ns.Data.polestarRoutes={{["revision"]="b753c783be39ccf9c91a94b1bfcb67ce01932d52",["source"]="Polestar GPL-3.0; simulation-derived Forever route",["zone"]=2652,["id"]="polestar:forever/40-50/shendralas",["next"]="polestar:forever/horde/40-50/03-feralas",["min"]=45,["availability"]="source-listed",["name"]="Shen'dralas (45-47)",["category"]="Leveling",["max"]=47,["zoneName"]="Shen'dralas",["refreshRevision"]="forever-20261117-b753c783",["steps"]={{["detail"]="New in Forever: this guide follows what players did in Shen'dralas. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nShen'dralas lies south of Desolace, through the Valley of Bones, and has no flight path of its own. From Camp Mojache ride north-west on the road past Dire Maul and on north into Desolace: the road comes out on Desolace's southern edge.",["goals"]={{["map"]=1443,["x"]=0.43,["sourceRouteConditions"]=true,["y"]=0.96,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:1:1",["t"]="goto",["text"]="Desolace, where the road from Feralas comes in",["soloWhen"]={{["name"]="Feralas",["k"]="zone",["area"]=357}}}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:1",["text"]="North into Desolace",["only"]={["factions"]={"Horde"}},["soloWhen"]={{["name"]="Feralas",["k"]="zone",["area"]=357}}},{["detail"]="New in Forever: this guide follows what players did in Shen'dralas. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nShen'dralas lies south of Desolace, through the Valley of Bones, and has no flight path of its own. Its quests are for levels 41-45. Coming from the Eastern Kingdoms, take the zeppelin to Orgrimmar first (from Grom'gol or the Undercity).",["goals"]={{["map"]=1454,["x"]=0.45299999999999996,["sourceRouteConditions"]=true,["y"]=0.637,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:2:1",["t"]="goto",["text"]="Orgrimmar flight master",["soloWhen"]={{["neg"]=true,["name"]="Shen'dralas",["k"]="zone",["area"]=16651},{["neg"]=true,["name"]="Desolace",["k"]="zone",["area"]=405},{["neg"]=true,["name"]="Feralas",["k"]="zone",["area"]=357}}},{["area"]=2408,["sourceRouteConditions"]=true,["location"]="Shadowprey Village",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:2:2",["t"]="fly",["node"]=38,["soloWhen"]={{["neg"]=true,["name"]="Shen'dralas",["k"]="zone",["area"]=16651},{["neg"]=true,["name"]="Desolace",["k"]="zone",["area"]=405},{["neg"]=true,["name"]="Feralas",["k"]="zone",["area"]=357}}}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:2",["text"]="Fly to Shadowprey Village",["only"]={["factions"]={"Horde"}},["soloWhen"]={{["neg"]=true,["name"]="Shen'dralas",["k"]="zone",["area"]=16651},{["neg"]=true,["name"]="Desolace",["k"]="zone",["area"]=405},{["neg"]=true,["name"]="Feralas",["k"]="zone",["area"]=357}}},{["detail"]="New in Forever: this guide follows what players did in Shen'dralas. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nShen'dralas lies south of Desolace, through the Valley of Bones, and has no flight path of its own. Its quests are for levels 41-45. Coming from the Eastern Kingdoms, take the boat from Menethil Harbor to Theramore first.",["goals"]={{["area"]=608,["sourceRouteConditions"]=true,["location"]="Nijel's Point",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:3:1",["t"]="fly",["node"]=37,["soloWhen"]={{["neg"]=true,["name"]="Shen'dralas",["k"]="zone",["area"]=16651},{["neg"]=true,["name"]="Desolace",["k"]="zone",["area"]=405}}}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:3",["text"]="Fly to Nijel's Point",["only"]={["factions"]={"Alliance"}},["soloWhen"]={{["neg"]=true,["name"]="Shen'dralas",["k"]="zone",["area"]=16651},{["neg"]=true,["name"]="Desolace",["k"]="zone",["area"]=405}}},{["detail"]="Ride east along Desolace's southern edge (from Shadowprey Village: past Gelkis Village): the Valley of Bones opens there into Shen'dralas.",["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:4:1",["t"]="goto",["soloWhen"]={{["neg"]=true,["name"]="Shen'dralas",["k"]="zone",["area"]=16651}},["y"]=0.22399999999999998,["x"]=0.212,["location"]="Shen'dralas",["area"]=16651}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:4",["text"]="Into the Valley of Bones",["only"]={["factions"]={"Horde"}},["soloWhen"]={{["neg"]=true,["name"]="Shen'dralas",["k"]="zone",["area"]=16651}}},{["detail"]="Ride south from Nijel's Point down the road through eastern Desolace to Magram Village: just past its western edge the path climbs into the Valley of Bones and Shen'dralas.",["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:5:1",["t"]="goto",["soloWhen"]={{["neg"]=true,["name"]="Shen'dralas",["k"]="zone",["area"]=16651}},["y"]=0.057999999999999996,["x"]=0.33,["location"]="Shen'dralas",["area"]=16651}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:5",["text"]="Into the Valley of Bones",["only"]={["factions"]={"Alliance"}},["soloWhen"]={{["neg"]=true,["name"]="Shen'dralas",["k"]="zone",["area"]=16651}}},{["goals"]={{["map"]=2652,["itemName"]="Tattered Journal",["sourceRouteConditions"]=true,["fromId"]=253272,["t"]="collect",["y"]=0.051,["x"]=0.3114,["item"]=260347,["lvl"]=43,["from"]="Magram Necromancer",["spread"]=true,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:6:1"},{["sourceRouteConditions"]=true,["itemName"]="Tattered Journal",["title"]="Tattered Journal",["item"]=260347,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:6:2",["t"]="accept",["quest"]=93644,["qlvl"]=45}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:6",["text"]="The Valley of Bones: a Tattered Journal",["sourceRouteConditions"]=true,["detail"]="New in Forever: if a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nThe Outcast Necromancers and the Magram Necromancers of the valley drop a Tattered Journal whose writer lives in Shen'dralas: players got it within a few kills. The Magram centaurs leave you be until you attack; the Magram Necrokhans among them (level 45) are elites: leave them be.\nThe Gelkis and Magram centaurs have Valley of Bones quest chains of their own, worth about 20,000 to 30,000 more experience, but each chain asks for Honored with its clan. The two clans are rivals, so work for one of them: the Gelkis and Magram Centaur Reputation guide, under Reputation, shows how."},{["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:7:1",["t"]="accept",["y"]=0.3436,["x"]=0.4366,["title"]="Strange Pylons",["objName"]="Shen'dralar Pylon",["qlvl"]=43,["quest"]=92914,["object"]=577959}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:7",["text"]="The western pylon",["sourceRouteConditions"]=true,["detail"]="East through the valley to the strange crystal on its pedestal: clicking it starts Strange Pylons. The Decrepit Pylon Protectors (levels 42-43) around it are the mana elementals that guard it. Corpsefeeders (level 45, elite) roam the valley east of here."},{["goals"]={{["map"]=2652,["x"]=0.732,["sourceRouteConditions"]=true,["r"]=15,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:8:1",["t"]="goto",["y"]=0.23199999999999998,["text"]="the eastern pylon"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:8",["text"]="Bristleback Retreat: the eastern pylon",["sourceRouteConditions"]=true,["detail"]="East along the valley road to the quilboar of Bristleback Retreat: the second pylon stands at the eastern end of their camp. A Corpsefeeder (level 45, elite) walks this road: let it pass. The Bristlebacks (levels 42-43) attack on sight; Kog'thug the Brave (level 43, elite) and his bodyguards hold the south side of the camp."},{["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:9:1",["t"]="complete",["objs"]={{["count"]=1,["text"]="Western pylon found"},{["count"]=1,["text"]="Eastern pylon found"},{["count"]=1,["text"]="Temple pylon found"}},["y"]=0.767,["x"]=0.47600000000000003,["title"]="Strange Pylons",["quest"]=92914}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:9",["text"]="The temple of Shen'dralas: the third pylon",["sourceRouteConditions"]=true,["detail"]="South to the Shen'dralar temple at the zone's heart, keeping west of Kog'thug's bodyguards: the third pylon stands inside. The temple's guards are neutral: leave them be."},{["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:10:1",["t"]="turnin",["npc"]=253471,["npcName"]="Mordent Evenshade",["x"]=0.3517,["title"]="Tattered Journal",["quest"]=93644,["y"]=0.4661},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:10:2",["t"]="turnin",["npc"]=253471,["npcName"]="Mordent Evenshade",["x"]=0.3517,["title"]="Strange Pylons",["quest"]=92914,["y"]=0.4661},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:10:3",["t"]="accept",["npc"]=253471,["npcName"]="Mordent Evenshade",["x"]=0.3517,["title"]="Fragments of the Pylons",["pre"]={92914},["y"]=0.4661,["quest"]=96010,["qlvl"]=41}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:10",["text"]="Evenshade's Overlook",["sourceRouteConditions"]=true,["detail"]="North-west from the temple to Mordent Evenshade's camp on the overlook, beside the spirit healer: the Tattered Journal is his, and he wants to hear about the pylons."},{["goals"]={{["map"]=1443,["x"]=0.64,["sourceRouteConditions"]=true,["location"]="Desolace",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:11:1",["t"]="goto",["y"]=0.804,["area"]=405}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:11",["text"]="North into Desolace",["sourceRouteConditions"]=true,["detail"]="Mordent Evenshade wants a fragment and a shard of the pylons back from Desolace's two centaur villages: Magram Village lies just beyond the valley's northern way out.\nCareful: if you have killed Magram or Gelkis centaurs, that clan's guards may attack you when you walk into its village."},{["goals"]={{["map"]=1443,["itemName"]="Pylon Fragment",["oi"]=1,["fromId"]=607122,["t"]="collect",["title"]="Fragments of the Pylons",["fromKind"]="object",["y"]=0.792,["x"]=0.6809999999999999,["count"]=1,["from"]="Pylon Fragment",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:12:1",["item"]=255656,["quest"]=96010,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:12",["text"]="Magram Village",["sourceRouteConditions"]=true,["detail"]="The Pylon Fragment lies at the western edge of the village; Magram Guardians (levels 39-41) watch over it."},{["goals"]={{["map"]=1443,["itemName"]="Pylon Shard",["oi"]=2,["fromId"]=607123,["t"]="collect",["title"]="Fragments of the Pylons",["fromKind"]="object",["y"]=0.856,["x"]=0.361,["count"]=1,["from"]="Pylon Shard",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:13:1",["item"]=255657,["quest"]=96010,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:13",["text"]="Gelkis Village",["sourceRouteConditions"]=true,["detail"]="West along Desolace's southern edge to Gelkis Village: the Pylon Shard lies at its southern end, watched by Gelkis Guardians (levels 39-41)."},{["goals"]={{["map"]=2652,["x"]=0.212,["sourceRouteConditions"]=true,["location"]="Shen'dralas",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:14:1",["t"]="goto",["y"]=0.22399999999999998,["area"]=16651}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:14",["text"]="Back into the Valley of Bones",["sourceRouteConditions"]=true,["detail"]="East again along Desolace's southern edge: the Valley of Bones opens into Shen'dralas."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:15",["text"]="Evenshade's Overlook",["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:15:1",["t"]="turnin",["npc"]=253471,["npcName"]="Mordent Evenshade",["x"]=0.3517,["title"]="Fragments of the Pylons",["quest"]=96010,["y"]=0.4661},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:15:2",["t"]="accept",["npc"]=253471,["npcName"]="Mordent Evenshade",["x"]=0.3517,["title"]="Powering the Pylons",["pre"]={96010},["y"]=0.4661,["quest"]=96018,["qlvl"]=43}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=2652,["itemName"]="Mana Sieve",["sourceRouteConditions"]=true,["fromId"]=584729,["t"]="collect",["y"]=0.782,["x"]=0.45899999999999996,["item"]=255662,["from"]="Mana Sieve",["fromKind"]="object",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:16:1"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:16",["text"]="The temple: the Mana Sieve",["sourceRouteConditions"]=true,["detail"]="Mordent Evenshade sends you for the Mana Sieve, kept inside the temple beside Historian Biraxas. Powering the Pylons asks you to gather mana with the Sieve before you repair the pylons: with it in your bags you can handle the Unstable Mana Rifts, the floating sparks of mana all along the road north."},{["goals"]={{["map"]=2652,["note"]="Decrepit Pylon Protector, then Repair and Recharge Pylon on it",["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:17:1",["t"]="kill",["npc"]=252711,["y"]=0.35590000000000005,["x"]=0.4397,["title"]="Powering the Pylons",["lvl"]=43,["target"]="Decrepit Pylon Protector",["count"]=1,["quest"]=96018,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:17",["text"]="The western pylon: repair it",["sourceRouteConditions"]=true,["detail"]="North up the road to the first pylon, gathering mana from the Unstable Mana Rifts on the way. Decrepit Pylon Protectors guard it: kill one beside the pylon, then use Repair and Recharge Pylon on it, as players did to repair it.\nCareful: the pylon stands at the edge of the Valley of Bones, where Magram Necrokhans and Corpsefeeders (elites, level 45) walk, and Nascent Pylon Protectors (elites, 43) wander the road. Pull the Decrepit Pylon Protectors away from them before you repair it."},{["goals"]={{["map"]=2652,["note"]="Decrepit Pylon Protector, then Repair and Recharge Pylon on it",["oi"]=3,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:18:1",["t"]="kill",["npc"]=252711,["y"]=0.2391,["x"]=0.7340000000000001,["title"]="Powering the Pylons",["lvl"]=43,["target"]="Decrepit Pylon Protector",["count"]=1,["quest"]=96018,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:18",["text"]="Bristleback Retreat: repair the eastern pylon",["sourceRouteConditions"]=true,["detail"]="East along the valley road to the eastern pylon and repair it the same way, a Decrepit Pylon Protector first, coming in from the west: Kog'thug the Brave (level 43, elite) and his bodyguards hold the south side of the quilboar camp, and a Corpsefeeder (level 45, elite) walks the road."},{["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:19:1",["t"]="turnin",["npc"]=253471,["npcName"]="Mordent Evenshade",["x"]=0.3517,["title"]="Powering the Pylons",["quest"]=96018,["y"]=0.4661},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:19:2",["t"]="accept",["npc"]=253471,["npcName"]="Mordent Evenshade",["x"]=0.3517,["title"]="A Brief History Lesson",["pre"]={96018},["y"]=0.4661,["quest"]=93016,["qlvl"]=43},{["map"]=2652,["note"]="Mordent Evenshade: hear him out",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:19:3",["t"]="talk",["npc"]=253471,["npcName"]="Mordent Evenshade",["x"]=0.3517,["title"]="A Brief History Lesson",["y"]=0.4661,["quest"]=93016,["sourceRouteConditions"]=true},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:19:4",["t"]="turnin",["npc"]=253471,["npcName"]="Mordent Evenshade",["x"]=0.3517,["title"]="A Brief History Lesson",["quest"]=93016,["y"]=0.4661},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:19:5",["t"]="accept",["npc"]=253471,["y"]=0.4661,["x"]=0.3517,["title"]="Meeting the Magister",["npcName"]="Mordent Evenshade",["pre"]={93016},["qlvl"]=43,["quest"]=93394,["minLevel"]=40}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:19",["text"]="Evenshade's Overlook",["sourceRouteConditions"]=true,["detail"]="Back west along the valley road and south to Mordent Evenshade. A Brief History Lesson asks you to hear him out: talk to him once more, then hand it in."},{["goals"]={{["itemName"]="Partially Digested Collar",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:20:1",["t"]="accept",["soloWhen"]={{["item"]=259461,["k"]="has",["n"]=1}},["title"]="Partially Digested Collar",["qlvl"]=45,["quest"]=93568,["item"]=259461},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:20:2",["t"]="turnin",["npc"]=255385,["soloWhen"]={{["item"]=259461,["k"]="has",["n"]=1}},["npcName"]="Liranne",["x"]=0.4746,["title"]="Partially Digested Collar",["quest"]=93568,["y"]=0.6563}},["detail"]="A Prowler gave up a Partially Digested Collar: Liranne, north of the temple, knows whose it was.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:20",["text"]="Liranne",["sourceRouteConditions"]=true,["soloWhen"]={{["item"]=259461,["k"]="has",["n"]=1}}},{["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:21:1",["t"]="turnin",["npc"]=254656,["npcName"]="Magister Kirandis",["x"]=0.47369999999999995,["title"]="Meeting the Magister",["quest"]=93394,["y"]=0.7646},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:21:2",["t"]="accept",["npc"]=254578,["npcName"]="Mithera",["x"]=0.5332,["title"]="Forlorn Gardens",["pre"]={93394},["y"]=0.7602,["quest"]=93341,["qlvl"]=43}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:21",["text"]="The temple: Magister Kirandis",["sourceRouteConditions"]=true,["detail"]="Magister Kirandis waits inside the temple. Then Mithera, on the temple's eastern side, has work in the Forlorn Gardens."},{["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:22:1",["t"]="complete",["objs"]={{["count"]=1,["text"]="Pedestal examined"}},["y"]=0.797,["x"]=0.703,["title"]="Forlorn Gardens",["quest"]=93341}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:22",["text"]="The Forlorn Gardens: the pedestal",["sourceRouteConditions"]=true,["detail"]="East of the temple the Forlorn Gardens have run wild, and their plants attack on sight. Examine the pedestal at the gardens' southern end."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:23",["text"]="Mithera",["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:23:1",["t"]="turnin",["npc"]=254578,["npcName"]="Mithera",["x"]=0.5332,["title"]="Forlorn Gardens",["quest"]=93341,["y"]=0.7602},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:23:2",["t"]="accept",["npc"]=254578,["npcName"]="Mithera",["x"]=0.5332,["title"]="What They've Done to My Peonies",["pre"]={93341},["y"]=0.7602,["quest"]=93362,["qlvl"]=43},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:23:3",["t"]="accept",["npc"]=254578,["npcName"]="Mithera",["x"]=0.5332,["title"]="Word of the Woods",["pre"]={93341},["y"]=0.7602,["quest"]=93594,["qlvl"]=43}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=2652,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:24:1",["t"]="kill",["npc"]=254566,["y"]=0.7451000000000001,["x"]=0.5111,["title"]="What They've Done to My Peonies",["lvl"]=42,["target"]="Rowdy Rose",["count"]=4,["quest"]=93362,["sourceRouteConditions"]=true},{["map"]=2652,["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:24:2",["t"]="kill",["npc"]=254567,["y"]=0.7558,["x"]=0.642,["title"]="What They've Done to My Peonies",["lvl"]=42,["target"]="Terrible Tulip",["count"]=4,["quest"]=93362,["sourceRouteConditions"]=true},{["map"]=2652,["oi"]=3,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:24:3",["t"]="kill",["npc"]=254572,["y"]=0.731,["x"]=0.6564,["title"]="What They've Done to My Peonies",["lvl"]=42,["target"]="Malevolent Marigold",["count"]=20,["quest"]=93362,["sourceRouteConditions"]=true},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:24:4",["t"]="turnin",["npc"]=254674,["npcName"]="Woodwyrd",["x"]=0.6966,["title"]="Word of the Woods",["quest"]=93594,["y"]=0.7178}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:24",["text"]="The Forlorn Gardens",["sourceRouteConditions"]=true,["detail"]="Rowdy Roses and Terrible Tulips grow all over the gardens; the Malevolent Marigolds keep to the northern part. Woodwyrd, the treant in the middle of the gardens, has a request of his own that needs water from Maraudon, a dungeon: this guide leaves it.\nThe Shen'dralar who wander the gardens are neutral, like the temple's guards: leave them be and pull the flowers away from them. Careful: Nascent Pylon Protectors (elites, 43) wander the zone's middle, the gardens too: keep clear of them."},{["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:25:1",["t"]="turnin",["npc"]=254578,["npcName"]="Mithera",["x"]=0.5332,["title"]="What They've Done to My Peonies",["quest"]=93362,["y"]=0.7602},{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:25:2",["t"]="accept",["npc"]=255486,["npcName"]="Historian Biraxas",["x"]=0.46,["title"]="A Heart of Crystal",["pre"]={93394},["y"]=0.7822,["quest"]=99257,["qlvl"]=43}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:25",["text"]="Mithera",["sourceRouteConditions"]=true,["detail"]="Historian Biraxas, inside the temple, has a task for you now that you have met Magister Kirandis: the heart of a Decrepit Pylon Protector (42-43, not elite), a short ride back up the road north."},{["goals"]={{["map"]=2652,["itemName"]="Depleted Crystal Heart",["oi"]=1,["spread"]=true,["fromId"]=252711,["t"]="collect",["fromKind"]="npc",["lvl"]=43,["y"]=0.6593000000000001,["x"]=0.4704,["title"]="A Heart of Crystal",["from"]="Decrepit Pylon Protector",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:26:1",["item"]=286647,["quest"]=99257,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:26",["text"]="A Heart of Crystal",["sourceRouteConditions"]=true,["detail"]="The nearest Decrepit Pylon Protectors stand by the road north, from the middle of the zone up to the western pylon, and around Mordent Evenshade's overlook: one of them carries the heart Biraxas wants."},{["goals"]={{["map"]=2652,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:27:1",["t"]="turnin",["npc"]=255486,["npcName"]="Historian Biraxas",["x"]=0.46,["title"]="A Heart of Crystal",["quest"]=99257,["y"]=0.7822}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:27",["text"]="Historian Biraxas",["sourceRouteConditions"]=true,["detail"]="Shen'dralas is done: ride back north through the Valley of Bones; the next step says where your route goes on from there."},{["goals"]={{["map"]=1443,["x"]=0.21559999999999999,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:28:1",["t"]="goto",["y"]=0.7404000000000001,["text"]="Shadowprey Village flight master"},{["sourceRouteConditions"]=true,["location"]="Orgrimmar",["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:28:2",["t"]="fly",["node"]=23,["area"]=1637}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:28",["text"]="Shadowprey Village",["only"]={["factions"]={"Horde"}},["detail"]="Shen'dralas is done. Ride back north through the Valley of Bones and west along Desolace's southern edge to Shadowprey Village: the next guide picks up in Orgrimmar, with the Feralas guide's hand-ins. Your hearthstone is bound at Camp Mojache: if it is ready, hearth there and fly to Orgrimmar from Camp Mojache instead."},{["goals"]={{["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:goal:29:1",["text"]="Shen'dralas is done. Your Feralas guide picks up from here: ride back north through the Valley of Bones, west along Desolace's southern edge and south into Feralas, to the dock on the Forgotten Coast where the boat crosses to Feathermoon Stronghold.",["sourceRouteConditions"]=true,["t"]="note"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/40-50/shendralas:step:29",["text"]="Back to your route",["only"]={["factions"]={"Alliance"}},["sourceRouteConditions"]=true}}},{["revision"]="b753c783be39ccf9c91a94b1bfcb67ce01932d52",["source"]="Polestar GPL-3.0; simulation-derived Forever route",["zone"]=1450,["id"]="polestar:forever/class/druid/aquatic-form",["zoneName"]="Moonglade",["min"]=16,["availability"]="source-listed",["name"]="Aquatic Form (16-22)",["category"]="Class",["max"]=22,["classes"]={"DRUID"},["refreshRevision"]="forever-20261117-b753c783",["steps"]={{["detail"]="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. Skyborne: cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up.",["goals"]={{["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:1:1",["level"]=16,["t"]="level",["soloWhen"]={{["neg"]=true,["k"]="onquest",["q"]={26}},{["neg"]=true,["k"]="turnedin",["q"]=26}}},{["map"]=1457,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:1:2",["t"]="goto",["soloWhen"]={{["neg"]=true,["k"]="onquest",["q"]={26}},{["neg"]=true,["k"]="turnedin",["q"]=26}},["y"]=0.11599999999999999,["x"]=0.358,["text"]="Cenarion Enclave",["area"]=1658}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:1",["text"]="Cenarion Enclave",["only"]={["races"]={"NightElf","Skyborne"},["factions"]={"Alliance"}},["soloWhen"]={{["neg"]=true,["k"]="onquest",["q"]={26}},{["neg"]=true,["k"]="turnedin",["q"]=26}}},{["goals"]={{["id"]="forever/class/druid/aquatic-form:1:1",["level"]=16,["sourceRouteConditions"]=true,["t"]="level"},{["map"]=1457,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:1:2",["t"]="accept",["npc"]=4217,["npcName"]="Mathrengyl Bearwalker",["x"]=0.35369999999999996,["title"]="A Lesson to Learn",["y"]=0.084,["qlvl"]=16,["quest"]=26,["minLevel"]=16}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:2",["text"]="A Lesson to Learn",["only"]={["races"]={"NightElf","Skyborne"},["factions"]={"Alliance"}},["detail"]="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. Skyborne: cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up."},{["goals"]={{["map"]=1450,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:2:1",["t"]="turnin",["npc"]=11802,["npcName"]="Dendrite Starblaze",["x"]=0.5621,["title"]="A Lesson to Learn",["quest"]=26,["y"]=0.3064},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:3:2",["t"]="accept",["npc"]=11802,["y"]=0.3064,["npcName"]="Dendrite Starblaze",["x"]=0.5621,["limit"]=1800,["title"]="Trial of the Lake",["pre"]={26},["qlvl"]=16,["quest"]=29,["minLevel"]=16},{["map"]=1450,["itemName"]="Shrine Bauble",["sourceRouteConditions"]=true,["fromId"]=177785,["t"]="collect",["y"]=0.46399999999999997,["x"]=0.547,["item"]=15877,["from"]="Bauble Container",["note"]="Shrine Bauble, from a Bauble Container in the lake",["count"]=1,["fromKind"]="object",["id"]="forever/class/druid/aquatic-form:2:3"},{["map"]=1450,["itemName"]="Shrine Bauble",["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:2:4",["t"]="use",["y"]=0.414,["x"]=0.36,["item"]=15877,["note"]="At the Shrine of Remulos"},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:3:5",["t"]="complete",["objs"]={{["count"]=1,["text"]="Shrine Of Remulos"}},["y"]=0.414,["x"]=0.36,["title"]="Trial of the Lake",["quest"]=29},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:2:6",["t"]="turnin",["npc"]=11799,["npcName"]="Tajarri",["x"]=0.3652,["title"]="Trial of the Lake",["quest"]=29,["y"]=0.401},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:2:7",["t"]="accept",["npc"]=11799,["y"]=0.401,["x"]=0.3652,["title"]="Trial of the Sea Lion",["npcName"]="Tajarri",["pre"]={29},["qlvl"]=16,["quest"]=272,["minLevel"]=16}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:3",["text"]="Trial of the Lake",["only"]={["races"]={"NightElf","Skyborne"},["factions"]={"Alliance"}},["detail"]="Cast Teleport: Moonglade to get here: Dendrite Starblaze stands upstairs in the building beside where you land. Trial of the Lake runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until Tajarri has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of Lake Elune'ara below Nighthaven, often near the bubbling fissures (the Bubbly Fissure in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the Shrine Bauble is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the Shrine of Remulos on the north-west shore, use it inside the shrine grounds and speak to Tajarri by the tree."},{["goals"]={{["sourceRouteConditions"]=true,["location"]="Auberdine",["id"]="forever/class/druid/aquatic-form:3:1",["t"]="fly",["node"]=26,["area"]=442},{["map"]=1439,["itemName"]="Half Pendant of Aquatic Agility",["sourceRouteConditions"]=true,["fromId"]=177792,["t"]="collect",["y"]=0.11320000000000001,["x"]=0.48869999999999997,["item"]=15883,["from"]="Strange Lockbox",["note"]="Half Pendant of Aquatic Agility, from the Strange Lockbox",["count"]=1,["fromKind"]="object",["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:4:2"}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:4",["text"]="Half Pendant of Aquatic Agility",["only"]={["races"]={"NightElf","Skyborne"},["factions"]={"Alliance"}},["detail"]="Fly from Nighthaven to Auberdine. The Strange Lockbox lies far out on the sea floor off the north coast, between tall rocks west of where the Cliffspring River reaches the sea: it cannot be seen from the east side of the rocks. Watch your breath and the Darkshore Threshers; fight above water."},{["goals"]={{["sourceRouteConditions"]=true,["location"]="Sentinel Hill",["id"]="forever/class/druid/aquatic-form:4:1",["t"]="fly",["node"]=4,["area"]=108},{["map"]=1436,["itemName"]="Half Pendant of Aquatic Endurance",["sourceRouteConditions"]=true,["fromId"]=177790,["t"]="collect",["y"]=0.3318,["x"]=0.1794,["item"]=15882,["from"]="Strange Lockbox",["note"]="Half Pendant of Aquatic Endurance, from the Strange Lockbox",["count"]=1,["fromKind"]="object",["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:5:2"}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:5",["text"]="Half Pendant of Aquatic Endurance",["only"]={["races"]={"NightElf","Skyborne"},["factions"]={"Alliance"}},["detail"]="Take the boat from Auberdine to Stormwind and fly to Sentinel Hill. Head west to the coast: the Strange Lockbox lies far out on the sea floor beside a bubbling fissure (air), west of a sunken anchor. Sharks roam here; do not swim on past the wreck beyond it, the deep water brings fatigue."},{["goals"]={{["map"]=1450,["itemName"]="Pendant of the Sea Lion",["oi"]=1,["note"]="Pendant of the Sea Lion: join the halves at the shrine",["fromId"]=15885,["t"]="collect",["fromKind"]="object",["item"]=15885,["y"]=0.4142,["x"]=0.36,["title"]="Trial of the Sea Lion",["from"]="Shrine Of Remulos",["id"]="forever/class/druid/aquatic-form:5:1",["count"]=1,["quest"]=272,["sourceRouteConditions"]=true},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:5:2",["t"]="turnin",["npc"]=11802,["npcName"]="Dendrite Starblaze",["x"]=0.5621,["title"]="Trial of the Sea Lion",["quest"]=272,["y"]=0.3064},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:5:3",["t"]="accept",["npc"]=11802,["y"]=0.3064,["x"]=0.5621,["title"]="Aquatic Form",["npcName"]="Dendrite Starblaze",["pre"]={272},["qlvl"]=16,["quest"]=5061,["minLevel"]=16},{["sourceRouteConditions"]=true,["location"]="Rut'theran Village",["id"]="forever/class/druid/aquatic-form:5:4",["t"]="fly",["node"]=27,["area"]=702}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:6",["text"]="Pendant of the Sea Lion",["only"]={["races"]={"NightElf","Skyborne"},["factions"]={"Alliance"}},["detail"]="Cast Teleport: Moonglade. With both halves in your bags, stand by the Shrine of Remulos on the north-west shore and use the Half Pendant of Aquatic Agility to join them, then cast Teleport: Moonglade again (it works inside Moonglade) to land by Dendrite Starblaze. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Afterwards Silva Fil'naveth, in the middle of Nighthaven, flies druids straight to Rut'theran Village."},{["detail"]="Take the portal up to Mathrengyl Bearwalker in the Cenarion Enclave. Aquatic Form: swim fast and breathe underwater.",["goals"]={{["map"]=1457,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:7:1",["t"]="goto",["soloWhen"]={{["neg"]=true,["k"]="turnedin",["q"]=5061}},["y"]=0.11599999999999999,["x"]=0.358,["text"]="Cenarion Enclave",["area"]=1658}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:7",["text"]="Cenarion Enclave",["only"]={["races"]={"NightElf","Skyborne"},["factions"]={"Alliance"}},["soloWhen"]={{["neg"]=true,["k"]="turnedin",["q"]=5061}}},{["goals"]={{["map"]=1457,["note"]="Mathrengyl Bearwalker: Aquatic Form",["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:6:1",["t"]="turnin",["npc"]=4217,["npcName"]="Mathrengyl Bearwalker",["x"]=0.35369999999999996,["title"]="Aquatic Form",["rewards"]={["items"]={{["item"]=16608,["itemName"]="Aquarius Belt"},{["item"]=263411,["itemName"]="Idol of Shifting Tides"}}},["quest"]=5061,["y"]=0.084}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:8",["text"]="Aquatic Form",["only"]={["races"]={"NightElf","Skyborne"},["factions"]={"Alliance"}},["detail"]="Take the portal up to Mathrengyl Bearwalker in the Cenarion Enclave. Aquatic Form: swim fast and breathe underwater."},{["goals"]={{["id"]="forever/class/druid/aquatic-form:7:1",["level"]=16,["sourceRouteConditions"]=true,["t"]="level"},{["map"]=1456,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:7:2",["t"]="accept",["npc"]=3033,["npcName"]="Turak Runetotem",["x"]=0.7648,["title"]="A Lesson to Learn",["y"]=0.2722,["qlvl"]=16,["quest"]=27,["minLevel"]=16}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:9",["text"]="A Lesson to Learn",["only"]={["races"]={"Tauren","Skyborne"},["factions"]={"Horde"}},["detail"]="Turak Runetotem stands in the druids' hut on Elder Rise."},{["goals"]={{["map"]=1450,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:8:1",["t"]="turnin",["npc"]=11802,["npcName"]="Dendrite Starblaze",["x"]=0.5621,["title"]="A Lesson to Learn",["quest"]=27,["y"]=0.3064},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:10:2",["t"]="accept",["npc"]=11802,["y"]=0.3064,["npcName"]="Dendrite Starblaze",["x"]=0.5621,["limit"]=1800,["title"]="Trial of the Lake",["pre"]={27},["qlvl"]=16,["quest"]=28,["minLevel"]=16},{["map"]=1450,["itemName"]="Shrine Bauble",["sourceRouteConditions"]=true,["fromId"]=177785,["t"]="collect",["y"]=0.46399999999999997,["x"]=0.547,["item"]=15877,["from"]="Bauble Container",["note"]="Shrine Bauble, from a Bauble Container in the lake",["count"]=1,["fromKind"]="object",["id"]="forever/class/druid/aquatic-form:8:3"},{["map"]=1450,["itemName"]="Shrine Bauble",["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:8:4",["t"]="use",["y"]=0.414,["x"]=0.36,["item"]=15877,["note"]="At the Shrine of Remulos"},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:10:5",["t"]="complete",["objs"]={{["count"]=1,["text"]="Shrine Of Remulos"}},["y"]=0.414,["x"]=0.36,["title"]="Trial of the Lake",["quest"]=28},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:8:6",["t"]="turnin",["npc"]=11799,["npcName"]="Tajarri",["x"]=0.3652,["title"]="Trial of the Lake",["quest"]=28,["y"]=0.401},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:8:7",["t"]="accept",["npc"]=11799,["y"]=0.401,["x"]=0.3652,["title"]="Trial of the Sea Lion",["npcName"]="Tajarri",["pre"]={28},["qlvl"]=16,["quest"]=30,["minLevel"]=16}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:10",["text"]="Trial of the Lake",["only"]={["races"]={"Tauren","Skyborne"},["factions"]={"Horde"}},["detail"]="Cast Teleport: Moonglade to get here: Dendrite Starblaze stands upstairs in the building beside where you land. Trial of the Lake runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until Tajarri has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of Lake Elune'ara below Nighthaven, often near the bubbling fissures (the Bubbly Fissure in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the Shrine Bauble is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the Shrine of Remulos on the north-west shore, use it inside the shrine grounds and speak to Tajarri by the tree."},{["goals"]={{["sourceRouteConditions"]=true,["location"]="Thunder Bluff",["id"]="forever/class/druid/aquatic-form:11:4",["t"]="fly",["node"]=22,["area"]=1638},{["sourceRouteConditions"]=true,["location"]="Orgrimmar",["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:11:2",["t"]="fly",["node"]=23,["area"]=1637},{["map"]=1413,["itemName"]="Half Pendant of Aquatic Agility",["sourceRouteConditions"]=true,["fromId"]=177794,["t"]="collect",["y"]=0.0832,["x"]=0.5667,["item"]=15883,["from"]="Strange Lockbox",["note"]="Half Pendant of Aquatic Agility, from the Strange Lockbox",["count"]=1,["fromKind"]="object",["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:11:3"}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:11",["text"]="Half Pendant of Aquatic Agility",["only"]={["races"]={"Tauren","Skyborne"},["factions"]={"Horde"}},["detail"]="Take Bunthen Plainswind's flight to Thunder Bluff and fly on to Orgrimmar. The Strange Lockbox lies underwater in the Sludge Fen pond, a short walk out of Orgrimmar's west gate, in front of a wooden wall. The Venture Co. there are quick to join a fight: come in from the west to avoid most of them."},{["goals"]={{["map"]=1411,["x"]=0.508,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:12:1",["text"]="Zeppelin to Undercity",["t"]="goto",["y"]=0.135}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:12",["text"]="Zeppelin to Undercity",["only"]={["races"]={"Tauren","Skyborne"},["factions"]={"Horde"}},["detail"]="Back through Orgrimmar to the zeppelin towers outside its main gate: the zeppelin to the Undercity lands in Tirisfal Glades, and Silverpine Forest is south of the Undercity."},{["goals"]={{["map"]=1421,["itemName"]="Half Pendant of Aquatic Endurance",["sourceRouteConditions"]=true,["fromId"]=177844,["t"]="collect",["y"]=0.292,["x"]=0.2956,["item"]=15882,["from"]="Strange Lockbox",["note"]="Half Pendant of Aquatic Endurance, from the Strange Lockbox",["count"]=1,["fromKind"]="object",["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:13:1"}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:13",["text"]="Half Pendant of Aquatic Endurance",["only"]={["races"]={"Tauren","Skyborne"},["factions"]={"Horde"}},["detail"]="The Strange Lockbox lies at the bottom of very deep water off the coast north-west of the Sepulcher, beside an air fissure where you can breathe: watch your breath on the way down. Then Teleport: Moonglade takes you straight back."},{["goals"]={{["map"]=1450,["itemName"]="Pendant of the Sea Lion",["oi"]=1,["note"]="Pendant of the Sea Lion: join the halves at the shrine",["fromId"]=15885,["t"]="collect",["fromKind"]="object",["item"]=15885,["y"]=0.4142,["x"]=0.36,["title"]="Trial of the Sea Lion",["from"]="Shrine Of Remulos",["id"]="forever/class/druid/aquatic-form:11:1",["count"]=1,["quest"]=30,["sourceRouteConditions"]=true},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:11:2",["t"]="turnin",["npc"]=11802,["npcName"]="Dendrite Starblaze",["x"]=0.5621,["title"]="Trial of the Sea Lion",["quest"]=30,["y"]=0.3064},{["map"]=1450,["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:11:3",["t"]="accept",["npc"]=11802,["y"]=0.3064,["x"]=0.5621,["title"]="Aquatic Form",["npcName"]="Dendrite Starblaze",["pre"]={30},["qlvl"]=16,["quest"]=31,["minLevel"]=16},{["sourceRouteConditions"]=true,["location"]="Thunder Bluff",["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:goal:14:4",["t"]="fly",["node"]=22,["area"]=1638}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:14",["text"]="Pendant of the Sea Lion",["only"]={["races"]={"Tauren","Skyborne"},["factions"]={"Horde"}},["detail"]="Cast Teleport: Moonglade. With both halves in your bags, stand by the Shrine of Remulos on the north-west shore and use the Half Pendant of Aquatic Agility to join them, then cast Teleport: Moonglade again (it works inside Moonglade) to land by Dendrite Starblaze. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Bunthen Plainswind flies druids to Thunder Bluff."},{["goals"]={{["map"]=1456,["note"]="Turak Runetotem: Aquatic Form",["sourceRouteConditions"]=true,["id"]="forever/class/druid/aquatic-form:12:1",["t"]="turnin",["npc"]=3033,["npcName"]="Turak Runetotem",["x"]=0.7648,["title"]="Aquatic Form",["rewards"]={["items"]={{["item"]=16608,["itemName"]="Aquarius Belt"},{["item"]=263411,["itemName"]="Idol of Shifting Tides"}}},["quest"]=31,["y"]=0.2722}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/aquatic-form:step:15",["text"]="Aquatic Form",["only"]={["races"]={"Tauren","Skyborne"},["factions"]={"Horde"}},["sourceRouteConditions"]=true}}},{["revision"]="b753c783be39ccf9c91a94b1bfcb67ce01932d52",["source"]="Polestar GPL-3.0; simulation-derived Forever route",["zone"]=1450,["id"]="polestar:forever/class/druid/bear-form",["zoneName"]="Moonglade",["min"]=10,["availability"]="source-listed",["name"]="Bear Form and Moonglade (10-12)",["category"]="Class",["max"]=12,["classes"]={"DRUID"},["refreshRevision"]="forever-20261117-b753c783",["steps"]={{["goals"]={{["id"]="forever/class/druid/bear-form:1:1",["level"]=10,["sourceRouteConditions"]=true,["t"]="level"},{["note"]="Kal, Dolanaar; Denatharion's and Theridran's letters lead to the same place",["sourceRouteConditions"]=true,["endNpcs"]={4217},["npc"]=3602,["npcName"]="Kal",["qlvl"]=10,["quest"]=5925,["map"]=1438,["optional"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/bear-form:goal:1:2",["t"]="accept",["xp"]=85,["closedBy"]={5921,5923,5924},["x"]=0.5595,["title"]="Heeding the Call",["y"]=0.6156,["minLevel"]=10}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/bear-form:step:1",["text"]="Heeding the Call",["only"]={["races"]={"NightElf"}},["detail"]="At 10 a druid's call reaches you: Kal in Dolanaar, Denatharion in Darnassus or Theridran in Stormwind. Any one of them sends you to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus."},{["detail"]="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab).",["goals"]={{["map"]=1457,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/bear-form:goal:2:1",["t"]="goto",["soloWhen"]={{["k"]="onquest",["q"]={5923,5924,5925}}},["y"]=0.11599999999999999,["x"]=0.358,["text"]="Cenarion Enclave",["area"]=1658}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/bear-form:step:2",["text"]="Cenarion Enclave",["only"]={["races"]={"NightElf"}},["soloWhen"]={{["k"]="onquest",["q"]={5923,5924,5925}}}},{["detail"]="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab).",["goals"]={{["map"]=1457,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/bear-form:goal:3:1",["t"]="goto",["soloWhen"]={{["neg"]=true,["k"]="onquest",["q"]={5921}},{["neg"]=true,["k"]="turnedin",["q"]=5921}},["y"]=0.11599999999999999,["x"]=0.358,["text"]="Cenarion Enclave",["area"]=1658}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/bear-form:step:3",["text"]="Cenarion Enclave",["only"]={["races"]={"NightElf"}},["soloWhen"]={{["neg"]=true,["k"]="onquest",["q"]={5921}},{["neg"]=true,["k"]="turnedin",["q"]=5921}}},{["goals"]={{["map"]=1457,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/bear-form:goal:4:1",["t"]="turnin",["npc"]=4217,["soloWhen"]={{["k"]="onquest",["q"]={5923}}},["npcName"]="Mathrengyl Bearwalker",["x"]=0.35369999999999996,["title"]="Heeding the Call",["quest"]=5923,["y"]=0.084}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/druid/bear-form:step:4",["text"]="Mathrengyl Bearwalker",["only"]={["races"]={"NightElf"}},["soloWhen"]={{