53,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/02-westfall:goal:22:5",["t"]="accept",["npc"]=6090,["y"]=0.5255,["npcName"]="Bartleby",["x"]=0.7676000000000001,["title"]="Beat Bartleby",["only"]={["races"]={"Human"}},["pre"]={1639,1678,1683},["qlvl"]=10,["quest"]=1640,["minLevel"]=10},{["map"]=1453,["note"]="Beat Bartleby",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/02-westfall:goal:22:6",["t"]="kill",["npc"]=6090,["y"]=0.5255,["x"]=0.7676000000000001,["title"]="Beat Bartleby",["target"]="Bartleby",["quest"]=1640,["only"]={["races"]={"Human"}},["sourceRouteConditions"]=true},{["map"]=1453,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/02-westfall:goal:22:7",["t"]="turnin",["npc"]=6090,["npcName"]="Bartleby",["x"]=0.7676000000000001,["title"]="Beat Bartleby",["only"]={["races"]={"Human"}},["quest"]=1640,["y"]=0.5255},{["map"]=1453,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/02-westfall:goal:22:8",["t"]="accept",["npc"]=6090,["y"]=0.5255,["npcName"]="Bartleby",["x"]=0.7676000000000001,["title"]="Bartleby's Mug",["only"]={["races"]={"Human"}},["pre"]={1640},["qlvl"]=10,["quest"]=1665,["minLevel"]=10},{["map"]=1453,["note"]="Harry Burlguard: Defensive Stance",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/02-westfall:goal:22:9",["t"]="turnin",["npc"]=6089,["npcName"]="Harry Burlguard",["x"]=0.7713,["title"]="Bartleby's Mug",["only"]={["races"]={"Human"}},["quest"]=1665,["y"]=0.5326}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/02-westfall:step:22",["text"]="Defensive Stance",["only"]={["classes"]={"WARRIOR"},["races"]={"Human"}},["detail"]="Ilsa Corbin trains warriors in Old Town, near Osric Strang's shop; the tram from Ironforge arrives in the Dwarven District, north of it.