,["fromAlsoId"]=2237,["fromId"]=2071,["fromAlso"]="Moonstalker Sire",["t"]="collect",["spread"]=true,["y"]=0.8136,["x"]=0.39890000000000003,["title"]="A Lost Master",["from"]="Moonstalker Matriarch",["note"]="Fine Moonstalker Pelts",["count"]=5,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:1"},{["map"]=1439,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:2",["t"]="accept",["npc"]=3584,["npcName"]="Therylune",["x"]=0.3864,["escort"]=true,["title"]="Therylune's Escape",["y"]=0.8733,["qlvl"]=18,["quest"]=945,["minLevel"]=10},{["note"]="Escort her out of the glaive; Therysil takes the turn-in in Ashenvale",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:3",["t"]="complete",["objs"]={{["count"]=1,["text"]="Escort Therylune away from the Master's Glaive"}},["title"]="Therylune's Escape",["carriedTo"]="forever/alliance/06-ashenvale",["quest"]=945,["escort"]=true},{["itemName"]="Book: The Powers Below",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:4",["t"]="accept",["note"]="Only if a Disciple or Thug dropped Book: The Powers Below: right-click it",["title"]="The Powers Below",["optional"]=true,["qlvl"]=18,["minLevel"]=10,["quest"]=968,["item"]=5352},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:5",["objs"]={{["count"]=1,["text"]="Enter the Master's Glaive"}},["title"]="The Master's Glaive",["startItemName"]="Phial of Scrying",["startItem"]=5251,["t"]="complete",["quest"]=944,["sourceRouteConditions"]=true},{["map"]=1439,["note"]="The Scrying Bowl",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:6",["t"]="turnin",["y"]=0.862,["x"]=0.386,["title"]="The Master's Glaive",["objName"]="Scrying Bowl",["quest"]=944,["object"]=10076},{["map"]=1439,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:7",["t"]="accept",["object"]=10076,["y"]=0.862,["x"]=0.386,["qlvl"]=17,["objName"]="Scrying Bowl",["pre"]={944},["minLevel"]=12,["quest"]=949,["title"]="The Twilight Camp"},{["map"]=1439,["note"]="The Twilight Tome",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:8",["t"]="turnin",["y"]=0.8604999999999999,["x"]=0.38539999999999996,["title"]="The Twilight Camp",["objName"]="Twilight Tome",["quest"]=949,["object"]=12666},{["map"]=1439,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:9",["t"]="accept",["object"]=12666,["y"]=0.8604999999999999,["x"]=0.38539999999999996,["qlvl"]=17,["objName"]="Twilight Tome",["pre"]={949},["minLevel"]=12,["quest"]=950,["title"]="Return to Onu"},{["map"]=1439,["note"]="The Twilight Tome, once it has The Twilight Camp",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:10",["t"]="accept",["object"]=12666,["y"]=0.8604999999999999,["x"]=0.38539999999999996,["qlvl"]=17,["objName"]="Twilight Tome",["pre"]={949},["minLevel"]=12,["quest"]=98042,["title"]="It's All Fun and Games Until..."},{["itemName"]="Peerless Eye",["sourceRouteConditions"]=true,["item"]=279279,["quest"]=98042,["map"]=1439,["oi"]=1,["fromAlsoId"]=2339,["fromId"]=2338,["fromAlso"]="Twilight Thug",["t"]="collect",["lvl"]=18,["y"]=0.8609,["x"]=0.3847,["title"]="It's All Fun and Games Until...",["from"]="Twilight Disciple",["note"]="Peerless Eye: Twilight Disciples and Thugs",["count"]=1,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:6:11"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:step:6",["text"]="The Master's Glaive",["sourceRouteConditions"]=true,["detail"]="Moonstalker Sires prowl the woods around the glaive. The Twilight Tome sits at the bottom of the crater; Therylune stands on its north side. For Onu's quest, use the Phial of Scrying at the bottom of the crater: it makes the Scrying Bowl, and you hand the quest in to the bowl."},{["goals"]={{["map"]=1439,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:7:1",["t"]="turnin",["npc"]=2917,["npcName"]="Prospector Remtravel",["x"]=0.35729999999999995,["title"]="The Absent Minded Prospector",["quest"]=729,["y"]=0.8370000000000001},{["map"]=1439,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:7:2",["t"]="accept",["npc"]=2917,["y"]=0.8370000000000001,["npcName"]="Prospector Remtravel",["x"]=0.35729999999999995,["escort"]=true,["title"]="The Absent Minded Prospector",["pre"]={729},["qlvl"]=20,["quest"]=731,["minLevel"]=15},{["escort"]=true,["title"]="The Absent Minded Prospector",["quest"]=731,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:7:3",["t"]="complete",["objs"]={{["count"]=1,["text"]="Escort Prospector Remtravel"}},["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:step:7",["text"]="Prospector Remtravel",["sourceRouteConditions"]=true,["detail"]="Remtravel's Excavation lies on the coast south of Murkdeep's beach. Protect the prospector while he searches for the fossil.\nCareful: Ambushers appear as he passes certain spots: a scout comes out from under the board ramp, and more scouts come out when he checks the tent."},{["goals"]={{["map"]=1439,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-darkshore-return:goal:8:1",["