=true,["y"]=0.7559999999999999,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-loch-modan:goal:25:1",["t"]="goto",["text"]="Algaz Station",["area"]=925}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-loch-modan:step:25",["text"]="The tunnel post",["sourceRouteConditions"]=true,["detail"]="West to the dwarven post at the tunnel to Dun Morogh."},{["goals"]={{["map"]=1432,["note"]="Captain Rugelfuss, inside",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-loch-modan:goal:26:1",["t"]="turnin",["npc"]=1092,["npcName"]="Captain Rugelfuss",["x"]=0.2323,["title"]="Banner of the Fallen",["quest"]=86585,["y"]=0.7368000000000001}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-loch-modan:step:26",["text"]="Captain Rugelfuss",["sourceRouteConditions"]=true,["detail"]="Captain Rugelfuss is inside the bunker at the tunnel post: go in by its door on the south-east side."},{["goals"]={{["map"]=1432,["x"]=0.33899999999999997,["sourceRouteConditions"]=true,["text"]="Thelsamar flight master",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-loch-modan:goal:27:1",["t"]="goto",["y"]=0.508,["soloWhen"]={{["name"]="Ironforge",["node"]=6,["k"]="taxi"}}},{["area"]=1537,["sourceRouteConditions"]=true,["location"]="Ironforge",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-loch-modan:goal:27:2",["t"]="fly",["node"]=6,["soloWhen"]={{["name"]="Ironforge",["node"]=6,["k"]="taxi"}}}},["detail"]="You have the Ironforge flight path: back north to Thelsamar's gryphons, quicker than walking through the tunnel and across Dun Morogh.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/03-loch-modan:step:27",["text"]="Fly to Ironforge",["sourceRouteConditions"]=true,["soloWhen"]={{["name"]="Ironforge",["node"]=6,["k"]="taxi"}}},{["goals"]={{["map"]=1426,["x"]=0.86,["sourceRouteConditions"]=true,["text"]="Into Dun Morogh