,["npc"]=415,["npcName"]="Verner Osgood",["x"]=0.2588,["title"]="Howling in the Hills",["quest"]=126,["y"]=0.4727},{["map"]=1433,["sourceRouteConditions"]=true,["id"]="forever/alliance/04-redridge-mountains:19:1",["t"]="turnin",["npc"]=382,["npcName"]="Marshal Marris",["x"]=0.2841,["title"]="Missing In Action",["quest"]=219,["y"]=0.48969999999999997},{["map"]=1433,["sourceRouteConditions"]=true,["id"]="forever/alliance/04-redridge-mountains:16:6",["t"]="turnin",["npc"]=382,["npcName"]="Marshal Marris",["x"]=0.2841,["title"]="Blackrock Menace",["quest"]=20,["y"]=0.48969999999999997},{["map"]=1433,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/04-redridge-mountains:goal:45:6",["t"]="turnin",["npc"]=382,["npcName"]="Marshal Marris",["x"]=0.2841,["title"]="Blackrock Blockade",["quest"]=98387,["y"]=0.48969999999999997},{["map"]=1433,["sourceRouteConditions"]=true,["id"]="forever/alliance/04-redridge-mountains:16:5",["t"]="turnin",["npc"]=341,["npcName"]="Foreman Oslow",["x"]=0.2705,["title"]="Alther's Mill",["quest"]=98386,["y"]=0.4864},{["map"]=1433,["note"]="Guard Howe, by the gryphons south of the bridge",["sourceRouteConditions"]=true,["id"]="forever/alliance/04-redridge-mountains:19:2",["t"]="turnin",["npc"]=903,["npcName"]="Guard Howe",["x"]=0.2645,["title"]="Blackrock Bounty",["quest"]=128,["y"]=0.5785},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/04-redridge-mountains:goal:45:9",["text"]="Next: the gryphon to Darkshire for Duskwood's second loop (05-duskwood).",["sourceRouteConditions"]=true,["t"]="note"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/04-redridge-mountains:step:45",["text"]="Back to Lakeshire",["sourceRouteConditions"]=true,["detail"]="Into Lakeshire from the north with Keeshan: Bailiff Conacher and Magistrate Solomon in the town hall, Marshal Marris and Foreman Oslow at the north end of the bridge, then over the bridge to Guard Howe and the gryphons."}}},{["revision"]="b753c783be39ccf9c91a94b1bfcb67ce01932d52",["source"]="Polestar GPL-3.0; simulation-derived Forever route",["zone"]=1431,["id"]="polestar:forever/alliance/05-duskwood",["next"]="polestar:forever/alliance/06-wetlands",["max"]=28,["min"]=27,["availability"]="source-listed",["name"]="Duskwood (27-28)",["faction"]="Alliance",["category"]="Leveling",["zoneName"]="Duskwood",["refreshRevision"]="forever-20261117-b753c783",["steps"]={{["goals"]={{["map"]=1433,["x"]=0.255,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/05-duskwood:goal:1:1",["t"]="goto",["y"]=0.594,["text"]="Lakeshire flight master"},{["sourceRouteConditions"]=true,["location"]="Darkshire",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/05-duskwood:goal:1:2",["t"]="fly",["node"]=12,["area"]=42}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/05-duskwood:step:1",["text"]="Fly to Darkshire",["sourceRouteConditions"]=true,["detail"]="Back to the Lakeshire gryphon master: fly to Darkshire for Duskwood's second loop."},{["goals"]={{["map"]=1431,["note"]="Inside",["sourceRouteConditions"]=true,["id"]="forever/alliance/05-duskwood:14:1",["t"]="turnin",["npc"]=302,["npcName"]="Blind Mary",["x"]=0.8199,["title"]="Ghost Hair Thread",["quest"]=149,["y"]=0.5909},{["map"]=1431,["sourceRouteConditions"]=true,["id"]="forever/alliance/05-duskwood:14:2",["t"]="accept",["npc"]=302,["y"]=0.5909,["x"]=0.8199,["title"]="Return the Comb",["npcName"]="Blind Mary",["pre"]={149},["qlvl"]=24,["quest"]=154,["minLevel"]=20},{["map"]=1431,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/05-duskwood:goal:2:3",["t"]="turnin",["npc"]=302,["npcName"]="Blind Mary",["x"]=0.8199,["title"]="Look to the Stars",["quest"]=175,["y"]=0.5909},{["map"]=1431,["note"]="Mary's Looking Glass: the Insane Ghoul in the cemetery's crypt is level 26; it waits for the Duskwood return",["sourceRouteCond