rue},{["goals"]={{["map"]=1442,["x"]=0.765,["sourceRouteConditions"]=true,["y"]=0.455,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-ashenvale:goal:11:1",["t"]="goto",["text"]="Windshear Crag",["area"]=461}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-ashenvale:step:11",["text"]="Stonetalon Mountains",["sourceRouteConditions"]=true,["detail"]="Head south past Mystral Lake into the Talondeep Path tunnel; it comes out in Stonetalon's Windshear Crag, north of the Windshear Mine."},{["goals"]={{["map"]=1442,["note"]="Below ground",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-ashenvale:goal:12:1",["t"]="accept",["npc"]=4276,["soloWhen"]={{["k"]="group",["q"]=1090}},["npcName"]="Piznik",["x"]=0.7187,["title"]="Gerenzo's Orders",["y"]=0.6,["qlvl"]=22,["quest"]=1090,["minLevel"]=17},{["map"]=1442,["note"]="Keep Piznik alive while he mines, below ground",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-ashenvale:goal:12:2",["t"]="complete",["objs"]={{["count"]=1,["text"]="Piznik"}},["soloWhen"]={{["k"]="group",["q"]=1090}},["y"]=0.6,["x"]=0.7187,["title"]="Gerenzo's Orders",["quest"]=1090},{["map"]=1442,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-ashenvale:goal:12:3",["t"]="turnin",["npc"]=4276,["soloWhen"]={{["k"]="group",["q"]=1090}},["npcName"]="Piznik",["x"]=0.7187,["title"]="Gerenzo's Orders",["quest"]=1090,["y"]=0.6},{["map"]=1442,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-ashenvale:goal:12:4",["t"]="accept",["npc"]=4276,["soloWhen"]={{["k"]="group",["q"]=1090}},["y"]=0.6,["x"]=0.7187,["title"]="Gerenzo's Orders",["npcName"]="Piznik",["pre"]={1090},["qlvl"]=22,["quest"]=1092,["minLevel"]=17}},["detail"]="Piznik's defence is hard alone at this level: grouping up is encouraged, look for people to do it with. Skip it if you are alone.\nPiznik mines at the bottom of the Windshear Mine at the east end of the crag, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-ashenvale:step:12",["text"]="Piznik",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="group",["q"]=1090}}},{["goals"]={{["map"]=1442,["sourceRouteConditions"]=true,["id"]="forever/alliance/06-ashenvale:27:1",["t"]="turnin",["npc"]=4080,["npcName"]="Kaela Shadowspear",["x"]=0.599,["title"]="On Guard in Stonetalon",["quest"]=1070,["y"]=0.6685},{["map"]=1442,["crumbs"]={1070},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-ashenvale:goal:13:2",["t"]="accept",["npc"]=4080,["y"]=0.6685,["x"]=0.599,["title"]="On Guard in Stonetalon",["npcName"]="Kaela Shadowspear",["minLevel"]=17,["qlvl"]=21,["quest"]=1085,["sourceRouteConditions"]=true},{["map"]=1442,["sourceRouteConditions"]=true,["id"]="forever/alliance/06-ashenvale:27:3",["t"]="turnin",["npc"]=4077,["npcName"]="Gaxim Rustfizzle",["x"]=0.5952000000000001,["title"]="On Guard in Stonetalon",["quest"]=1085,["y"]=0.6715000000000001},{["map"]=1442,["sourceRouteConditions"]=true,["id"]="forever/alliance/06-ashenvale:27:4",["t"]="accept",["npc"]=4077,["y"]=0.6715000000000001,["x"]=0.5952000000000001,["title"]="A Gnome's Respite",["npcName"]="Gaxim Rustfizzle",["pre"]={1085},["qlvl"]=21,["quest"]=1071,["minLevel"]=17}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-ashenvale:step:13",["text"]="Windshear Crag",["sourceRouteConditions"]=true,["detail"]="Kaela Shadowspear and Gaxim Rustfizzle camp on the Webwinder Path, south-west of the mine."},{["goals"]={{["map"]=1442,["note"]="Ziz Fizziks, inside",["sourceRouteConditions"]=true,["id"]=