="accept",["npc"]=270637,["npcName"]="Howin Kindfeather",["x"]=0.4936,["title"]="Razormaw Needling",["y"]=0.4213,["qlvl"]=29,["quest"]=98245,["minLevel"]=21},{["map"]=1437,["note"]="Trying Times: the Razormaw eggs, on the same loop",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:29:2",["t"]="accept",["npc"]=270637,["npcName"]="Howin Kindfeather",["x"]=0.4936,["title"]="Trying Times",["y"]=0.4213,["qlvl"]=29,["quest"]=98246,["minLevel"]=21}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:step:29",["text"]="Howin Kindfeather",["sourceRouteConditions"]=true,["detail"]="Howin Kindfeather camps among the Fenrunners, just west of Rethiel the Greenwarden."},{["goals"]={{["map"]=1437,["note"]="Einar Stonegrip: for James Halloran in Menethil",["sourceRouteConditions"]=true,["endNpcs"]={2094},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:30:1",["t"]="accept",["npc"]=2093,["xp"]=825,["npcName"]="Einar Stonegrip",["x"]=0.49920000000000003,["qlvl"]=21,["y"]=0.3937,["closedBy"]={484},["title"]="Daily Delivery",["quest"]=469,["minLevel"]=18}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:step:30",["text"]="Einar Stonegrip",["sourceRouteConditions"]=true,["detail"]="East from Howin Kindfeather: Einar Stonegrip stands beside the road."},{["goals"]={{["map"]=1437,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:31:1",["t"]="kill",["npc"]=1040,["y"]=0.32799999999999996,["x"]=0.47600000000000003,["title"]="Blisters on the Land",["count"]=12,["target"]="Fen Creeper",["quest"]=275,["spread"]=true,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:step:31",["text"]="Fen Creepers along the river",["sourceRouteConditions"]=true,["detail"]="North-west from Einar Stonegrip to the river: Fen Creepers hide in its pools and along its banks all the way west to Sundown Marsh. Work west along it until you have twelve, then back east to Rethiel the Greenwarden.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:step:32",["text"]="Rethiel the Greenwarden",["goals"]={{["map"]=1437,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:32:1",["t"]="turnin",["npc"]=1244,["npcName"]="Rethiel the Greenwarden",["x"]=0.5637,["title"]="Blisters on the Land",["quest"]=275,["y"]=0.40399999999999997},{["map"]=1437,["note"]="Carnage, an elite raptor, on the Wetlands loop of 30-40/01-hillsbrad-foothills",["sourceRouteConditions"]=true,["preAll"]={275},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:32:2",["t"]="accept",["npc"]=1244,["qlvl"]=30,["npcName"]="Rethiel the Greenwarden",["x"]=0.5637,["minLevel"]=22,["y"]=0.40399999999999997,["pre"]={275},["title"]="Carnage",["quest"]=98283,["optional"]=true}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1437,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:33:1",["t"]="accept",["npc"]=1244,["soloWhen"]={{["map"]=2998,["k"]="dungeon",["name"]="Excavation Site: Wetlands"}},["y"]=0.40399999999999997,["x"]=0.5637,["title"]="Horrors in the Highland",["npcName"]="Rethiel the Greenwarden",["pre"]={275},["qlvl"]=31,["quest"]=95646,["minLevel"]=24}},["detail"]="For your Excavation Site: Wetlands run, on the way back west: Rethiel the Greenwarden wants the root core of a Highland Horror inside.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:step:33",["text"]="Rethiel the Greenwarden",["sourceRouteConditions"]=true,["soloWhen"]={{["map"]=2998,["k"]="dungeon",["name"]="Excavation Site: Wetlands"}}},{["goals"]={{["map"]=1