ditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:36:2",["t"]="turnin",["npc"]=2104,["npcName"]="Captain Stoutfist",["x"]=0.0986,["title"]="From the Ashes",["quest"]=98221,["y"]=0.5749},{["map"]=1437,["preAll"]={464,98221},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:36:3",["t"]="accept",["npc"]=2104,["note"]="For the Dragonmaw catapult, on the Wetlands loop of 30-40/01-hillsbrad-foothills",["y"]=0.5749,["x"]=0.0986,["title"]="Nek'rosh's Gambit",["npcName"]="Captain Stoutfist",["pre"]={98221},["qlvl"]=31,["quest"]=465,["minLevel"]=23},{["map"]=1437,["note"]="James Halloran, by the docks, on the way to the boat",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:36:4",["t"]="turnin",["npc"]=2094,["npcName"]="James Halloran",["x"]=0.0855,["title"]="Daily Delivery",["quest"]=469,["y"]=0.5574}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:step:36",["text"]="Captain Stoutfist",["sourceRouteConditions"]=true,["detail"]="Hearth back to Menethil Harbor if you bound at the Deepwater Tavern, or walk west along the road: Captain Stoutfist stands on the top floor of Menethil Keep, James Halloran by the docks on the way to the boat."},{["goals"]={{["map"]=1437,["x"]=0.086,["sourceRouteConditions"]=true,["text"]="Bluegill Raider",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:37:1",["t"]="goto",["y"]=0.69,["soloWhen"]={{["op"]="<",["k"]="level",["n"]=28}}},{["map"]=1437,["note"]="grind on Bluegill Raider",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:37:2",["t"]="level",["soloWhen"]={{["op"]="<",["k"]="level",["n"]=28}},["npcName"]="Bluegill Raider",["x"]=0.0864,["lvl"]=29,["y"]=0.69,["level"]=28,["spread"]=true,["grind"]=1418}},["detail"]="Still below leve