"]=1440,["note"]="Llana: Seeking Caitlin, for Caitlin Grassman in Menethil Harbor",["sourceRouteConditions"]=true,["endNpcs"]={1480},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:45:2",["t"]="accept",["npc"]=3970,["xp"]=1250,["npcName"]="Llana",["x"]=0.34979999999999994,["qlvl"]=31,["y"]=0.48460000000000003,["closedBy"]={95647},["title"]="Seeking Caitlin",["quest"]=95737,["minLevel"]=24}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:step:45",["text"]="Shindrell Swiftfire",["sourceRouteConditions"]=true,["detail"]="Shindrell Swiftfire and Llana stand by Astranaar's flight master."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:step:46",["text"]="Astranaar",["goals"]={{["map"]=1440,["note"]="Pelturas Whitemoon, inside",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:46:1",["t"]="accept",["npc"]=3894,["y"]=0.5179,["x"]=0.3737,["title"]="Fallen Sky Lake",["npcName"]="Pelturas Whitemoon",["pre"]={1034},["qlvl"]=30,["quest"]=1035,["minLevel"]=20}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1440,["note"]="Raene Wolfrunner: Trek to Ashenvale, if you still carry it from Darkshore",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:goal:47:1",["t"]="turnin",["npc"]=3691,["soloWhen"]={{["k"]="onquest",["q"]={990}}},["npcName"]="Raene Wolfrunner",["x"]=0.36619999999999997,["title"]="Trek to Ashenvale",["quest"]=990,["y"]=0.49579999999999996}},["detail"]="Raene Wolfrunner stands in the inn, beside the innkeeper.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetlands:step:47",["text"]="Raene Wolfrunner",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="onquest",["q"]={990}}}},{["goals"]={{["map"]=1440,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/06-wetland