hird Troll Legend",["oi"]=3,["note"]="The Third Troll Legend: Fall of Gurubashi",["fromId"]=52,["t"]="collect",["fromKind"]="object",["item"]=2007,["y"]=0.1202,["x"]=0.22949999999999998,["title"]="Kurzen's Mystery",["from"]="Fall of Gurubashi",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/30-40/04b-stranglethorn-vale:goal:11:1",["count"]=1,["quest"]=207,["sourceRouteConditions"]=true},{["map"]=1434,["note"]="Zimmix Sputterspark, in his cage beside the third tablet",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/30-40/04b-stranglethorn-vale:goal:11:2",["t"]="accept",["npc"]=268992,["npcName"]="Zimmix Sputterspark",["x"]=0.2346,["title"]="Where's the Key?",["y"]=0.12789999999999999,["qlvl"]=35,["quest"]=97329,["minLevel"]=30},{["map"]=1434,["itemName"]="Bloodscalp Ear",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/30-40/04b-stranglethorn-vale:goal:11:3",["t"]="collect",["count"]=15,["quest"]=189,["y"]=0.1261,["x"]=0.23379999999999998,["title"]="Bloodscalp Ears",["lvl"]=34,["fromNpcsAt"]="1,6,7,9,8;6,1,7;1,7,6,9;1,6,9;1,6,7,9;1,6,7,9,8;8,7,9;8;8;4;4;4,5;3;3;3,5;5;2,5;2,4,5",["item"]=1519,["spread"]=true,["sourceRouteConditions"]=true},{["map"]=1434,["itemName"]="Primitive Key",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/30-40/04b-stranglethorn-vale:goal:11:4",["t"]="collect",["item"]=277957,["title"]="Where's the Key?",["y"]=0.1261,["x"]=0.23379999999999998,["count"]=1,["lvl"]=37,["fromNpcsAt"]="2,1,3;2,1,3;6,4,3,7;1,2,4,6,3,5,7;4,6,5,7;1,2;4,6,7;6;5,6;5;1,2,3,7;4,5,6;1,2,7",["note"]="Primitive Key, from the Bloodscalp trolls",["quest"]=97329,["sourceRouteConditions"]=true},{["map"]=1434,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/30-40/04b-stranglethorn-vale:goal:11:5",["t"]="turnin",["npc"]=268992,["npcName"]="Zimmix Sputterspark",["x"]=0.2346,["title"]="Where's the Key?",["que