76,["y"]=0.5982999999999999,["x"]=0.26739999999999997,["title"]="Deliver the Shipment",["npcName"]="Watcher Biggs",["pre"]={1398},["qlvl"]=42,["quest"]=1425,["minLevel"]=30}},["sourceRouteConditions"]=true},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:step:81",["text"]="Duskwood",["goals"]={{["map"]=1431,["x"]=0.7759999999999999,["sourceRouteConditions"]=true,["y"]=0.444,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:goal:81:1",["t"]="goto",["text"]="Darkshire",["area"]=42}},["sourceRouteConditions"]=true},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:step:82",["text"]="Fly to Stormwind",["goals"]={{["map"]=1431,["x"]=0.7759999999999999,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:goal:82:1",["text"]="Darkshire flight master",["t"]="goto",["y"]=0.444},{["sourceRouteConditions"]=true,["location"]="Stormwind",["t"]="fly",["node"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:goal:82:2"}},["sourceRouteConditions"]=true},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:step:83",["text"]="Stormwind",["goals"]={{["map"]=1453,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/01-stranglethorn-vale:49:2",["t"]="turnin",["npc"]=5384,["npcName"]="Brohann Caskbelly",["x"]=0.6945,["title"]="In Search of The Temple",["quest"]=1448,["y"]=0.40399999999999997},{["map"]=1453,["note"]="for Falstad Wildhammer at Aerie Peak: keep it",["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/01-stranglethorn-vale:49:3",["t"]="accept",["npc"]=5384,["y"]=0.40399999999999997,["x"]=0.6945,["title"]="To The Hinterlands",["npcName"]="Brohann Caskbelly",["pre"]={1448},["qlvl"]=43,["quest"]=1449,["minLevel"]=38}},["sourceRouteConditions"]=true},{["id"]