e,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:goal:89:2",["t"]="vendor",["npc"]=1261,["soloWhen"]={{["op"]=">=",["k"]="level",["n"]=40}},["npcName"]="Veron Amberstill",["x"]=0.6347,["note"]="Veron Amberstill: other colours, 20g",["y"]=0.5056}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:step:89",["text"]="Riding at 40",["only"]={["races"]={"Dwarf"}},["soloWhen"]={{["op"]=">=",["k"]="level",["n"]=40}}},{["goals"]={{["map"]=1426,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:goal:90:1",["t"]="goto",["soloWhen"]={{["op"]=">=",["k"]="level",["n"]=40}},["y"]=0.48100000000000004,["x"]=0.49200000000000005,["text"]="Steelgrill's Depot",["area"]=189}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:step:90",["text"]="Dun Morogh",["only"]={["races"]={"Gnome"}},["soloWhen"]={{["op"]=">=",["k"]="level",["n"]=40}}},{["detail"]="At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Binjy Featherwhistle teaches Gnomes at Steelgrill's Depot, just east of Kharanos, beside Milli Featherwhistle's mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour.",["goals"]={{["map"]=1426,["optional"]=true,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:goal:91:1",["t"]="train",["npc"]=7954,["soloWhen"]={{["op"]=">=",["k"]="level",["n"]=40}},["npcName"]="Binjy Featherwhistle",["x"]=0.4915,["y"]=0.4813},{["map"]=1426,["optional"]=true,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01-stranglethorn-vale:goal:91:2",["t"]="vendor",["npc"]=795