es:step:26",["text"]="Wheeler's Grange",["sourceRouteConditions"]=true,["detail"]="West to Wheeler's Grange: Benjy Wheeler stands by the farmhouse."},{["goals"]={{["map"]=2548,["itemName"]="Pawprint Tracing",["oi"]=1,["fromId"]=625779,["t"]="collect",["title"]="Foal Play",["fromKind"]="object",["y"]=0.779,["x"]=0.5479999999999999,["count"]=1,["from"]="Track",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:27:1",["item"]=267223,["quest"]=94615,["sourceRouteConditions"]=true},{["map"]=2548,["itemName"]="Bundle of Hay",["oi"]=1,["fromId"]=629484,["t"]="collect",["title"]="Stuff 'Em and Stick 'Em",["fromKind"]="object",["y"]=0.7659999999999999,["x"]=0.5479999999999999,["count"]=3,["from"]="Bundle of Hay",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:27:2",["item"]=268536,["quest"]=95156,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:27",["text"]="The stables",["sourceRouteConditions"]=true,["detail"]="Search around the stables south of the farmhouse for the horses' tracks; the bundles of hay lie around the farm."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:28",["text"]="Benjy Wheeler",["goals"]={{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:28:1",["t"]="turnin",["npc"]=258317,["npcName"]="Benjy Wheeler",["x"]=0.5489,["title"]="Foal Play",["quest"]=94615,["y"]=0.73},{["map"]=2548,["note"]="Coyote Huntin'",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:28:2",["t"]="accept",["npc"]=258317,["y"]=0.73,["x"]=0.5489,["title"]="Coyote Huntin'",["npcName"]="Benjy Wheeler",["pre"]={94615},["qlvl"]=38,["quest"]=94617,["minLevel"]=36},{["map"]=2548,["note"]="Wheeler's Fleeing Steeds",["