tions"]=true,["item"]=271432,["quest"]=95913,["map"]=2548,["oi"]=1,["fromId"]=259267,["t"]="collect",["spread"]=true,["y"]=0.8108,["x"]=0.6093,["title"]="Fit for a Princess",["lvl"]=37,["count"]=3,["from"]="Plains Coyote",["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:53:1"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:53",["text"]="Coyote pelts",["sourceRouteConditions"]=true,["detail"]="The Plains Coyotes roam west and south-west of the keep, towards Wheeler's Grange."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:54",["text"]="Tessa Dawnbright",["goals"]={{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:54:1",["t"]="turnin",["npc"]=263089,["npcName"]="Tessa Dawnbright",["x"]=0.6385000000000001,["title"]="Fit for a Princess",["quest"]=95913,["y"]=0.8223999999999999},{["map"]=2548,["note"]="Stepped Out: for Gray Dawnbright in Powderfuse Port, keep it",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:54:2",["t"]="accept",["npc"]=263089,["y"]=0.8223999999999999,["x"]=0.6385000000000001,["title"]="Stepped Out",["npcName"]="Tessa Dawnbright",["pre"]={95913},["qlvl"]=38,["quest"]=95961,["minLevel"]=36}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:55:1",["t"]="accept",["npc"]=259352,["soloWhen"]={{["k"]="group",["q"]=95986}},["y"]=0.6396999999999999,["x"]=0.5953,["title"]="King of the Wild Plains",["npcName"]="Watcher Cornelius",["pre"]={95984},["qlvl"]=41,["quest"]=95986,["minLevel"]=36}},["detail"]="Ombassa, an elite lion (level 41), prowls the plains north of Terral's Watch, on your way back north: grouping up is advised.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:55",["text"]="King of the Wild Plains",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="group",["q"]=95986}}},{["goals"]={{["itemName"]="Ombassa's Hide",["sourceRouteConditions"]=true,["group"]={["kind"]="elite",["rank"]=1,["lvl"]=41},["soloWhen"]={{["k"]="group",["q"]=95986}},["item"]=281052,["fromRank"]=1,["quest"]=95986,["map"]=2548,["oi"]=1,["fromId"]=263315,["t"]="collect",["y"]=0.536,["x"]=0.596,["title"]="King of the Wild Plains",["from"]="Ombassa",["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:56:1"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:56",["text"]="Ombassa",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="group",["q"]=95986}}},{["goals"]={{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:57:1",["t"]="turnin",["npc"]=263367,["npcName"]="Sleebo Fizzlespout",["x"]=0.6809999999999999,["title"]="Gaseous Gold",["quest"]=96063,["y"]=0.486},{["map"]=2548,["note"]="Rock 'em and Sock 'em",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:57:2",["t"]="accept",["npc"]=263367,["y"]=0.486,["x"]=0.6809999999999999,["title"]="Rock 'em and Sock 'em",["npcName"]="Sleebo Fizzlespout",["pre"]={96063},["qlvl"]=40,["quest"]=96067,["minLevel"]=36},{["map"]=2548,["note"]="the stress test: beat G45-B4G beside the workshop",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:57:3",["t"]="complete",["objs"]={{["count"]=1,["text"]="Fight G45-B4G in a stress test of Sleebo's engine."}},["y"]=0.486,["x"]=0.682,["title"]="Rock 'em and Sock 'em",["quest"]=96067},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:57:4",["t"]="turnin",["npc"]=263367,["npcName"]="Sleebo Fizzlespout",["x"]=0.6809999999999999,["title"]="Rock 'em and Sock 'em",["quest"]=96067,["y"]=0.486}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:57",["text"]="Sleebo Fizzlespout",["sourceRouteConditions"]=true,["detail"]="North-east to Sleebo Fizzlespout's workshop. Sleebo Fizzlespout's stress test is a fight with his G45-B4G beside the workshop: hand the quest in once it's beaten."},{["goals"]={{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:1",["t"]="turnin",["npc"]=255897,["npcName"]="Friz Frazzlespark",["x"]=0.7709999999999999,["title"]="A Few Furs for Friz",["quest"]=94928,["y"]=0.529},{["map"]=2548,["note"]="Smuggler's Paradise",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:2",["t"]="accept",["npc"]=255897,["y"]=0.529,["x"]=0.7709999999999999,["title"]="Smuggler's Paradise",["npcName"]="Friz Frazzlespark",["pre"]={94928,93976},["qlvl"]=43,["quest"]=95288,["minLevel"]=38},{["map"]=2548,["note"]="Frazzlespark's Crate: for Demar Brant in Farholde Keep, keep it",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:3",["t"]="accept",["npc"]=255897,["npcName"]="Friz Frazzlespark",["x"]=0.7709999999999999,["title"]="Frazzlespark's Crate",["y"]=0.529,["qlvl"]=36,["quest"]=95059,["minLevel"]=36},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:4",["t"]="turnin",["npc"]=263120,["npcName"]="Gray Dawnbright",["x"]=0.7881999999999999,["title"]="Stepped Out",["quest"]=95961,["y"]=0.5416},{["map"]=2548,["note"]="Innkeeper Zizplink: Goes Down Smooth",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:5",["t"]="accept",["npc"]=255894,["y"]=0.5398,["x"]=0.7877,["title"]="Goes Down Smooth",["npcName"]="Innkeeper Zizplink",["pre"]={95961},["qlvl"]=38,["quest"]=95988,["minLevel"]=36},{["map"]=2548,["itemName"]="Fresh Chum",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:6",["t"]="buy",["npc"]=260487,["npcName"]="Gritta Chumwater",["x"]=0.7848,["item"]=271657,["note"]="Fresh Chum, from Gritta Chumwater",["y"]=0.5379},{["map"]=2548,["itemName"]="Goblin Degreaser",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:7",["t"]="buy",["npc"]=260565,["npcName"]="Kor'gar",["x"]=0.7864,["item"]=271653,["note"]="Goblin Degreaser, from Kor'gar",["y"]=0.5297999999999999},{["map"]=2548,["itemName"]="Expired Poison",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:8",["t"]="buy",["npc"]=260560,["npcName"]="Krikshank",["x"]=0.7827,["item"]=271654,["note"]="Expired Poison, from Krikshank",["y"]=0.5281},{["map"]=2548,["note"]="Fimbo Greasemitz: A Taste of the Sea",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:9",["t"]="accept",["npc"]=259962,["npcName"]="Fimbo Greasemitz",["x"]=0.7902,["title"]="A Taste of the Sea",["y"]=0.542,["qlvl"]=40,["quest"]=95121,["minLevel"]=36},{["map"]=2548,["note"]="The WANTED! poster by the inn: Trapclaw",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:10",["t"]="accept",["y"]=0.539,["x"]=0.785,["title"]="WANTED: Trapclaw",["objName"]="WANTED!",["qlvl"]=42,["minLevel"]=36,["quest"]=95254,["object"]=628948},{["map"]=2548,["note"]="Wharfmaster Whizzbuzz: Saltwater Savages",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:11",["t"]="accept",["npc"]=259961,["npcName"]="Wharfmaster Whizzbuzz",["x"]=0.7945,["title"]="Saltwater Savages",["y"]=0.5271,["qlvl"]=41,["quest"]=95118,["minLevel"]=36},{["map"]=2548,["note"]="Unfriendly Competition",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:58:12",["t"]="accept",["npc"]=259961,["npcName"]="Wharfmaster Whizzbuzz",["x"]=0.7945,["title"]="Unfriendly Competition",["y"]=0.5271,["qlvl"]=43,["quest"]=95119,["minLevel"]=38}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:58",["text"]="Powderfuse Port",["sourceRouteConditions"]=true,["detail"]="East down the road to Powderfuse Port, the goblins' harbour. Friz Frazzlespark keeps a stall at the west end of the docks; Gray Dawnbright, Innkeeper Zizplink and Fimbo Greasemitz are at the inn, and Wharfmaster Whizzbuzz works the north pier. Zizplink's drink needs three things the port's traders sell: the chum from Gritta Chumwater, the degreaser and the old poison from Kor'gar and Krikshank, by Friz Frazzlespark's stall."},{["goals"]={{["map"]=2548,["note"]="The WANTED! poster by the inn",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:59:1",["t"]="accept",["soloWhen"]={{["k"]="group",["q"]=95120}},["y"]=0.539,["x"]=0.785,["title"]="WANTED: Old Rot-Chum",["objName"]="WANTED!",["qlvl"]=42,["minLevel"]=36,["quest"]=95120,["object"]=628948}},["detail"]="Old Rot-Chum is an elite (level 42) on the south shore: grouping up is advised.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:59",["text"]="WANTED: Old Rot-Chum",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="group",["q"]=95120}}},{["goals"]={{["map"]=2548,["note"]="Painted Hide: Terrors From the Deep",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:60:1",["t"]="accept",["y"]=0.6189,["x"]=0.7234999999999999,["title"]="Terrors From the Deep",["objName"]="Painted Hide",["qlvl"]=42,["quest"]=95260,["object"]=629761},{["map"]=2548,["itemName"]="Saltwater Murloc Eye",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:60:2",["t"]="collect",["title"]="A Taste of the Sea",["y"]=0.615,["x"]=0.7240000000000001,["count"]=12,["lvl"]=41,["spread"]=true,["item"]=268344,["quest"]=95121,["sourceRouteConditions"]=true},{["map"]=2548,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:60:3",["t"]="kill",["npc"]=256801,["y"]=0.615,["x"]=0.7240000000000001,["title"]="Saltwater Savages",["count"]=8,["target"]="Murloc Warrior",["quest"]=95118,["spread"]=true,["sourceRouteConditions"]=true},{["map"]=2548,["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:60:4",["t"]="kill",["npc"]=255898,["y"]=0.616,["x"]=0.727,["title"]="Saltwater Savages",["count"]=8,["target"]="Murloc Oracle",["quest"]=95118,["spread"]=true,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:60",["text"]="The murlocs, south-west",["sourceRouteConditions"]=true,["detail"]="South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts Terrors From the Deep for Argo Brinewhistle at the docks."},{["goals"]={{["itemName"]="Rot-Covered Harpoon",["sourceRouteConditions"]=true,["group"]={["kind"]="elite",["rank"]=1,["lvl"]=42},["soloWhen"]={{["k"]="group",["q"]=95120}},["item"]=268341,["fromRank"]=1,["quest"]=95120,["map"]=2548,["oi"]=1,["fromId"]=257001,["t"]="collect",["y"]=0.723,["x"]=0.774,["title"]="WANTED: Old Rot-Chum",["lvl"]=42,["from"]="Old Rot-Chum",["count"]=1,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:61:1"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:61",["text"]="Old Rot-Chum",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="group",["q"]=95120}}},{["goals"]={{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:62:1",["t"]="turnin",["npc"]=259961,["npcName"]="Wharfmaster Whizzbuzz",["x"]=0.7945,["title"]="Saltwater Savages",["quest"]=95118,["y"]=0.5271},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:62:2",["t"]="turnin",["npc"]=260231,["npcName"]="Argo Brinewhistle",["x"]=0.7995,["title"]="Terrors From the Deep",["quest"]=95260,["y"]=0.5249},{["map"]=2548,["note"]="It Takes Guts: the beasts' entrails come as you go; the mushrooms are for later",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:62:3",["t"]="accept",["npc"]=260231,["y"]=0.5249,["x"]=0.7995,["title"]="It Takes Guts",["npcName"]="Argo Brinewhistle",["pre"]={95260},["qlvl"]=42,["quest"]=95261,["minLevel"]=38}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:62",["text"]="Back through the port",["sourceRouteConditions"]=true,["detail"]="Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."},{["goals"]={{["itemName"]="Sand Crawler Meat",["sourceRouteConditions"]=true,["item"]=268345,["quest"]=95121,["map"]=2548,["oi"]=2,["fromId"]=255901,["t"]="collect",["fromAlsoId"]=256807,["title"]="A Taste of the Sea",["y"]=0.5279,["x"]=0.7859999999999999,["count"]=6,["from"]="Sand Crawler",["spread"]=true,["fromAlso"]="Shore Crawler",["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:63:1"},{["itemName"]="Crawler Spittle",["sourceRouteConditions"]=true,["item"]=271650,["quest"]=95988,["map"]=2548,["oi"]=1,["fromId"]=256807,["t"]="collect",["spread"]=true,["y"]=0.49479999999999996,["x"]=0.7887000000000001,["title"]="Goes Down Smooth",["lvl"]=40,["count"]=3,["from"]="Shore Crawler",["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:63:2"},{["map"]=2548,["itemName"]="Trapclaw's Pincer",["oi"]=1,["item"]=268586,["fromId"]=260235,["t"]="collect",["fromKind"]="npc",["lvl"]=42,["y"]=0.49079999999999996,["x"]=0.7933,["title"]="WANTED: Trapclaw",["from"]="Trapclaw",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:63:3",["count"]=1,["quest"]=95254,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:63",["text"]="The crawlers and Trapclaw",["sourceRouteConditions"]=true,["detail"]="North along the beach from the docks: the crawlers drop the meat for Fimbo Greasemitz and the spittle for Zizplink, and their entrails count for Argo Brinewhistle. Trapclaw, a big crab, scuttles along the rocks east of the docks. Gul'gash, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."},{["goals"]={{["map"]=2548,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:64:1",["t"]="kill",["npc"]=257901,["count"]=10,["y"]=0.4537,["x"]=0.8172,["title"]="Unfriendly Competition",["lvl"]=42,["target"]="Eastsea Buccaneer",["quest"]=95119,["spread"]=true,["sourceRouteConditions"]=true},{["map"]=2548,["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:64:2",["t"]="kill",["npc"]=257910,["count"]=10,["y"]=0.47,["x"]=0.8069,["title"]="Unfriendly Competition",["lvl"]=43,["target"]="Eastsea Musketeer",["quest"]=95119,["spread"]=true,["sourceRouteConditions"]=true},{["itemName"]="Smuggled Goods",["sourceRouteConditions"]=true,["item"]=268796,["quest"]=95288,["map"]=2548,["oi"]=1,["fromAlsoId"]=257910,["fromId"]=257901,["t"]="collect",["fromAlso"]="Eastsea Musketeer",["spread"]=true,["y"]=0.47,["x"]=0.8069,["title"]="Smuggler's Paradise",["lvl"]=43,["from"]="Eastsea Buccaneer",["count"]=8,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:64:3"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:step:64",["text"]="The Eastsea pirates",["sourceRouteConditions"]=true,["detail"]="North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. Gul'gash walks the camp too: keep an eye out for him."},{["goals"]={{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:65:1",["t"]="turnin",["npc"]=259961,["npcName"]="Wharfmaster Whizzbuzz",["x"]=0.7945,["title"]="Unfriendly Competition",["quest"]=95119,["y"]=0.5271},{["map"]=2548,["note"]="Unchecked Expansion: for later in this guide",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:65:2",["t"]="accept",["npc"]=259961,["y"]=0.5271,["x"]=0.7945,["title"]="Unchecked Expansion",["npcName"]="Wharfmaster Whizzbuzz",["pre"]={95119},["qlvl"]=44,["quest"]=95122,["minLevel"]=38},{["map"]=2548,["note"]="A Blast Ye Scurvy Dogs!: for later in this guide",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:65:3",["t"]="accept",["npc"]=259961,["y"]=0.5271,["x"]=0.7945,["title"]="A Blast Ye Scurvy Dogs!",["npcName"]="Wharfmaster Whizzbuzz",["pre"]={95119},["qlvl"]=44,["quest"]=95123,["minLevel"]=38},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:65:4",["t"]="turnin",["npc"]=259962,["npcName"]="Fimbo Greasemitz",["x"]=0.7902,["title"]="WANTED: Trapclaw",["quest"]=95254,["y"]=0.542},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:65:5",["t"]="turnin",["npc"]=259962,["npcName"]="Fimbo Greasemitz",["x"]=0.7902,["title"]="A Taste of the Sea",["quest"]=95121,["y"]=0.542},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:65:6",["t"]="turnin",["npc"]=255894,["npcName"]="Innkeeper Zizplink",["x"]=0.7877,["title"]="Goes Down Smooth",["quest"]=95988,["y"]=0.5398},{["map"]=2548,["note"]="Drink Up!",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:65:7",["t"]="accept",["npc"]=255894,["y"]=0.5398,["x"]=0.7877,["title"]="Drink Up!",["npcName"]="Innkeeper Zizplink",["pre"]={95988},["qlvl"]=38,["quest"]=95957,["minLevel"]=36},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:65:8",["t"]="turnin",["npc"]=263120,["npcName"]="Gray Dawnbright",["x"]=0.7881999999999999,["title"]="Drink Up!",["quest"]=95957,["y"]=0.5416},{["map"]=2548,["note"]="Her World: for later, the wildflowers west of the port",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/01b-riverglades:goal:65:9",["t"]="accept",["npc"]=263120,["y"]=0.5416,["x"]=0.7881999999999999,["title"]="Her World",["npcName"]="Gray Dawnbright",["pre"]={95957},["qlvl"]=41,["quest"]=95975,["minLevel"]=36},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-2026