ct"]=true,["qlvl"]=45,["quest"]=349,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:goal:27:1"}},["detail"]="Hand in the fangs and stay: three waves of gorillas come, Mokk the Savage last.\nCareful: three waves of gorillas come one after another with little rest between, then Mokk the Savage. Start at full health and mana, and stay near Unbagwa. Some classes find it hard alone: a friend makes it easy.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:step:27",["text"]="Unbagwa's ritual",["sourceRouteConditions"]=true,["soloWhen"]={{["item"]=2799,["k"]="has",["n"]=10}}},{["goals"]={{["map"]=1434,["itemName"]="Heart of Mokk",["oi"]=1,["title"]="Stranglethorn Fever",["fromId"]=1514,["t"]="collect",["fromKind"]="npc",["soloWhen"]={{["k"]="turnedin",["q"]=349}},["y"]=0.6088,["x"]=0.3505,["count"]=1,["from"]="Mokk the Savage",["sourceRouteConditions"]=true,["item"]=2797,["quest"]=348,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:goal:28:1"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:step:28",["text"]="Unbagwa's ritual",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="turnedin",["q"]=349}}},{["goals"]={{["map"]=1434,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:goal:29:1",["t"]="turnin",["npc"]=2494,["npcName"]="Privateer Bloads",["x"]=0.2676,["title"]="Akiris by the Bundle",["quest"]=617,["y"]=0.7637999999999999},{["map"]=1434,["note"]="for Privateer Groy in Theramore: keep it, the Un'Goro guide lands there",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:goal:29:2",["t"]="accept",["npc"]=2494,["y"]=0.7637999999999999,["x"]=0.2676,["title"]="Akiris by the Bundle",["npcName"]="Privateer Bloads",["pre"]={617},["qlvl"]=43,["quest"]=623,["minLevel"]=38},{["map"]=1434,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:goal:29:3",["t"]="turnin",["npc"]=2486,["npcName"]="Fin Fizracket",["x"]=0.2761,["title"]="Stranglethorn Fever",["quest"]=348,["y"]=0.7674},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:goal:29:4",["text"]="Crank Fizzlebub's next Zanzil errand starts in Thousand Needles: skip it.",["sourceRouteConditions"]=true,["t"]="note"},{["map"]=1434,["note"]="Crank Fizzlebub, inside",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:goal:29:5",["t"]="turnin",["npc"]=2498,["npcName"]="Crank Fizzlebub",["x"]=0.2712,["title"]="Zanzil's Secret",["quest"]=621,["y"]=0.7720999999999999},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:goal:29:6",["text"]="MacKinley's next task sends you after elite ogres: skip it.",["sourceRouteConditions"]=true,["t"]="note"},{["map"]=1434,["note"]="\"Sea Wolf\" MacKinley, on the top floor",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:goal:29:7",["t"]="turnin",["npc"]=2501,["npcName"]="\"Sea Wolf\" MacKinley",["x"]=0.2778,["title"]="Voodoo Dues",["quest"]=609,["y"]=0.7706999999999999}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/05-the-hinterlands:step:29",["text"]="Booty Bay",["sourceRouteConditions"]=true,["detail"]="Ride back down to town."},{["goals"]={{["map"]=1434,["itemName"]="Monogrammed Sash",["sourceRouteConditions"]=true,["group"]={["kind"]="elite",["rank"]=1,["lvl"]=50},["t"]="collect",["fromId"]=1493,["soloWhen"]={{["k"]="group",["q"]=8552}},["y"]=0.721,["x"]=0.233,["item"]=3985,["from"]="Mok'rash",["count"]=1,["fromRank"]=1,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-5