,{["escort"]=true,["title"]="Suntara Stones",["quest"]=3367,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/06-searing-gorge:goal:8:2",["t"]="complete",["objs"]={{["count"]=1,["text"]="Dorius Escort"}},["sourceRouteConditions"]=true},{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/06-searing-gorge:13:3",["t"]="turnin",["y"]=0.1929,["x"]=0.7445,["title"]="Suntara Stones",["objName"]="Singed Letter",["quest"]=3367,["object"]=175704},{["map"]=1427,["note"]="For Curator Thorius in Ironforge, at the end of this guide",["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/06-searing-gorge:13:4",["t"]="accept",["object"]=175704,["y"]=0.1929,["x"]=0.7445,["qlvl"]=48,["objName"]="Singed Letter",["pre"]={3367},["minLevel"]=40,["quest"]=3368,["title"]="Suntara Stones"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/06-searing-gorge:step:8",["text"]="Dorius Stonetender",["sourceRouteConditions"]=true,["detail"]="Dorius stands by the road beside the Grimesilt Dig Site. Escort him north-east to Dustfire Valley and keep him alive; when it is over, read the Singed Letter he leaves on the road."},{["goals"]={{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/06-searing-gorge:2:1",["t"]="getfp",["npc"]=2941,["npcName"]="Lanie Reed",["x"]=0.37939999999999996,["location"]="Thorium Point",["y"]=0.3086,["node"]=74,["area"]=1446},{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/06-searing-gorge:2:7",["t"]="accept",["npc"]=14624,["npcName"]="Master Smith Burninate",["x"]=0.38799999999999996,["title"]="What the Flux?",["y"]=0.2851,["qlvl"]=50,["quest"]=7722,["minLevel"]=45},{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/06-searing-gorge:2:6",["t"]="accept",["npc"]=14627,["npcName"]="Hansel Heavyhands",["x"]=0.3858,["title"]="Incendosaurs? Whateverosaur is More Like It",["y"]=0.2781,["qlvl"]=49,["quest"]=7727,["minLevel"]=4