"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/06-searing-gorge:goal:21:1",["t"]="turnin",["npc"]=8479,["npcName"]="Velarok Windblade",["x"]=0.3906,["title"]="Forging the Shaft",["quest"]=3443,["y"]=0.3899}},["sourceRouteConditions"]=true},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/06-searing-gorge:step:22",["text"]="Thorium Point",["goals"]={{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/06-searing-gorge:11:2",["t"]="turnin",["npc"]=14626,["npcName"]="Taskmaster Scrange",["x"]=0.3897,["title"]="JOB OPPORTUNITY: Culling the Competition",["quest"]=7729,["y"]=0.2751},{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/06-searing-gorge:11:1",["t"]="turnin",["npc"]=14626,["npcName"]="Taskmaster Scrange",["x"]=0.3897,["title"]="STOLEN: Smithing Tuyere and Lookout's Spyglass",["quest"]=7728,["y"]=0.2751},{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/06-searing-gorge:11:3",["t"]="turnin",["npc"]=14627,["npcName"]="Hansel Heavyhands",["x"]=0.3858,["title"]="Curse These Fat Fingers",["quest"]=7723,["y"]=0.2781},{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/06-searing-gorge:11:4",["t"]="turnin",["npc"]=14627,["npcName"]="Hansel Heavyhands",["x"]=0.3858,["title"]="Fiery Menace!",["quest"]=7724,["y"]=0.2781}},["sourceRouteConditions"]=true},{["goals"]={{["itemName"]="Secret Plans: Fiery Flux",["sourceRouteConditions"]=true,["group"]={["rank"]=1,["kind"]="elite",["near"]=true,["lvl"]=50},["item"]=18922,["quest"]=7722,["map"]=1427,["oi"]=1,["fromId"]=179826,["t"]="collect",["y"]=0.3574,["x"]=0.4045,["title"]="What the Flux?",["from"]="Secret Plans: Fiery Flux",["note"]="Secret Plans: Fiery Flux; below ground",["count"]=1,["fromKind"]="object",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/06-searing-gorge:goal:23:1"},{["map"]=1427,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polesta