d"]="forever/alliance/40-50/07-un-goro-crater:8:2",["t"]="turnin",["npc"]=9270,["npcName"]="Williden Marshal",["x"]=0.4395,["title"]="Williden's Journal",["quest"]=3884,["y"]=0.07139999999999999},{["map"]=1449,["note"]="Linken, at the back of the refuge",["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/07-un-goro-crater:8:5",["t"]="turnin",["npc"]=8737,["npcName"]="Linken",["x"]=0.44659999999999994,["title"]="It's a Secret to Everybody",["quest"]=3845,["y"]=0.081},{["map"]=1449,["note"]="Ends with Donova Snowden in Winterspring: keep it",["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/07-un-goro-crater:8:6",["t"]="accept",["npc"]=8737,["y"]=0.081,["x"]=0.44659999999999994,["title"]="It's a Secret to Everybody",["npcName"]="Linken",["pre"]={3845},["qlvl"]=52,["quest"]=3908,["minLevel"]=47},{["map"]=1449,["note"]="J.D. Collie, at the back of the cave; below ground",["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/07-un-goro-crater:8:8",["t"]="accept",["npc"]=9117,["npcName"]="J.D. Collie",["x"]=0.4192,["title"]="Crystals of Power",["y"]=0.027000000000000003,["qlvl"]=53,["quest"]=4284,["minLevel"]=47},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:goal:20:8",["text"]="Spark Nilminer, Hol'anyee Marshal, Williden Marshal and Karna Remtravel have quests among mobs of 51-55: leave them for the later Un'Goro visit, at about 56.",["sourceRouteConditions"]=true,["t"]="note"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:step:20",["text"]="Marshal's Refuge",["sourceRouteConditions"]=true,["detail"]="Ride north-west to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and Un'Goro Dirt Pile you pass from here on."},{["goals"]={{["itemName"]="Bloodpetal",["sourceRouteConditions"]=true,["item"]=11316,["quest"]=4141,["map"]=1449,["oi"]=1,["fromAlsoId"]=6510,["fromId"]=6509,["t"]="collect",["fromAlso"]="Bloodpetal Flayer",["note"]="Bloodpetal, from the Lashers and Threshers",["y"]=0.35,["x"]=0.5660000000000001,["title"]="Muigin and Larion",["lvl"]=52,["from"]="Bloodpetal Lasher",["count"]=15,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:goal:21:1"},{["map"]=1449,["itemName"]="Un'Goro Soil",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:goal:21:2",["t"]="collect",["carriedTo"]="forever/alliance/50-60/01-burning-steppes",["title"]="Un'Goro Soil",["y"]=0.35,["x"]=0.5660000000000001,["item"]=11018,["note"]="Un'Goro Soil, from the Threshers and the dirt piles",["count"]=20,["fromNpcsAt"]="1;1;;;1;;1;;1;;1;2;2;2;;1;2;1;2;;3,5;;2;2;;2;6,2;2;4,3,5,6;2",["quest"]=3764,["sourceRouteConditions"]=true},{["map"]=1449,["itemName"]="Webbed Pterrordax Scale",["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:goal:21:3",["t"]="collect",["item"]=11831,["title"]="Shizzle's Flyer",["y"]=0.353,["x"]=0.5770000000000001,["count"]=8,["lvl"]=50,["fromNpcsAt"]="1;1;1;2;1;1;1;2;2",["note"]="Webbed Pterrordax Scale, Fledgling Pterrordax",["quest"]=4503,["sourceRouteConditions"]=true},{["map"]=1449,["itemName"]="Webbed Diemetradon Scale",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:goal:21:4",["t"]="collect",["note"]="Webbed Diemetradon Scale, Young Diemetradon",["y"]=0.353,["x"]=0.5770000000000001,["title"]="Shizzle's Flyer",["lvl"]=52,["item"]=11830,["count"]=8,["quest"]=4503,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:step:21",["text"]="Fire Plume Ridge and the eastern jungle",["sourceRouteConditions"]=true,["detail"]="Ride east into the eastern jungle: Bloodpetal Lashers and Threshers (48-50) drop the petals and Un'Goro Soil. Crystal clusters stand all over the crater, many around the foot of Fire Plume Ridge: take a few extra of each colour.\nCareful: the Living Blazes (54-55) walk the top of Fire Plume Ridge, and the Bloodpetal Flayers and Trappers (51-53) hold the jungle's south: take your crystals from the ridge's foot and your petals in the north.\nShizzle's scales: the Fledgling Pterrordax (48-50) glide over the north-east of the jungle and the Young Diemetradons (49-50) graze beside them. There are only ten of those: the Diemetradons (51) on the jungle's western edge, a short way west of the Threshers, drop the scales too. They are a level over you: take them one at a time."},{["goals"]={{["map"]=1449,["itemName"]="Blue Power Crystal",["oi"]=4,["fromId"]=164658,["t"]="collect",["title"]="Crystals of Power",["fromKind"]="object",["y"]=0.21100000000000002,["x"]=0.722,["count"]=7,["from"]="Blue Power Crystal",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:goal:22:1",["item"]=11184,["quest"]=4284,["sourceRouteConditions"]=true},{["map"]=1449,["itemName"]="Green Power Crystal",["oi"]=3,["fromId"]=164659,["t"]="collect",["title"]="Crystals of Power",["fromKind"]="object",["y"]=0.21100000000000002,["x"]=0.722,["count"]=7,["from"]="Green Power Crystal",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:goal:22:2",["item"]=11185,["quest"]=4284,["sourceRouteConditions"]=true},{["map"]=1449,["itemName"]="Red Power Crystal",["oi"]=1,["fromId"]=164660,["t"]="collect",["title"]="Crystals of Power",["fromKind"]="object",["y"]=0.21100000000000002,["x"]=0.722,["count"]=7,["from"]="Red Power Crystal",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:goal:22:3",["item"]=11186,["quest"]=4284,["sourceRouteConditions"]=true},{["map"]=1449,["itemName"]="Yellow Power Crystal",["oi"]=2,["fromId"]=164661,["t"]="collect",["title"]="Crystals of Power",["fromKind"]="object",["y"]=0.21100000000000002,["x"]=0.722,["count"]=7,["from"]="Yellow Power Crystal",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:goal:22:4",["item"]=11188,["quest"]=4284,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:step:22",["text"]="Lakkari Tar Pits",["sourceRouteConditions"]=true,["detail"]="Crystal clusters stand all over the crater. The pits' Tar Lords (53-54) and the oozes around them (50-54) are over you: take the clusters on the jungle's north-eastern edge, among the Lashers and young beasts (48-50)."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:step:23",["text"]="Marshal's Refuge",["goals"]={{["map"]=1449,["note"]="J.D. Collie, below ground",["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/07-un-goro-crater:14:3",["t"]="turnin",["npc"]=9117,["npcName"]="J.D. Collie",["x"]=0.4192,["title"]="Crystals of Power",["quest"]=4284,["y"]=0.027000000000000003},{["map"]=1449,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/07-un-goro-crater:14:1",["t"]="turnin",["npc"]=9119,["npcName"]="Muigin",["x"]=0.4294,["title"]="Muigin and Larion",["quest"]=4141,["y"]=0.0964},{["map"]=1449,["note"]="For Gregan Brewspewer in Feralas: keep it",["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/07-un-goro-crater:14:2",["t"]="accept",["npc"]=9119,["y"]=0.0964,["x"]=0.4294,["title"]="A Visit to Gregan",["npcName"]="Muigin",["pre"]={4141},["qlvl"]=52,["quest"]=4142,["minLevel"]=47},{["map"]=1449,["sourceRouteConditions"]=true,["id"]="forever/alliance/40-50/07-un-goro-crater:22:1",["t"]="turnin",["npc"]=9998,["npcName"]="Shizzle",["x"]=0.44229999999999997,["title"]="Shizzle's Flyer",["quest"]=4503,["y"]=0.1159},{["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/40-50/07-un-goro-crater:goal:23:5",["t"]="level",["only"]={["classes"]={"PRIEST","MAGE"}},["level"]=50}},["sourceRouteConditions"]=true},{["goals"]=