"]={["size"]=2,["kind"]="group"},["soloWhen"]={{["k"]="group",["q"]=91775}},["item"]=248002,["fromRank"]=1,["quest"]=91775,["map"]=1429,["oi"]=1,["fromId"]=248464,["t"]="collect",["y"]=0.799,["x"]=0.41619999999999996,["title"]="Book Return",["from"]="Nimsy",["note"]="Fun with Elementals: Nimsy",["count"]=1,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:goal:49:2"}},["detail"]="These are elite mobs: grouping up is encouraged, look for people to do it with. Nimsy (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:step:49",["text"]="Maclure Vineyards: kill these as you meet them",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="group",["q"]=91775}}},{["goals"]={{["map"]=1429,["x"]=0.395,["sourceRouteConditions"]=true,["y"]=0.8240000000000001,["id"]="forever/alliance/human/01-elwynn-forest:32:3",["t"]="goto",["text"]="Fargodeep Mine",["area"]=57},{["map"]=1429,["itemName"]="Bernice's Necklace",["oi"]=1,["note"]="Bernice's Necklace; below ground",["fromId"]=327,["t"]="collect",["quest"]=87,["count"]=1,["y"]=0.7803,["x"]=0.4171,["item"]=981,["from"]="Goldtooth",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:goal:50:2",["title"]="Goldtooth",["fromKind"]="npc",["sourceRouteConditions"]=true},{["map"]=1429,["itemName"]="Westfall Deed",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:goal:50:3",["fromNpcsAt"]="1;2,3,6;1;4;4;1;1;1;7;1;1;1;1;1;1;1,4;1,4;4,1;1;1,5,8;4;4;4",["y"]=0.7493000000000001,["x"]=0.4437,["item"]=1972,["lvl"]=9,["t"]="collect",["optional"]=true,["spread"]=true,["count"]=1},{["optional"]=true,["sourceRouteConditions"]=true,["id"]="forever/alliance/human/01-elwynn-forest:33:3",["t"]="accept",["title"]="Furlbrow's Deed",["itemName"]="Westfall Deed",["qlvl"]=9,["minLevel"]=8,["quest"]=184,["item"]=1972}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:step:50",["text"]="Goldtooth",["sourceRouteConditions"]=true,["detail"]="Goldtooth is inside the Fargodeep Mine, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a Westfall Deed now and then: right-click it.\nCareful: Nimsy (6), a kobold deep in the mine, is elite, and Narg the Taskmaster (10, rare) walks the tunnels: pull the kobolds one at a time."},{["goals"]={{["map"]=1429,["sourceRouteConditions"]=true,["id"]="forever/alliance/human/01-elwynn-forest:34:1",["t"]="turnin",["npc"]=241,["npcName"]="Remy \"Two Times\"",["x"]=0.4214,["title"]="Gold Dust Exchange",["quest"]=47,["y"]=0.6726000000000001},{["map"]=1429,["sourceRouteConditions"]=true,["id"]="forever/alliance/human/01-elwynn-forest:34:2",["t"]="turnin",["npc"]=241,["npcName"]="Remy \"Two Times\"",["x"]=0.4214,["title"]="An Enticing Offer",["quest"]=99130,["y"]=0.6726000000000001},{["map"]=1429,["sourceRouteConditions"]=true,["id"]="forever/alliance/human/01-elwynn-forest:34:3",["t"]="accept",["npc"]=241,["y"]=0.6726000000000001,["x"]=0.4214,["title"]="Baited for Success",["npcName"]="Remy \"Two Times\"",["pre"]={99130},["qlvl"]=7,["quest"]=99131,["minLevel"]=4},{["map"]=1429,["sourceRouteConditions"]=true,["id"]="forever/alliance/human/01-elwynn-forest:34:4",["t"]="accept",["npc"]=241,["npcName"]="Remy \"Two Times\"",["x"]=0.4214,["title"]="A Fishy Peril",["y"]=0.6726000000000001,["qlvl"]=10,["quest"]=40,["minLevel"]=7},{["map"]=1429,["sourceRouteConditions"]=true,["id"]="forever/alliance/human/01-elwynn-forest:34:5",["t"]="turnin",["npc"]=240,["npcName"]="Marshal Dughan",["x"]=0.4211,["title"]="A Fishy Peril",["quest"]=40,["y"]=0.6593000000000001},{["map"]=1429,["sourceRouteConditions"]=true,["id"]="forever/alliance/human/01-elwynn-forest:34:6",["