nk"]=1,["kind"]="elite",["near"]=true,["lvl"]=11},["fromId"]=562103,["t"]="collect",["fromKind"]="object",["item"]=247813,["y"]=0.764,["x"]=0.745,["title"]="Downstream",["from"]="Waterlogged Saw",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:goal:61:1",["count"]=1,["quest"]=91733,["sourceRouteConditions"]=true},{["map"]=1429,["oi"]=2,["id"]="forever/alliance/human/01-elwynn-forest:57:4",["t"]="kill",["npc"]=822,["y"]=0.804,["x"]=0.7340000000000001,["title"]="Protect the Frontier",["count"]=5,["target"]="Young Forest Bear",["quest"]=52,["spread"]=true,["sourceRouteConditions"]=true},{["map"]=1429,["itemName"]="Brass Collar",["oi"]=1,["note"]="Brass Collar: Princess",["fromId"]=330,["t"]="collect",["quest"]=88,["count"]=1,["y"]=0.7925,["x"]=0.6966,["item"]=1006,["from"]="Princess",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:goal:61:3",["title"]="Princess Must Die!",["fromKind"]="npc",["sourceRouteConditions"]=true},{["map"]=1429,["itemName"]="Waterlogged Toolbox",["oi"]=3,["fromId"]=562106,["group"]={["rank"]=1,["kind"]="elite",["near"]=true,["lvl"]=12},["t"]="collect",["fromKind"]="object",["item"]=247818,["y"]=0.867,["x"]=0.773,["title"]="Downstream",["from"]="Waterlogged Toolbox",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:goal:61:4",["count"]=1,["quest"]=91733,["sourceRouteConditions"]=true},{["map"]=1429,["itemName"]="Waterlogged Axe",["oi"]=1,["fromId"]=562105,["group"]={["rank"]=1,["kind"]="elite",["near"]=true,["lvl"]=12},["t"]="collect",["fromKind"]="object",["item"]=247817,["y"]=0.8240000000000001,["x"]=0.767,["title"]="Downstream",["from"]="Waterlogged Axe",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:goal:61:5",["count"]=1,["quest"]=91733,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:step:61",["text"]="Downstream and Princess",["sourceRouteConditions"]=true,["detail"]="The Waterlogged Saw, Axe and Toolbox lie in the river south of the bridge. Princess, a big boar, roots in the Brackwell Pumpkin Patch west of the river with her Porcine Entourage: pull the piglets away first. Kill Young Forest Bears on the way; the Prowlers (level 9-10) wait for the walk back to Guard Thomas, after the logging camp and the mine. Careful: Croaky is a level 11 elite on the murloc shore. Only go for his head with a group; otherwise leave him: it's optional."},{["goals"]={{["itemName"]="Croaky's Head",["sourceRouteConditions"]=true,["group"]={["kind"]="elite",["rank"]=1,["lvl"]=11},["soloWhen"]={{["k"]="group",["q"]=91740}},["item"]=247826,["fromRank"]=1,["map"]=1429,["fromId"]=248278,["t"]="collect",["y"]=0.8327,["x"]=0.7689,["count"]=1,["lvl"]=11,["from"]="Croaky",["note"]="Croaky's Head: Croaky",["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:goal:62:1"},{["optional"]=true,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:goal:62:2",["t"]="accept",["soloWhen"]={{["k"]="group",["q"]=91740}},["title"]="Croaky's Head",["itemName"]="Croaky's Head",["qlvl"]=11,["minLevel"]=7,["quest"]=91740,["item"]=247826}},["detail"]="Croaky is a level 11 elite on the murloc shore south of the bridge: grouping up is encouraged, look for people to do it with. Croaky's Head needs a group of 2. Skip it if you are alone: the route has you grind the XP back. Right-click the head for its quest.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:step:62",["text"]="Croaky",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="group",["q"]=91740}}},{["goals"]={{["map"]=1429,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/human/01-elwynn-forest:goal:63:1",["t"]="turnin",["npc"]=248277,["