e"]="The Sprouted Fronds"},{["map"]=1438,["itemName"]="Dewy Lasher Frond",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:goal:65:4",["t"]="collect",["title"]="The Great Tree Provides",["y"]=0.6907,["x"]=0.607,["count"]=6,["lvl"]=10,["spread"]=true,["item"]=286017,["quest"]=99050,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:step:65",["text"]="Lake Al'Ameth",["sourceRouteConditions"]=true,["detail"]="South-east of Dolanaar, to Denalan. Lasher Sproutlings wander around him on the shore."},{["goals"]={{["map"]=1438,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:goal:66:1",["t"]="kill",["npc"]=2039,["y"]=0.7981,["x"]=0.3883,["title"]="Ursal the Mauler",["target"]="Ursal the Mauler",["count"]=1,["quest"]=486,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:step:66",["text"]="Ursal the Mauler",["sourceRouteConditions"]=true,["detail"]="South-west from Lake Al'Ameth, past the Pools of Arlithrien: Ursal prowls the far south of the island.\nCareful: Gnarlpine of roughly level 9-11 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."},{["goals"]={{["map"]=1438,["sourceRouteConditions"]=true,["id"]="forever/alliance/nightelf/01-teldrassil:37:5",["t"]="turnin",["npc"]=2078,["npcName"]="Athridas Bearmantle",["x"]=0.5596,["title"]="Ursal the Mauler",["quest"]=486,["y"]=0.5727},{["map"]=1438,["note"]="Byancie, inside",["sourceRouteConditions"]=true,["id"]="forever/alliance/nightelf/01-teldrassil:39:1",["t"]="turnin",["npc"]=6094,["npcName"]="Byancie",["x"]=0.5529,["title"]="The Great Tree Provides",["quest"]=99050,["y"]=0.5682},{["map"]=1438,["sourceRouteConditions"]=true,["id"]="forever/alliance/nightelf/01-teldrassil:39:2",["t"]="accept",["npc"]=6094,["y"]=0.5682,["x"]=0.5529,["title"]="Easing Suffering",["npcName"]="Byancie",["pre"]={99050},["qlvl"]=10,["quest"]=99073,["minLevel"]=4}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:step:67",["text"]="Dolanaar again",["sourceRouteConditions"]=true,["detail"]="North-east from Ursal's den, back to Dolanaar. Byancie takes a Refreshing Spring Water with the fronds and the vial: if you drank yours, buy another from Innkeeper Keldamyr in this inn before you hand in."},{["goals"]={{["map"]=1438,["note"]="Webwood Lurker: tame it with the Taming Rod",["oi"]=1,["count"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:goal:68:1",["t"]="kill",["npc"]=1998,["spread"]=true,["y"]=0.5584,["x"]=0.5817,["title"]="Taming the Beast",["lvl"]=6,["target"]="Webwood Lurker",["text"]="Tame Webwood Lurker",["quest"]=6063,["sourceRouteConditions"]=true},{["map"]=1438,["sourceRouteConditions"]=true,["id"]="forever/alliance/nightelf/01-teldrassil:40:2",["t"]="turnin",["npc"]=3601,["npcName"]="Dazalar",["x"]=0.5668,["title"]="Taming the Beast",["quest"]=6063,["y"]=0.5949},{["map"]=1438,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:goal:68:3",["t"]="accept",["npc"]=3601,["y"]=0.5949,["x"]=0.5668,["title"]="Taming the Beast",["npcName"]="Dazalar",["pre"]={6063,94013},["qlvl"]=10,["quest"]=6101,["minLevel"]=10},{["map"]=1438,["note"]="Nightsaber Stalker: tame it with the Taming Rod",["oi"]=1,["count"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:goal:68:4",["t"]="kill",["npc"]=2043,["spread"]=true,["y"]=0.7227,["x"]=0.5579,["title"]="Taming the Beast",["lvl"]=8,["target"]="Nightsaber Stalker",["text"]="Tame Nightsaber Stalker",["quest"]=6101,["sourceRouteConditions"]=true},{["map"]=1438,["sourceRouteConditions"]=true,["id"]="forever/alliance/nightelf/01-teldrassil:40:5",["t"]="turnin",["npc"]=3601,["npcName"]="Dazalar",["x"]=0.5668,["title"]="Taming the Beast",["quest"]=6101,["y"]=0.5949},{["map"]=1438,["sourceRouteConditions"]=true,["id"]="forever/alliance/nightelf/01-teldrassil:40:6",["t"]="accept",["npc"]=3601,["y"]=0.5949,["x"]=0.5668,["title"]="Taming the Beast",["npcName"]="Dazalar",["pre"]={6101},["qlvl"]=10,["quest"]=6102,["minLevel"]=10},{["map"]=1438,["note"]="Strigid Screecher: tame it with the Taming Rod",["oi"]=1,["count"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:goal:68:7",["t"]="kill",["npc"]=1996,["spread"]=true,["y"]=0.6723,["x"]=0.642,["title"]="Taming the Beast",["lvl"]=8,["target"]="Strigid Screecher",["text"]="Tame Strigid Screecher",["quest"]=6102,["sourceRouteConditions"]=true},{["map"]=1438,["note"]="Tame Beast",["sourceRouteConditions"]=true,["id"]="forever/alliance/nightelf/01-teldrassil:40:8",["t"]="turnin",["npc"]=3601,["npcName"]="Dazalar",["x"]=0.5668,["title"]="Taming the Beast",["quest"]=6102,["y"]=0.5949},{["map"]=1438,["note"]="Jocaste in Darnassus takes it",["sourceRouteConditions"]=true,["id"]="forever/alliance/nightelf/01-teldrassil:40:9",["t"]="accept",["npc"]=3601,["y"]=0.5949,["x"]=0.5668,["title"]="Training the Beast",["npcName"]="Dazalar",["pre"]={6102},["qlvl"]=10,["quest"]=6103,["minLevel"]=10}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:step:68",["text"]="Taming the Beast",["only"]={["classes"]={"HUNTER"}},["detail"]="Each of Dazalar's quests hands you a Taming Rod: use it on the beast he names, then bring the rod back to him in Dolanaar. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."},{["goals"]={{["map"]=1438,["sourceRouteConditions"]=true,["id"]="forever/alliance/nightelf/01-teldrassil:41:1",["t"]="turnin",["npc"]=275683,["npcName"]="Sentinel Eralya Leafshadow",["x"]=0.3754,["title"]="Easing Suffering",["quest"]=99073,["y"]=0.36810000000000004}},["id"]="forever/alliance/nightelf/01-teldrassil:41",["text"]="Sentinel Eralya Leafshadow",["sourceRouteConditions"]=true,["detail"]="Take the road north-west from Dolanaar again; she still lies beside it, on the way to Darnassus."},{["goals"]={{["map"]=1457,["note"]="Mydrannul, on the Craftsmen's Terrace just inside the city",["sourceRouteConditions"]=true,["endNpcs"]={10118},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:goal:70:1",["t"]="accept",["npc"]=4241,["xp"]=210,["npcName"]="Mydrannul",["x"]=0.7068000000000001,["qlvl"]=10,["y"]=0.45380000000000004,["closedBy"]={6341},["title"]="Nessa Shadowsong",["quest"]=6344,["minLevel"]=10}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:step:70",["text"]="Into Darnassus",["only"]={["classes"]={"WARRIOR"}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1457,["x"]=0.573,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:goal:71:1",["text"]="Elanaria",["t"]="goto",["y"]=0.34600000000000003}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:step:71",["text"]="Darnassus",["only"]={["classes"]={"WARRIOR"}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1457,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:goal:72:1",["t"]="turnin",["npc"]=4088,["npcName"]="Elanaria",["x"]=0.573,["title"]="Elanaria",["quest"]=1684,["y"]=0.3461},{["map"]=1457,["sourceRouteConditions"]=true,["endNpcs"]={4088},["id"]="refresh:forever-20261117-b753c783:polestar:forever/alliance/nightelf/01-teldrassil:goal:72:2",["t"]="accept",["xp"]=850,["npc"]=4088,["y"]=0.3461,["x"]=0.573,["title"]="Vorlus Vilehoof",["npcName"]="Elanaria",["closedBy"]={1639,1678},["qlvl"]=10,["quest"]=1683,["minLevel"]=10}},["sourceRouteConditions"]=true,["id"]=