RouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/priest/priest-robes-alliance:goal:8:1",["t"]="turnin",["npc"]=1226,["npcName"]="Maxan Anvol",["x"]=0.47340000000000004,["title"]="Garments of the Light",["rewards"]={["items"]={{["item"]=16605,["itemName"]="Friar's Robes of the Light"}}},["quest"]=5625,["y"]=0.5219}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/priest/priest-robes-alliance:step:8",["text"]="Maxan Anvol",["only"]={["races"]={"Dwarf","Gnome"}},["detail"]="Back inside the Thunderbrew Distillery: Maxan Anvol gives you Friar's Robes of the Light."},{["goals"]={{["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/priest/priest-robes-alliance:goal:9:1",["level"]=5,["sourceRouteConditions"]=true,["t"]="level"},{["map"]=1438,["sourceRouteConditions"]=true,["endNpcs"]={3600},["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/priest/priest-robes-alliance:goal:9:2",["t"]="accept",["xp"]=90,["npc"]=3595,["y"]=0.4044,["x"]=0.5917,["title"]="In Favor of Elune",["npcName"]="Shanda",["closedBy"]={5621},["qlvl"]=4,["quest"]=5622,["minLevel"]=5}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/priest/priest-robes-alliance:step:9",["text"]="In Favor of Elune",["only"]={["races"]={"NightElf"}},["detail"]="At 5, Shanda, the priest trainer on the second level of Aldrassil, the great tree in Shadowglen, sends you to Laurna Morninglight in Dolanaar. Train Lesser Heal (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."},{["goals"]={{["map"]=1438,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/priest/priest-robes-alliance:goal:10:1",["t"]="turnin",["npc"]=3600,["npcName"]="Laurna Morninglight",["x"]=0.5556,["title"]="In Favor of Elune",["quest"]=5622,["y"]=0.5675},{["map"]=1438,["crumbs"]={5622},["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/priest/priest-robes-alliance:goal:10:2",["t"]="accept",["npc"]=3600,["y"]=0.5675,["x"]=0.5556,["title"]="Garments of the Moon",["npcName"]="Laurna Morninglight",["minLevel"]=5,["qlvl"]=4,["quest"]=5621,["sourceRouteConditions"]=true},{["note"]="Lesser Heal (Rank 2), if Shanda did not teach it yet",["sourceRouteConditions"]=true,["zone"]=1438,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/priest/priest-robes-alliance:goal:10:3",["t"]="train",["class"]=true,["locations"]={{["map"]=1438,["x"]=0.5556,["npcName"]="Laurna Morninglight",["npc"]=3600,["y"]=0.5675},{["map"]=1438,["x"]=0.5917,["npcName"]="Shanda",["npc"]=3595,["y"]=0.4044},{["map"]=1457,["x"]=0.39520000000000005,["npcName"]="Priestess Alathea",["npc"]=11401,["y"]=0.812},{["map"]=1426,["x"]=0.28600000000000003,["npcName"]="Branstock Khalder",["npc"]=837,["y"]=0.6639},{["map"]=1426,["x"]=0.47340000000000004,["npcName"]="Maxan Anvol",["npc"]=1226,["y"]=0.5219},{["map"]=1429,["x"]=0.49810000000000004,["npcName"]="Priestess Anetta",["npc"]=375,["y"]=0.39490000000000003},{["map"]=1429,["x"]=0.4328,["npcName"]="Priestess Josetta",["npc"]=377,["y"]=0.6572},{["npcName"]="High Priestess Laurena",["x"]=0.4953,["y"]=0.446,["npc"]=376,["map"]=1453},{["npcName"]="Nara Meideros",["x"]=0.3568,["y"]=0.6318,["npc"]=11397,["map"]=1453},{["map"]=1455,["x"]=0.2408,["npcName"]="Theodrus Frostbeard",["npc"]=5141,["y"]=0.08410000000000001}}}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/priest/priest-robes-alliance:step:10",["text"]="Laurna Morninglight",["only"]={["races"]={"NightElf"}},["detail"]="Leave Shadowglen by the ramp and follow the road south-west to Dolanaar. Laurna Morninglight is in the building at the north edge of the village."},{["goals"]={{["map"]=1438,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/class/priest/priest-robes-alliance:goal:11:1",["t"]="kill",["npc"]=12429,[