title"]="Consumed by Hatred",["from"]="Bristleback Hunter",["lvl"]=20,["count"]=60,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/02-the-barrens:goal:79:4"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/02-the-barrens:step:79",["text"]="Bramblescar",["sourceRouteConditions"]=true,["detail"]="Back north into the Bristleback camps. Any Bristleback can drop a tusk for Mankrik, so collect them while you kill these for Mangletooth. Keep one Blood Shard."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/02-the-barrens:step:80",["text"]="Camp Taurajo",["goals"]={{["map"]=1413,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/02-the-barrens:goal:80:1",["t"]="turnin",["npc"]=3430,["npcName"]="Mangletooth",["x"]=0.44549999999999995,["title"]="Tribes at War",["quest"]=878,["y"]=0.5926},{["map"]=1413,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/02-the-barrens:goal:80:2",["t"]="accept",["npc"]=3430,["y"]=0.5926,["x"]=0.44549999999999995,["title"]="Blood Shards of Agamaggan",["npcName"]="Mangletooth",["pre"]={878},["qlvl"]=21,["quest"]=5052,["minLevel"]=14}},["sourceRouteConditions"]=true},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/02-the-barrens:step:81",["text"]="Agama'gor",["goals"]={{["itemName"]="Blood Shard",["sourceRouteConditions"]=true,["item"]=5075,["quest"]=5052,["map"]=1413,["oi"]=1,["fromAlsoId"]=3261,["fromId"]=3263,["fromAlso"]="Bristleback Thornweaver",["t"]="collect",["spread"]=true,["y"]=0.5526,["x"]=0.4509,["title"]="Blood Shards of Agamaggan",["from"]="Bristleback Geomancer",["lvl"]=20,["count"]=1,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/02-the-barrens:goal:81:1"},{["map"]=1413,["itemName"]="Hoof of Lakota'mani",["sourceRouteConditions"]=true,["fromId"]=3474,["t"]="collect",["optional"]=true,["y"]=0.5274,["x"]=0.45130000000000