etail"]="Grish Longrunner and Brave Moonhorn wait at the top of the Great Lift: Maggran's letter is for Grish Longrunner, and Moonhorn's message goes down to Freewind Post with you."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:59",["text"]="Freewind Post's lift",["goals"]={{["map"]=1441,["x"]=0.449,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:59:1",["text"]="Freewind Post's lift",["t"]="goto",["y"]=0.489}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1441,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:60:1",["t"]="getfp",["npc"]=4317,["npcName"]="Nyse",["x"]=0.4514,["location"]="Freewind Post",["y"]=0.4911,["node"]=30,["area"]=484},{["map"]=1441,["note"]="Elu, by the wind rider master",["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:29:6",["t"]="accept",["npc"]=10377,["npcName"]="Elu",["x"]=0.4493,["title"]="Wind Rider",["y"]=0.4892,["qlvl"]=29,["quest"]=4767,["minLevel"]=25},{["map"]=1441,["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:29:5",["t"]="accept",["npc"]=10539,["npcName"]="Hagar Lightninghoof",["x"]=0.4464,["title"]="Alien Egg",["y"]=0.5029,["qlvl"]=26,["quest"]=4821,["minLevel"]=24},{["map"]=1441,["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:29:3",["t"]="turnin",["npc"]=10537,["npcName"]="Cliffwatcher Longhorn",["x"]=0.4567,["title"]="Message to Freewind Post",["quest"]=4542,["y"]=0.5074000000000001},{["map"]=1441,["crumbs"]={4542},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:60:5",["t"]="accept",["npc"]=10537,["y"]=0.5074000000000001,["x"]=0.4567,["title"]="Pacify the Centaur",["npcName"]="Cliffwatcher Longhorn",["minLevel"]=23,["qlvl"]=25,["quest"]=4841,["sourceRouteConditions"]=true},{["map"]=1441,["note"]="The Wanted poster beside Cliffwatcher Longhorn",["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:29:8",["t"]="accept",["y"]=0.5085999999999999,["x"]=0.46,["title"]="WANTED: Arnak Grimtotem",["objName"]="Wanted Poster - Arnak Grimtotem",["qlvl"]=29,["minLevel"]=25,["quest"]=5147,["object"]=176115},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:60:7",["text"]="Jandia's two harpy quests are taken when you leave Freewind; their den comes with the next Freewind visit, at about 30.",["sourceRouteConditions"]=true,["t"]="note"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:60",["text"]="Freewind Post",["sourceRouteConditions"]=true,["detail"]="Ride the lift down, then follow the road east through the canyons to Freewind Post, a Tauren village on top of the mesas. Its lift is on the north side."},{["goals"]={{["map"]=1441,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:61:1",["t"]="turnin",["npc"]=4722,["soloWhen"]={{["k"]="onquest",["q"]={1196}}},["npcName"]="Rau Cliffrunner",["x"]=0.46140000000000003,["title"]="The Sacred Flame",["quest"]=1196,["y"]=0.5171},{["map"]=1441,["note"]="Rau Cliffrunner: the Ancient Brazier in Splithoof Hold, among the Galak camps",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:61:2",["t"]="accept",["npc"]=4722,["soloWhen"]={{["k"]="onquest",["q"]={1196}}},["y"]=0.5171,["x"]=0.46140000000000003,["title"]="The Sacred Flame",["npcName"]="Rau Cliffrunner",["pre"]={1196},["qlvl"]=29,["quest"]=1197,["minLevel"]=20}},["detail"]="Rau Cliffrunner stands in Freewind Post: Zangen Stonehoof's filled phial is for him.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:61",["text"]="Rau Cliffrunner",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="onquest",["q"]={1196}}}},{["goals"]={{["map"]=1441,["itemName"]="Alien Egg",["oi"]=1,["fromId"]=175565,["group"]={["rank"]=1,["kind"]="elite",["near"]=true,["lvl"]=30},["t"]="collect",["quest"]=4821,["count"]=1,["y"]=0.561,["x"]=0.376,["item"]=12467,["from"]="Alien Egg",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:62:1",["title"]="Alien Egg",["fromKind"]="object",["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:62",["text"]="Alien Egg",["sourceRouteConditions"]=true,["detail"]="Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."},{["goals"]={{["map"]=1441,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:63:1",["t"]="kill",["npc"]=4094,["y"]=0.4354,["x"]=0.45530000000000004,["title"]="Pacify the Centaur",["lvl"]=25,["target"]="Galak Scout",["count"]=12,["quest"]=4841,["sourceRouteConditions"]=true},{["map"]=1441,["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:63:2",["t"]="kill",["npc"]=4093,["y"]=0.4188,["x"]=0.46130000000000004,["title"]="Pacify the Centaur",["lvl"]=26,["target"]="Galak Wrangler",["count"]=10,["quest"]=4841,["sourceRouteConditions"]=true},{["map"]=1441,["oi"]=3,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:63:3",["t"]="kill",["npc"]=4096,["y"]=0.41159999999999997,["x"]=0.4657,["title"]="Pacify the Centaur",["lvl"]=25,["target"]="Galak Windchaser",["count"]=6,["quest"]=4841,["sourceRouteConditions"]=true},{["map"]=1441,["itemName"]="Assassination Note",["sourceRouteConditions"]=true,["fromId"]=10617,["t"]="collect",["y"]=0.331,["x"]=0.3943,["item"]=12564,["from"]="Galak Messenger",["note"]="Galak Messenger's Assassination Plot, if you meet him",["optional"]=true,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:63:4"},{["optional"]=true,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:63:5",["t"]="accept",["title"]="Assassination Plot",["itemName"]="Assassination Note",["qlvl"]=28,["minLevel"]=23,["quest"]=4881,["item"]=12564}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:63",["text"]="Galak centaurs",["sourceRouteConditions"]=true,["detail"]="The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone Galak Messenger walks a long path between the camps: if you meet him, kill him, his note starts a quest for Whitereach Post. Don't wait for him. Careful: storm elementals roam the canyon floor around the camps: Stormheart (30), the Ravaging Tempests (40) and Ailgrha Splittusk (38), all elite. Keep clear of them."},{["goals"]={{["map"]=1441,["itemName"]="Filled Etched Phial",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:64:1",["t"]="use",["soloWhen"]={{["k"]="onquest",["q"]={1197}}},["y"]=0.315,["x"]=0.42,["title"]="The Sacred Flame",["note"]="Filled Etched Phial, at the Ancient Brazier",["item"]=5868,["quest"]=1197,["sourceRouteConditions"]=true},{["itemName"]="Cloven Hoof",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="onquest",["q"]={1197}}},["item"]=5869,["quest"]=1197,["map"]=1441,["oi"]=1,["fromId"]=20807,["t"]="collect",["y"]=0.315,["x"]=0.42,["title"]="The Sacred Flame",["from"]="Ancient Brazier",["note"]="Cloven Hoof, from the Ancient Brazier",["count"]=1,["fromKind"]="object",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:64:2"}},["detail"]="A short walk north of the Galak camps, the cave of Splithoof Hold leads down to its deepest chamber, where the Ancient Brazier burns. Use the Filled Etched Phial on it, then loot the Cloven Hoof at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to Dorn Plainstalker's mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:64",["text"]="Splithoof Hold",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="onquest",["q"]={1197}}}},{["goals"]={{["map"]=1441,["note"]="Dorn Plainstalker, below ground",["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:33:1",["t"]="accept",["npc"]=2986,["npcName"]="Dorn Plainstalker",["x"]=0.5395,["title"]="Test of Faith",["y"]=0.41490000000000005,["qlvl"]=26,["quest"]=1149,["minLevel"]=25},{["map"]=1441,["note"]="the end of the planks",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:65:2",["t"]="complete",["objs"]={{["count"]=1,["text"]="If you have faith, leap from the planks overlooking Thousand Needles."}},["y"]=0.3293,["x"]=0.2643,["title"]="Test of Faith",["quest"]=1149},{["map"]=1441,["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:33:3",["t"]="turnin",["npc"]=2986,["npcName"]="Dorn Plainstalker",["x"]=0.5395,["title"]="Test of Faith",["quest"]=1149,["y"]=0.41490000000000005},{["map"]=1441,["note"]="Dorn Plainstalker: Grenka Bloodscreech, in the harpy den west of the post",["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:33:4",["t"]="accept",["npc"]=2986,["y"]=0.41490000000000005,["x"]=0.5395,["title"]="Test of Endurance",["npcName"]="Dorn Plainstalker",["pre"]={1149},["qlvl"]=30,["quest"]=1150,["minLevel"]=25},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:65:5",["text"]="Test of Endurance (Grenka Bloodscreech, 31) waits for the next Freewind visit, at about 30: keep it.",["sourceRouteConditions"]=true,["t"]="note"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:65",["text"]="Dorn Plainstalker",["sourceRouteConditions"]=true,["detail"]="Dorn Plainstalker stands on a mesa top east of the Galak camps. Taking his Test of Faith puts you on a high cliff far to the west: follow the stone path to the end of the wooden planks and step off there, and you land safely. Jump from anywhere else and you fall to your death."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:66",["text"]="Freewind Post",["goals"]={{["map"]=1441,["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:34:1",["t"]="turnin",["npc"]=10537,["npcName"]="Cliffwatcher Longhorn",["x"]=0.4567,["title"]="Pacify the Centaur",["quest"]=4841,["y"]=0.5074000000000001},{["map"]=1441,["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:34:2",["t"]="accept",["npc"]=10537,["y"]=0.5074000000000001,["x"]=0.4567,["title"]="Grimtotem Spying",["npcName"]="Cliffwatcher Longhorn",["pre"]={4841},["qlvl"]=28,["quest"]=5064,["minLevel"]=24},{["map"]=1441,["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:31:1",["t"]="turnin",["npc"]=10539,["npcName"]="Hagar Lightninghoof",["x"]=0.4464,["title"]="Alien Egg",["quest"]=4821,["y"]=0.5029},{["map"]=1441,["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:31:2",["t"]="accept",["npc"]=10539,["y"]=0.5029,["x"]=0.4464,["title"]="Serpent Wild",["npcName"]="Hagar Lightninghoof",["pre"]={4821},["qlvl"]=26,["quest"]=4865,["minLevel"]=24},{["map"]=1441,["note"]="Innkeeper Abeqwa, beside Jandia",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:66:5",["t"]="sethome",["npc"]=11116,["npcName"]="Innkeeper Abeqwa",["x"]=0.4607,["location"]="Freewind Post",["y"]=0.5152,["area"]=484}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1441,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:67:1",["t"]="turnin",["npc"]=4722,["soloWhen"]={{["k"]="complete",["q"]=1197}},["npcName"]="Rau Cliffrunner",["x"]=0.46140000000000003,["title"]="The Sacred Flame",["quest"]=1197,["y"]=0.5171}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:67",["text"]="Rau Cliffrunner",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="complete",["q"]=1197}}},{["goals"]={{["map"]=1441,["note"]="Document Chest, south-east camp",["oi"]=3,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:68:1",["t"]="interact",["y"]=0.415,["x"]=0.39299999999999996,["title"]="Grimtotem Spying",["objName"]="Document Chest",["object"]=190484,["quest"]=5064,["sourceRouteConditions"]=true},{["map"]=1441,["note"]="Document Chest, south-west camp",["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:68:2",["t"]="interact",["y"]=0.4,["x"]=0.33799999999999997,["title"]="Grimtotem Spying",["objName"]="Document Chest",["object"]=190483,["quest"]=5064,["sourceRouteConditions"]=true},{["map"]=1441,["note"]="Document Chest, north-west camp",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:68:3",["t"]="interact",["y"]=0.326,["x"]=0.318,["title"]="Grimtotem Spying",["objName"]="Document Chest",["object"]=176344,["quest"]=5064,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:68",["text"]="Darkcloud Pinnacle",["sourceRouteConditions"]=true,["detail"]="West of Freewind, the Grimtotem camps below Darkcloud Pinnacle. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."},{["goals"]={{["map"]=1441,["x"]=0.35,["sourceRouteConditions"]=true,["text"]="Grimtotem camps below Darkcloud Pinnacle",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:69:1",["t"]="goto",["y"]=0.315,["soloWhen"]={{["op"]="<",["k"]="level",["n"]=28}}},{["map"]=1441,["note"]="grind on Grimtotem Stomper",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:69:2",["t"]="level",["soloWhen"]={{["op"]="<",["k"]="level",["n"]=28}},["npcName"]="Grimtotem Stomper",["x"]=0.3496,["lvl"]=27,["level"]=28,["y"]=0.3103,["grind"]=10759}},["detail"]="Short of 28? The Grimtotem around these camps (25-28) are the right level: kill a few more before the climb to Lakota Windsong. Past it, this step skips itself. Or, with a group, run the Blackfathom Deeps dungeon instead.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:69",["text"]="Level 28",["sourceRouteConditions"]=true,["soloWhen"]={{["op"]="<",["k"]="level",["n"]=28}}},{["goals"]={{["map"]=1441,["itemName"]="Arnak's Hoof",["oi"]=1,["fromId"]=10896,["t"]="collect",["title"]="WANTED: Arnak Grimtotem",["fromKind"]="npc",["y"]=0.26899999999999996,["x"]=0.381,["count"]=1,["from"]="Arnak Grimtotem",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:70:1",["item"]=12884,["quest"]=5147,["sourceRouteConditions"]=true},{["map"]=1441,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:70:2",["t"]="accept",["npc"]=10646,["npcName"]="Lakota Windsong",["x"]=0.3795,["escort"]=true,["title"]="Free at Last",["y"]=0.2645,["qlvl"]=29,["quest"]=4904,["minLevel"]=25},{["escort"]=true,["title"]="Free at Last",["quest"]=4904,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:70:3",["t"]="complete",["objs"]={{["count"]=1,["text"]="Escort Lakota Windsong from the Darkcloud Pinnacle."}},["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:70",["text"]="Lakota Windsong",["sourceRouteConditions"]=true,["detail"]="Great Lift detour warning: the arrow may miss the path up Darkcloud Pinnacle. If you are on the canyon floor, follow the path and rope bridges up Darkcloud Pinnacle. Lakota Windsong is held captive beside Arnak Grimtotem (29): clear the guards and Arnak Grimtotem first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."},{["goals"]={{["map"]=1441,["itemName"]="Highperch Wyvern Egg",["oi"]=1,["fromId"]=175384,["t"]="collect",["title"]="Wind Rider",["fromKind"]="object",["y"]=0.4168,["x"]=0.1802,["count"]=10,["from"]="Highperch Wyvern Egg",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:71:1",["item"]=12356,["quest"]=4767,["sourceRouteConditions"]=true},{["map"]=1441,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:71:2",["t"]="accept",["npc"]=10427,["npcName"]="Pao'ka Swiftmountain",["x"]=0.1789,["escort"]=true,["title"]="Homeward Bound",["y"]=0.4057,["qlvl"]=29,["quest"]=4770,["minLevel"]=25},{["escort"]=true,["title"]="Homeward Bound",["quest"]=4770,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:71:3",["t"]="complete",["objs"]={{["count"]=1,["text"]="Escort Pao'ka from Highperch"}},["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:71",["text"]="Highperch",["sourceRouteConditions"]=true,["detail"]="West of Whitereach the wyverns nest on the Highperch cliffs; the eggs lie in the nests. Pao'ka Swiftmountain waits on the east side of the nesting grounds: free him and keep him alive on the walk back to Whitereach Post.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom. Highperch Patriarchs (30-31) and the rare Heartrazor (32) nest here too: pull around them."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:72",["text"]="Whitereach Post",["goals"]={{["map"]=1441,["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:39:1",["t"]="turnin",["npc"]=10428,["npcName"]="Motega Firemane",["x"]=0.21539999999999998,["title"]="Homeward Bound",["quest"]=4770,["y"]=0.3235},{["map"]=1441,["sourceRouteConditions"]=true,["id"]="forever/horde/07-ashenvale:37:1",["t"]="turnin",["npc"]=10428,["npcName"]="Motega Firemane",["x"]=0.21539999999999998,["title"]="Serpent Wild",["quest"]=4865,["y"]=0.3235},{["id"]="forever/horde/07-ashenvale:37:2",["text"]="Motega Firemane's next quest, Sacred Fire, ends in Thunder Bluff, off this route. Skip it.",["sourceRouteConditions"]=true,["t"]="note"}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1441,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:73:1",["t"]="turnin",["npc"]=10638,["soloWhen"]={{["k"]="onquest",["q"]={4881,4966}}},["npcName"]="Kanati Greycloud",["x"]=0.2125,["title"]="Assassination Plot",["quest"]=4881,["y"]=0.3206},{["map"]=1441,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:73:2",["t"]="accept",["npc"]=10638,["soloWhen"]={{["k"]="onquest",["q"]={4881,4966}}},["y"]=0.3206,["x"]=0.2125,["title"]="Protect Kanati Greycloud",["npcName"]="Kanati Greycloud",["pre"]={4881},["qlvl"]=28,["quest"]=4966,["minLevel"]=23}},["detail"]="Only if the Galak Messenger dropped his plot for you: Kanati Greycloud stands at Whitereach Post.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:73",["text"]="Kanati Greycloud",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="onquest",["q"]={4881,4966}}}},{["goals"]={{["map"]=1441,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:goal:74:1",["t"]="accept",["npc"]=10941,["soloWhen"]={{["k"]="group",["q"]=5151}},["npcName"]="Wizlo Bearingshiner",["x"]=0.2143,["title"]="Hypercapacitor Gizmo",["y"]=0.32549999999999996,["qlvl"]=30,["quest"]=5151,["minLevel"]=24}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/07-ashenvale:step:74",["text"]="Wizlo Bearingshiner",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="group",["q"]=5151