oWhen"]={{["op"]=">=",["k"]="level",["n"]=30}},["npcName"]="Tallow",["qlvl"]=32,["quest"]=676,["map"]=1424,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/01-hillsbrad-foothills:goal:43:4",["t"]="accept",["xp"]=2550,["closedBy"]={677},["x"]=0.6187,["title"]="The Hammer May Fall",["y"]=0.1957,["minLevel"]=30},{["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/01-hillsbrad-foothills:goal:43:5",["text"]="Keep these in your log: their camps are two to four levels over you now, and the 38-39 guide works them on its first Tarren Mill loop and in Hammerfall.",["t"]="note",["soloWhen"]={{["op"]=">=",["k"]="level",["n"]=30}}}},["detail"]="Magus Wordeen Voidglare and Keeper Bel'varil are inside the inn, Tallow just outside it. Their quests are offered from level 30; below it, the 38-39 guide's first Tarren Mill stop takes them.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/01-hillsbrad-foothills:step:43",["text"]="Voidglare, Bel'varil and Tallow",["sourceRouteConditions"]=true,["soloWhen"]={{["op"]=">=",["k"]="level",["n"]=30}}},{["goals"]={{["map"]=1424,["sourceRouteConditions"]=true,["group"]={["map"]=2959,["kind"]="dungeon",["name"]="City of Dalaran"},["t"]="turnin",["npc"]=2278,["soloWhen"]={{["map"]=2959,["k"]="dungeon",["name"]="City of Dalaran"},{["k"]="complete",["q"]=96986}},["npcName"]="Melisara",["x"]=0.6263000000000001,["title"]="The Grave Knight",["y"]=0.2065,["quest"]=96986,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/01-hillsbrad-foothills:goal:44:1"}},["detail"]="The Grave Knight from your City of Dalaran run: Melisara, a short walk east of Magus Wordeen Voidglare.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/01-hillsbrad-foothills:step:44",["text"]="Melisara",["sourceRouteConditions"]=true,["soloWhen"]={{["map"]=2959,["k"]="dungeon",["name"]="City of Dalaran"},{["k"]="complete",["q"]=96986}}},{["goals"]={{["