]=true},{["goals"]={{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:38:1",["t"]="accept",["npc"]=11596,["npcName"]="Smeed Scrabblescrew",["x"]=0.6086,["title"]="Kodo Roundup",["y"]=0.6186,["qlvl"]=34,["quest"]=5561,["minLevel"]=30}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:38",["text"]="Scrabblescrew's Camp",["sourceRouteConditions"]=true,["detail"]="Head south out of Stonetalon into Desolace and follow the road south to Smeed Scrabblescrew's camp."},{["goals"]={{["map"]=1443,["crumbs"]={1362},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:39:1",["t"]="accept",["npc"]=5395,["y"]=0.5957,["x"]=0.5619,["title"]="Khan Dez'hepah",["npcName"]="Felgur Twocuts",["minLevel"]=30,["qlvl"]=35,["quest"]=1365,["sourceRouteConditions"]=true},{["map"]=1443,["note"]="Nataka Longhorn, up on the rise",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:39:2",["t"]="turnin",["npc"]=11259,["npcName"]="Nataka Longhorn",["x"]=0.5540999999999999,["title"]="Family Tree",["quest"]=5361,["y"]=0.5581}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:39",["text"]="Ghost Walker Post",["sourceRouteConditions"]=true,["detail"]="Felgur Twocuts stands in the post, Nataka Longhorn up on its rise; Takata Steelblade and Maurin Bonesplitter wait on the rise west of it, above the Kodo Graveyard."},{["goals"]={{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:40:1",["t"]="turnin",["npc"]=5641,["soloWhen"]={{["k"]="onquest",["q"]={1432}}},["npcName"]="Takata Steelblade",["x"]=0.5257000000000001,["title"]="Alliance Relations",["quest"]=1432,["y"]=0.5439}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:40",["text"]="Takata Steelblade",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="onquest",["q"]={1432}}}},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:41",["text"]="Takata Steelblade and Maurin Bonesplitter",["goals"]={{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:41:1",["t"]="accept",["npc"]=5641,["y"]=0.5439,["x"]=0.5257000000000001,["title"]="Alliance Relations",["npcName"]="Takata Steelblade",["pre"]={1432},["qlvl"]=33,["quest"]=1433,["minLevel"]=30},{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:41:2",["t"]="accept",["npc"]=5641,["y"]=0.5439,["x"]=0.5257000000000001,["title"]="Befouled by Satyr",["npcName"]="Takata Steelblade",["pre"]={1432},["qlvl"]=33,["quest"]=1434,["minLevel"]=25},{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:41:3",["t"]="turnin",["npc"]=4498,["npcName"]="Maurin Bonesplitter",["x"]=0.5225,["title"]="Alliance Relations",["quest"]=1433,["y"]=0.5344},{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:41:4",["t"]="accept",["npc"]=4498,["y"]=0.5344,["x"]=0.5225,["title"]="The Burning of Spirits",["npcName"]="Maurin Bonesplitter",["pre"]={1433},["qlvl"]=33,["quest"]=1435,["minLevel"]=25}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1443,["itemName"]="Kodo Kombobulator",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:42:1",["t"]="use",["y"]=0.585,["x"]=0.51,["item"]=13892,["note"]="on an Aged, Dying or Ancient Kodo in the graveyard; don't kill it",["text"]="Kodo Kombobulator"},{["map"]=1443,["note"]="the tamed kodo, at Smeed Scrabblescrew's camp: talk to it, five times",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:42:2",["t"]="talk",["npc"]=4700,["npcName"]="Aged Kodo",["x"]=0.606,["title"]="Kodo Roundup",["y"]=0.616,["quest"]=5561,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:42",["text"]="Kodo Graveyard",["sourceRouteConditions"]=true,["detail"]="Use Smeed Scrabblescrew's Kodo Kombobulator on an Aged, Dying or Ancient Kodo in the graveyard and walk the tamed kodo back to Smeed Scrabblescrew. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time. Careful: leave the kodo skulls on the ground alone: opening one raises a Kodo Apparition (37-38) that hits hard."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:43",["text"]="Scrabblescrew's Camp",["goals"]={{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:43:1",["t"]="turnin",["npc"]=11596,["npcName"]="Smeed Scrabblescrew",["x"]=0.6086,["title"]="Kodo Roundup",["quest"]=5561,["y"]=0.6186}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1443,["optional"]=true,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:44:1",["t"]="accept",["npc"]=268705,["npcName"]="Aka'rai",["x"]=0.2532,["title"]="Hate the Hatefury",["note"]="Aka'rai: the Hatefury satyrs of Sargeron, later in this guide",["y"]=0.6705,["qlvl"]=33,["quest"]=97265,["minLevel"]=28},{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:44:2",["t"]="sethome",["npc"]=11106,["npcName"]="Innkeeper Sikewa",["x"]=0.2409,["location"]="Shadowprey Village",["y"]=0.6820999999999999,["area"]=2408},{["map"]=1443,["note"]="Roon Wildmane: for Hemet Nesingwary in Stranglethorn, next guide",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:44:3",["t"]="accept",["npc"]=11877,["npcName"]="Roon Wildmane",["x"]=0.2505,["title"]="Hunting in Stranglethorn",["y"]=0.7227,["qlvl"]=31,["quest"]=5763,["minLevel"]=28},{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:44:4",["t"]="accept",["npc"]=12031,["npcName"]="Mai'Lahii",["x"]=0.22640000000000002,["title"]="Clam Bait",["y"]=0.7197,["qlvl"]=35,["quest"]=6142,["minLevel"]=31},{["map"]=1443,["note"]="Thalon, at the village's south-west end",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:44:5",["t"]="getfp",["npc"]=6726,["npcName"]="Thalon",["x"]=0.21600000000000003,["location"]="Shadowprey Village",["y"]=0.7413,["node"]=38,["area"]=2408}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:44",["text"]="Shadowprey Village",["sourceRouteConditions"]=true,["detail"]="Head west to the troll village on the coast, keeping clear of the Gelkis Village on the way. Aka'rai stands on the path just north of the village.\nAka'rai may not be here on Forever: if Aka'rai doesn't offer Hate the Hatefury, skip it."},{["goals"]={{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:45:1",["t"]="accept",["npc"]=11863,["npcName"]="Azore Aldamort",["x"]=0.38880000000000003,["title"]="Sceptre of Light",["y"]=0.2716,["qlvl"]=33,["quest"]=5741,["minLevel"]=30}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:45",["text"]="Ethel Rethor",["sourceRouteConditions"]=true,["detail"]="Head north along the coast, then inland to the ruined tower of Ethel Rethor: Azore Aldamort waits inside. The coast's clams and naga come after Thunder Axe Fortress, on one walk north to Ranazjar Isle."},{["goals"]={{["map"]=1443,["itemName"]="Infused Burning Gem",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:46:1",["fromNpcsAt"]="3,1,4,5,2;5,4,3;3,5,4,1,6;4,5,1,3;4,1;1,3,4,5,2;3;5,4",["t"]="collect",["y"]=0.265,["x"]=0.55,["title"]="The Burning of Spirits",["lvl"]=32,["item"]=6435,["count"]=15,["quest"]=1435,["sourceRouteConditions"]=true},{["map"]=1443,["itemName"]="Sceptre of Light",["oi"]=1,["note"]="On the top floor",["fromId"]=13019,["t"]="collect",["quest"]=5741,["count"]=1,["y"]=0.301,["x"]=0.552,["item"]=15750,["from"]="Burning Blade Seer",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:46:2",["title"]="Sceptre of Light",["fromKind"]="npc",["sourceRouteConditions"]=true},{["map"]=1443,["itemName"]="Flayed Demon Skin",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:46:3",["t"]="collect",["y"]=0.3005,["x"]=0.5518,["item"]=20310,["lvl"]=32,["optional"]=true,["spread"]=true,["count"]=1},{["optional"]=true,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:46:4",["t"]="accept",["title"]="The Corrupter",["itemName"]="Flayed Demon Skin",["qlvl"]=33,["minLevel"]=25,["quest"]=1480,["item"]=20310}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:46",["text"]="Thunder Axe Fortress",["sourceRouteConditions"]=true,["detail"]="Head east to Thunder Axe Fortress. Beat a Burning Blade cultist down, then use the Burning Gem on it before it dies to fill one Infused Burning Gem. The Burning Blade Seer stands on the fortress's top floor with the Sceptre. The cultists also drop a Flayed Demon Skin now and then (1-5%); if one drops, read it. Leave the red Hand of Iruxos Crystal for now: its Demon Spirit is 37, and the second Desolace visit comes back for it."},{["goals"]={{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:47:1",["t"]="turnin",["npc"]=11863,["npcName"]="Azore Aldamort",["x"]=0.38880000000000003,["title"]="Sceptre of Light",["quest"]=5741,["y"]=0.2716},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:47:2",["text"]="Azore Aldamort's next errand, the Book of the Ancients, needs Lord Kragaru (38) out on Ranazjar Isle: leave it, he is over your level.",["sourceRouteConditions"]=true,["t"]="note"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:47",["text"]="Ethel Rethor",["sourceRouteConditions"]=true,["detail"]="Back west to Azore Aldamort."},{["goals"]={{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:48:1",["t"]="accept",["y"]=0.3041,["x"]=0.3607,["title"]="Claim Rackmore's Treasure!",["objName"]="Rackmore's Log",["qlvl"]=36,["minLevel"]=30,["quest"]=6161,["object"]=177787}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:48",["text"]="Rackmore's Log",["sourceRouteConditions"]=true,["detail"]="Rackmore's Log lies on the ground just south-west of Azore Aldamort's tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."},{["goals"]={{["map"]=1443,["note"]="Giant Softshell Clams, on the sea floor",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:49:1",["t"]="interact",["y"]=0.319,["x"]=0.306,["title"]="Clam Bait",["objName"]="Giant Softshell Clam",["object"]=177784,["quest"]=6142,["sourceRouteConditions"]=true},{["map"]=1443,["itemName"]="Soft-shelled Clam",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:49:2",["t"]="use",["y"]=0.319,["x"]=0.306,["title"]="Clam Bait",["note"]="Soft-shelled Clam: open it in your bags",["item"]=15874,["quest"]=6142,["sourceRouteConditions"]=true},{["map"]=1443,["itemName"]="Soft-shelled Clam Meat",["oi"]=1,["note"]="Underwater",["fromId"]=12347,["t"]="collect",["quest"]=6142,["count"]=10,["y"]=0.3187,["x"]=0.305,["item"]=15924,["from"]="Enraged Reef Crawler",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:49:3",["title"]="Clam Bait",["fromKind"]="npc",["sourceRouteConditions"]=true},{["itemName"]="Rackmore's Silver Key",["sourceRouteConditions"]=true,["item"]=15878,["quest"]=6161,["map"]=1443,["oi"]=1,["fromId"]=11562,["t"]="collect",["fromAlsoId"]=11563,["title"]="Claim Rackmore's Treasure!",["y"]=0.301,["x"]=0.33399999999999996,["count"]=1,["from"]="Drysnap Crawler",["note"]="Rackmore's Silver Key, from the Drysnap crabs",["fromAlso"]="Drysnap Pincer",["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:49:4"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:49",["text"]="Clam beds",["sourceRouteConditions"]=true,["detail"]="West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a Soft-shelled Clam. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry Rackmore's Silver Key, about one in seven."},{["goals"]={{["itemName"]="Rackmore's Golden Key",["sourceRouteConditions"]=true,["item"]=15881,["fromRank"]=4,["quest"]=6161,["map"]=1443,["oi"]=2,["fromId"]=14229,["t"]="collect",["y"]=0.21850000000000003,["x"]=0.3872,["title"]="Claim Rackmore's Treasure!",["from"]="Accursed Slitherblade",["note"]="Rackmore's Golden Key, from the Slitherblade naga",["count"]=1,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:50:1"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:50",["text"]="Sar'theris Strand",["sourceRouteConditions"]=true,["detail"]="Keep north to Sar'theris Strand for Rackmore's Golden Key: any Slitherblade can drop it.\nCareful: the Myrmidons (34-35) hold the beach's northern half with the Sea Witches and Oracles (34-36, casters), up to two over you at 33: work the Naga and Sorceresses (32-33) of the southern half until the key drops, and leave the north for the second Desolace visit, at 38."},{["goals"]={{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:51:1",["t"]="turnin",["y"]=0.087,["x"]=0.3,["title"]="Claim Rackmore's Treasure!",["objName"]="Rackmore's Chest",["quest"]=6161,["object"]=177786}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:51",["text"]="Rackmore's Chest",["sourceRouteConditions"]=true,["detail"]="Swim out to Ranazjar Isle off the far northern tip: Rackmore's Chest stands on the shore beside the Serpent Statue. Open it with both keys; leave the statue alone."},{["goals"]={{["map"]=1443,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:52:1",["t"]="kill",["npc"]=4670,["y"]=0.16649999999999998,["x"]=0.7092,["title"]="Befouled by Satyr",["lvl"]=32,["target"]="Hatefury Rogue",["count"]=7,["quest"]=1434,["sourceRouteConditions"]=true},{["map"]=1443,["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:52:2",["t"]="kill",["npc"]=4672,["count"]=7,["y"]=0.20120000000000002,["x"]=0.7152,["title"]="Befouled by Satyr",["lvl"]=32,["target"]="Hatefury Felsworn",["quest"]=1434,["spread"]=true,["sourceRouteConditions"]=true},{["map"]=1443,["oi"]=3,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:52:3",["t"]="kill",["npc"]=4673,["count"]=7,["y"]=0.1888,["x"]=0.7225,["title"]="Befouled by Satyr",["lvl"]=33,["target"]="Hatefury Betrayer",["quest"]=1434,["spread"]=true,["sourceRouteConditions"]=true},{["map"]=1443,["oi"]=4,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:52:4",["t"]="kill",["npc"]=4675,["y"]=0.19190000000000002,["x"]=0.7228,["title"]="Befouled by Satyr",["lvl"]=33,["target"]="Hatefury Hellcaller",["count"]=7,["quest"]=1434,["sourceRouteConditions"]=true},{["map"]=1443,["optional"]=true,["oi"]=3,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:52:5",["t"]="kill",["npc"]=4674,["y"]=0.20329999999999998,["x"]=0.7528,["title"]="Hate the Hatefury",["target"]="Hatefury Shadowstalker",["count"]=2,["quest"]=97265,["sourceRouteConditions"]=true},{["map"]=1443,["optional"]=true,["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:52:6",["t"]="kill",["npc"]=4675,["y"]=0.1985,["x"]=0.7602,["title"]="Hate the Hatefury",["target"]="Hatefury Hellcaller",["count"]=2,["quest"]=97265,["sourceRouteConditions"]=true},{["map"]=1443,["optional"]=true,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:52:7",["t"]="kill",["npc"]=4671,["y"]=0.24100000000000002,["x"]=0.7794,["title"]="Hate the Hatefury",["note"]="Hatefury Trickster, on the way south",["target"]="Hatefury Trickster",["count"]=2,["quest"]=97265,["sourceRouteConditions"]=true},{["map"]=1443,["optional"]=true,["oi"]=4,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:52:8",["t"]="kill",["npc"]=4672,["y"]=0.24350000000000002,["x"]=0.7444,["title"]="Hate the Hatefury",["count"]=2,["target"]="Hatefury Felsworn",["quest"]=97265,["spread"]=true,["sourceRouteConditions"]=true},{["map"]=1443,["optional"]=true,["oi"]=5,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:52:9",["t"]="kill",["npc"]=4670,["y"]=0.2366,["x"]=0.7529,["title"]="Hate the Hatefury",["count"]=2,["target"]="Hatefury Rogue",["quest"]=97265,["spread"]=true,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:52",["text"]="Sargeron",["sourceRouteConditions"]=true,["detail"]="Head east past Thunder Axe Fortress and along the northern hills to the satyrs' ruins of Sargeron. Kill every kind you meet for Aka'rai; the Shadowstalkers walk unseen.\nCareful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them."},{["goals"]={{["map"]=1443,["itemName"]="Khan Dez'hepah's Head",["oi"]=1,["count"]=1,["fromId"]=5600,["t"]="collect",["quest"]=1365,["lvl"]=35,["y"]=0.418,["x"]=0.732,["item"]=6066,["from"]="Khan Dez'hepah",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:53:1",["title"]="Khan Dez'hepah",["fromKind"]="npc",["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:53",["text"]="Khan Dez'hepah",["sourceRouteConditions"]=true,["detail"]="South to Kolkar Village. Khan Dez'hepah (35) walks among the tents on the east side with a Battle Lord or two (32-33): clear around him, then pull him alone at full health.\nCareful: Kolkar Battle Lords call nearby allies within 30 yd once they fall to 20% health."},{["goals"]={{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:54:1",["t"]="turnin",["npc"]=5641,["npcName"]="Takata Steelblade",["x"]=0.5257000000000001,["title"]="Befouled by Satyr",["quest"]=1434,["y"]=0.5439},{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:54:2",["t"]="turnin",["npc"]=4498,["npcName"]="Maurin Bonesplitter",["x"]=0.5225,["title"]="The Burning of Spirits",["quest"]=1435,["y"]=0.5344},{["map"]=1443,["optional"]=true,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:54:3",["t"]="turnin",["npc"]=4498,["npcName"]="Maurin Bonesplitter",["x"]=0.5225,["title"]="The Corrupter",["quest"]=1480,["y"]=0.5344},{["map"]=1443,["preAll"]={1434,1435},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:54:4",["t"]="accept",["npc"]=5641,["y"]=0.5439,["x"]=0.5257000000000001,["title"]="Alliance Relations",["note"]="Takata Steelblade: for Keldran in Orgrimmar, next guide",["npcName"]="Takata Steelblade",["qlvl"]=33,["quest"]=1436,["minLevel"]=30},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:54:5",["text"]="Takata Steelblade's next errand sends you after a demon lord with an elite guard: skip it.",["sourceRouteConditions"]=true,["t"]="note"},{["map"]=1443,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:54:6",["t"]="turnin",["npc"]=5395,["npcName"]="Felgur Twocuts",["x"]=0.5619,["title"]="Khan Dez'hepah",["quest"]=1365,["y"]=0.5957},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:goal:54:7",["text"]="Felgur Twocuts now offers Centaur Bounty: the second Desolace visit, at 38, takes it on its way to the Valley of Spears.",["sourceRouteConditions"]=true,["t"]="note"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/30-40/02-thousand-needles:step:54",["text"]="Ghost Walker Post",["sourceRouteConditions"]=true,["detail"]="South-west down the road to the post."},{["goals"]={{["map"]=1443,["optional"]=true,["sourceRouteCondi