uteConditions"]=true,["id"]="forever/horde/40-50/01-stranglethorn-vale:30:1",["t"]="accept",["npc"]=1776,["npcName"]="Magtoor",["x"]=0.25980000000000003,["title"]="Draenethyst Crystals",["y"]=0.314,["qlvl"]=35,["quest"]=1389,["minLevel"]=30}},["id"]="forever/horde/40-50/01-stranglethorn-vale:30",["text"]="Into the Swamp of Sorrows",["sourceRouteConditions"]=true,["detail"]="Follow the road east from Duskwood through Deadwind Pass into the swamp. Magtoor waits at the Harborage, the draenei camp just off the road where it comes in from Deadwind Pass."},{["goals"]={{["map"]=1435,["note"]="Dar, inside",["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/01-stranglethorn-vale:31:3",["t"]="accept",["npc"]=5591,["npcName"]="Dar",["x"]=0.447,["title"]="Lack of Surplus",["y"]=0.5721,["qlvl"]=40,["quest"]=698,["minLevel"]=35},{["map"]=1435,["note"]="Dar, inside",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01-stranglethorn-vale:goal:59:2",["t"]="accept",["npc"]=5591,["npcName"]="Dar",["x"]=0.447,["title"]="Fresh Meat",["y"]=0.5721,["qlvl"]=44,["quest"]=1430,["minLevel"]=35},{["map"]=1435,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/01-stranglethorn-vale:31:1",["t"]="getfp",["npc"]=6026,["npcName"]="Breyk",["x"]=0.4607,["location"]="Stonard",["y"]=0.5483,["node"]=56,["area"]=75},{["map"]=1435,["note"]="Helgrum the Swift, upstairs",["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/01-stranglethorn-vale:31:2",["t"]="turnin",["npc"]=1442,["npcName"]="Helgrum the Swift",["x"]=0.47740000000000005,["title"]="Report to Helgrum",["quest"]=1420,["y"]=0.552},{["map"]=1435,["note"]="Fel'zerul, on the top floor",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01-stranglethorn-vale:goal:59:5",["t"]="accept",["npc"]=1443,["npcName"]="Fel'zerul",["x"]=0.4793,["title"]="Pool of Tears",["y"]=0.5478000000000001,["qlvl"]=43,["quest"]=1424,["minLevel"]=38}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01-stranglethorn-vale:step:59",["text"]="Stonard",["sourceRouteConditions"]=true,["detail"]="Head east to Stonard, in the reeds south of the road."},{["goals"]={{["itemName"]="Unprepared Sawtooth Flank",["sourceRouteConditions"]=true,["item"]=6169,["quest"]=698,["map"]=1435,["carriedTo"]="forever/horde/40-50/03-feralas",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01-stranglethorn-vale:goal:60:1",["fromId"]=1082,["fromAlso"]="Sawtooth Snapper",["t"]="collect",["spread"]=true,["y"]=0.5599000000000001,["x"]=0.536,["title"]="Lack of Surplus",["from"]="Sawtooth Crocolisk",["lvl"]=42,["count"]=8,["fromKind"]="npc",["fromAlsoId"]=1087}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01-stranglethorn-vale:step:60",["text"]="Sawtooth crocolisks",["sourceRouteConditions"]=true,["detail"]="The crocolisks wallow in the pools around Galen Goodward's camp and south towards Stonard; about one in four drops a flank."},{["goals"]={{["map"]=1435,["x"]=0.5489999999999999,["sourceRouteConditions"]=true,["y"]=0.341,["target"]="Noboru the Cudgel",["t"]="kill",["npc"]=5477,["id"]="forever/horde/40-50/01-stranglethorn-vale:34:1"},{["map"]=1435,["itemName"]="Noboru's Cudgel",["sourceRouteConditions"]=true,["fromId"]=5477,["t"]="collect",["y"]=0.341,["x"]=0.5489999999999999,["item"]=6196,["from"]="Noboru the Cudgel",["fromKind"]="npc",["id"]="forever/horde/40-50/01-stranglethorn-vale:34:2"},{["itemName"]="Noboru's Cudgel",["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/01-stranglethorn-vale:34:3",["t"]="accept",["title"]="Noboru the Cudgel",["qlvl"]=39,["minLevel"]=29,["quest"]=1392,["item"]=6196}},["id"]="forever/horde/40-50/01-stranglethorn-vale:34",["text"]="Noboru the Cudgel",["sourceRouteConditions"]=true,["detail"]="Noboru wanders the clearing south-west of the Fallow Sanctuary; his cudgel starts a quest."},{["goals"]={{["map"]=1435,["itemName"]="Draenethyst Crystal",["oi"]=1,["fromId"]=22550,["t"]="collect",["title"]="Draenethyst Crystals",["fromKind"]="object",["y"]=0.30079999999999996,["x"]=0.5509000000000001,["count"]=6,["from"]="Draenethyst Crystals",["id"]="forever/horde/40-50/01-stranglethorn-vale:32:1",["item"]=6071,["quest"]=1389,["sourceRouteConditions"]=true}},["id"]="forever/horde/40-50/01-stranglethorn-vale:32",["text"]="Draenethyst crystals",["sourceRouteConditions"]=true,["detail"]="Head north-east to the Fallow Sanctuary. The crystals stand along the way up to Galen Goodward's cage."},{["goals"]={{["map"]=1435,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01-stranglethorn-vale:goal:63:1",["t"]="accept",["npc"]=5391,["npcName"]="Galen Goodward",["x"]=0.6547,["escort"]=true,["title"]="Galen's Escape",["y"]=0.1816,["qlvl"]=38,["quest"]=1393,["minLevel"]=30},{["escort"]=true,["title"]="Galen's Escape",["quest"]=1393,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01-stranglethorn-vale:goal:63:2",["t"]="complete",["objs"]={{["count"]=1,["text"]="Escort Galen out of the Fallow Sanctuary."}},["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01-stranglethorn-vale:step:63",["text"]="Galen's Escape",["sourceRouteConditions"]=true,["detail"]="Galen Goodward is held in the Fallow Sanctuary in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."},{["goals"]={{["map"]=1435,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/01-stranglethorn-vale:35:1",["t"]="turnin",["y"]=0.39759999999999995,["x"]=0.4781,["title"]="Galen's Escape",["objName"]="Galen's Strongbox",["quest"]=1393,["object"]=32569}},["id"]="forever/horde/40-50/01-stranglethorn-vale:35",["text"]="Galen's Strongbox",["sourceRouteConditions"]=true,["detail"]="His strongbox waits at his old camp north of Stonard, on the way back west."},{["goals"]={{["map"]=1435,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/01-stranglethorn-vale:37:1",["t"]="turnin",["npc"]=1776,["npcName"]="Magtoor",["x"]=0.25980000000000003,["title"]="Noboru the Cudgel",["quest"]=1392,["y"]=0.314},{["map"]=1435,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/01-stranglethorn-vale:37:2",["t"]="turnin",["npc"]=1776,["npcName"]="Magtoor",["x"]=0.25980000000000003,["title"]="Draenethyst Crystals",["quest"]=1389,["y"]=0.314}},["id"]="forever/horde/40-50/01-stranglethorn-vale:37",["text"]="Harborage",["sourceRouteConditions"]=true,["detail"]="Head west along the road to the draenei camp at the Harborage, near the way in from Deadwind Pass. Lack of Surplus goes to Tok'Kar at Misty Reed Post on the next swamp visit: keep the flanks."}}},{["revision"]="b753c783be39ccf9c91a94b1bfcb67ce01932d52",["source"]="Polestar GPL-3.0; simulation-derived Forever route",["zone"]=2548,["id"]="polestar:forever/horde/40-50/01b-riverglades",["next"]="polestar:forever/horde/40-50/02-feralas",["max"]=44,["min"]=41,["availability"]="source-listed",["name"]="Riverglades (41-44)",["faction"]="Horde",["category"]="Leveling",["zoneName"]="Riverglades",["refreshRevision"]="forever-20261117-b753c783",["steps"]={{["goals"]={{["map"]=1435,["x"]=0.461,["sourceRouteConditions"]=true,["y"]=0.547,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:1:1",["t"]="goto",["text"]="Stonard flight master",["soloWhen"]={{["name"]="Kargath",["node"]=21,["k"]="taxi"},{["name"]="Swamp of Sorrows",["k"]="zone",["area"]=8}}},{["area"]=340,["sourceRouteConditions"]=true,["location"]="Kargath",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:1:2",["t"]="fly",["node"]=21,["soloWhen"]={{["name"]="Kargath",["node"]=21,["k"]="taxi"},{["name"]="Swamp of Sorrows",["k"]="zone",["area"]=8}}}},["detail"]="The Riverglades lie south of the Badlands. Ride east from the Harborage to Stonard and fly to Kargath: the way down into the zone starts there.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:1",["text"]="Fly to Kargath",["sourceRouteConditions"]=true,["soloWhen"]={{["name"]="Kargath",["node"]=21,["k"]="taxi"},{["name"]="Swamp of Sorrows",["k"]="zone",["area"]=8}}},{["goals"]={{["map"]=1418,["x"]=0.55,["sourceRouteConditions"]=true,["y"]=0.93,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:2:1",["t"]="goto",["text"]="Into the Riverglades",["soloWhen"]={{["name"]="Kargath",["node"]=21,["k"]="taxi"},{["neg"]=true,["name"]="Riverglades",["k"]="zone",["area"]=16591}}},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:2:2",["t"]="goto",["soloWhen"]={{["name"]="Kargath",["node"]=21,["k"]="taxi"},{["neg"]=true,["name"]="Riverglades",["k"]="zone",["area"]=16591}},["y"]=0.299,["x"]=0.32,["location"]="Riverglades",["area"]=16591}},["detail"]="New in Forever: this guide follows what players did in the Riverglades. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nFrom Kargath, ride south-east across the Badlands to the zone's southern edge: the pass of Twilight's Shroud leads down into the Riverglades. Rog'mar, the Horde's fort, stands in the middle of the zone, east along the valley.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:2",["text"]="Into the Riverglades",["sourceRouteConditions"]=true,["soloWhen"]={{["name"]="Kargath",["node"]=21,["k"]="taxi"},{["neg"]=true,["name"]="Riverglades",["k"]="zone",["area"]=16591}}},{["goals"]={{["area"]=484,["sourceRouteConditions"]=true,["location"]="Freewind Post",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:3:1",["t"]="fly",["node"]=30,["soloWhen"]={{["neg"]=true,["name"]="Kargath",["node"]=21,["k"]="taxi"},{["neg"]=true,["name"]="Riverglades",["k"]="zone",["area"]=16591}}}},["detail"]="New in Forever: this guide follows what players did in the Riverglades. If a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nThe Riverglades lie across the sea from Tanaris: a goblin boat sails from Steamwheedle Port, north-east of Gadgetzan, to Powderfuse Port. Fly to Freewind Post in Thousand Needles and head south-east through the Shimmering Flats to Gadgetzan. (If you already know Kargath in the Badlands, the way in through Twilight's Shroud works too.)",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:3",["text"]="Fly to Freewind Post",["sourceRouteConditions"]=true,["soloWhen"]={{["neg"]=true,["name"]="Kargath",["node"]=21,["k"]="taxi"},{["neg"]=true,["name"]="Riverglades",["k"]="zone",["area"]=16591}}},{["goals"]={{["map"]=1446,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:4:1",["t"]="getfp",["npc"]=7824,["soloWhen"]={{["neg"]=true,["name"]="Kargath",["node"]=21,["k"]="taxi"},{["neg"]=true,["name"]="Riverglades",["k"]="zone",["area"]=16591}},["npcName"]="Bulkrek Ragefist",["x"]=0.516,["location"]="Gadgetzan",["y"]=0.2544,["node"]=40,["area"]=976}},["detail"]="Learn Gadgetzan's flight path: it saves the ride next time.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:4",["text"]="Gadgetzan",["sourceRouteConditions"]=true,["soloWhen"]={{["neg"]=true,["name"]="Kargath",["node"]=21,["k"]="taxi"},{["neg"]=true,["name"]="Riverglades",["k"]="zone",["area"]=16591}}},{["goals"]={{["map"]=1446,["x"]=0.6757,["sourceRouteConditions"]=true,["y"]=0.231,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:5:1",["t"]="goto",["text"]="Boat to Powderfuse Port",["soloWhen"]={{["neg"]=true,["name"]="Kargath",["node"]=21,["k"]="taxi"},{["neg"]=true,["name"]="Riverglades",["k"]="zone",["area"]=16591}}}},["detail"]="Steamwheedle Port is on the coast north-east of Gadgetzan: wait on the pier for the goblin boat to Powderfuse Port.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:5",["text"]="Boat to Powderfuse Port",["sourceRouteConditions"]=true,["soloWhen"]={{["neg"]=true,["name"]="Kargath",["node"]=21,["k"]="taxi"},{["neg"]=true,["name"]="Riverglades",["k"]="zone",["area"]=16591}}},{["goals"]={{["map"]=2548,["note"]="Frazzlespark's Crate: for Krom'rosh in Rog'mar",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:6:1",["t"]="accept",["npc"]=255897,["soloWhen"]={{["neg"]=true,["name"]="Kargath",["node"]=21,["k"]="taxi"}},["npcName"]="Friz Frazzlespark",["x"]=0.7709999999999999,["title"]="Frazzlespark's Crate",["y"]=0.529,["qlvl"]=36,["quest"]=95062,["minLevel"]=36}},["detail"]="New in Forever: if a step is wrong, tell us on Polestar's Discord or GitHub and name the step.\nFriz Frazzlespark keeps a stall at the west end of the docks. The port's other jobs are for later in this guide: this crate goes to the Horde's fort.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:6",["text"]="Powderfuse Port",["sourceRouteConditions"]=true,["soloWhen"]={{["neg"]=true,["name"]="Kargath",["node"]=21,["k"]="taxi"}}},{["goals"]={{["map"]=2548,["note"]="Gaseous Gold",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:7:1",["t"]="accept",["npc"]=263367,["soloWhen"]={{["neg"]=true,["name"]="Kargath",["node"]=21,["k"]="taxi"}},["npcName"]="Sleebo Fizzlespout",["x"]=0.6809999999999999,["title"]="Gaseous Gold",["y"]=0.486,["qlvl"]=38,["quest"]=96063,["minLevel"]=36}},["detail"]="West up the road from the port: Sleebo Fizzlespout has his workshop on the hill. The gas vents are in the marsh south-west of it, on your first hunt for Neza Bloodsnout.",["id"]="refresh:forever-