},["npc"]=258031,["soloWhen"]={{["k"]="group",["q"]=94533}},["npcName"]="Neza Bloodsnout",["qlvl"]=40,["quest"]=94533,["map"]=2548,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:21:1",["t"]="accept",["xp"]=3150,["y"]=0.478,["x"]=0.605,["title"]="Snargl's Snout",["pre"]={96109},["closedBy"]={94679},["minLevel"]=36}},["detail"]="Snargl is an elite gnoll (level 40) who roams the south-western camps of the Bristle Hills: grouping up is advised.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:21",["text"]="Snargl's Snout",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="group",["q"]=94533}}},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:22",["text"]="Kreza Darkthorn",["goals"]={{["map"]=2548,["note"]="Bristle Hills Bandits",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:22:1",["t"]="accept",["npc"]=256657,["y"]=0.4597,["x"]=0.5992000000000001,["title"]="Bristle Hills Bandits",["npcName"]="Kreza Darkthorn",["pre"]={96109},["qlvl"]=38,["quest"]=94535,["minLevel"]=36}},["sourceRouteConditions"]=true},{["goals"]={{["itemName"]="Woodworker's Axe",["sourceRouteConditions"]=true,["fromFaction"]="A",["item"]=263972,["quest"]=93788,["map"]=2548,["oi"]=1,["fromId"]=256434,["t"]="collect",["y"]=0.5514,["x"]=0.4416,["title"]="Borrowed Blades",["lvl"]=38,["from"]="Turner's Mill Lumberjack",["count"]=10,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:23:1"},{["map"]=2548,["itemName"]="Wood Bundle",["sourceRouteConditions"]=true,["fromId"]=645516,["t"]="collect",["y"]=0.628,["x"]=0.392,["item"]=271629,["from"]="Peasant Woodpile",["note"]="Wood Bundle, from the Peasant Woodpiles",["fromKind"]="object",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:23:2"},{["map"]=2548,["itemName"]="Wood Bundle",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:23:3",["t"]="use",["y"]=0.628,["x"]=0.392,["title"]="Fetch 'n' Fletch",["note"]="Wood Bundle: fletch it into Makeshift Stickin' Spears",["item"]=271629,["quest"]=95951,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:23",["text"]="Turner's Logging Camp",["sourceRouteConditions"]=true,["detail"]="South-west across the river to the Alliance lumber camp. The lumberjacks carry the axes. Loot Wood Bundles from the Peasant Woodpiles around the camp and use them to fletch Makeshift Stickin' Spears. Ghostmaw, an elite (level 42), prowls the river by the camp: if he comes your way, back off and let him pass."},{["goals"]={{["map"]=2548,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:24:1",["t"]="kill",["npc"]=255770,["count"]=8,["y"]=0.6,["x"]=0.34299999999999997,["title"]="Gnoll Infestation",["lvl"]=37,["target"]="Redridge Mystic",["quest"]=94532,["spread"]=true,["sourceRouteConditions"]=true},{["map"]=2548,["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:24:2",["t"]="kill",["npc"]=255772,["count"]=8,["y"]=0.6009,["x"]=0.3432,["title"]="Gnoll Infestation",["lvl"]=37,["target"]="Redridge Trapper",["quest"]=94532,["spread"]=true,["sourceRouteConditions"]=true},{["map"]=2548,["oi"]=3,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:24:3",["t"]="kill",["npc"]=255769,["count"]=6,["y"]=0.6124,["x"]=0.3361,["title"]="Gnoll Infestation",["lvl"]=38,["target"]="Redridge Brute",["quest"]=94532,["spread"]=true,["sourceRouteConditions"]=true},{["map"]=2548,["itemName"]="Stolen Ore",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:24:4",["t"]="collect",["title"]="Bristle Hills Bandits",["y"]=0.6124,["x"]=0.3361,["count"]=40,["lvl"]=38,["spread"]=true,["item"]=265358,["quest"]=94535,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:24",["text"]="The Bristle Hills",["sourceRouteConditions"]=true,["detail"]="West into the Bristle Hills: the Redridge gnolls camp along the slopes and carry the stolen ore. Work south-west through their camps.\nCareful: Snargl, an elite gnoll (level 40), roams the south-western camps: pull the gnolls away from him."},{["goals"]={{["itemName"]="Snargl's Snout",["sourceRouteConditions"]=true,["group"]={["kind"]="elite",["rank"]=1,["lvl"]=40},["soloWhen"]={{["k"]="group",["q"]=94533}},["item"]=265357,["fromRank"]=1,["quest"]=94533,["map"]=2548,["oi"]=1,["fromId"]=255906,["t"]="collect",["y"]=0.732,["x"]=0.161,["title"]="Snargl's Snout",["lvl"]=40,["from"]="Snargl",["count"]=1,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:25:1"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:25",["text"]="Snargl",["sourceRouteConditions"]=true,["soloWhen"]={{["k"]="group",["q"]=94533}}},{["goals"]={{["map"]=2548,["note"]="Clear 'em Out",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:26:1",["t"]="accept",["npc"]=262399,["npcName"]="Gelinda Coppergleam",["x"]=0.302,["title"]="Clear 'em Out",["y"]=0.6920000000000001,["qlvl"]=42,["quest"]=95792,["minLevel"]=36},{["map"]=2548,["note"]="Proof of Profit",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:26:2",["t"]="accept",["npc"]=262399,["npcName"]="Gelinda Coppergleam",["x"]=0.302,["title"]="Proof of Profit",["y"]=0.6920000000000001,["qlvl"]=42,["quest"]=95934,["minLevel"]=36}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:26",["text"]="Gelinda Coppergleam",["sourceRouteConditions"]=true,["detail"]="South-east out of the hills: Gelinda Coppergleam, a prospector who deals with both sides, has camped by the Cinderscale dragonkin's hollow."},{["goals"]={{["map"]=2548,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:27:1",["t"]="kill",["npc"]=262473,["y"]=0.722,["x"]=0.3,["title"]="Clear 'em Out",["lvl"]=40,["target"]="Cinderscale Whelp",["count"]=8,["quest"]=95792,["sourceRouteConditions"]=true},{["map"]=2548,["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:27:2",["t"]="kill",["npc"]=262477,["y"]=0.731,["x"]=0.29600000000000004,["title"]="Clear 'em Out",["lvl"]=42,["target"]="Cinderscale Warrior",["count"]=4,["quest"]=95792,["sourceRouteConditions"]=true},{["map"]=2548,["itemName"]="Cubic Draconia",["oi"]=1,["fromId"]=648590,["group"]={["rank"]=2,["kind"]="elite",["near"]=true,["lvl"]=43},["t"]="collect",["fromKind"]="object",["item"]=271611,["y"]=0.733,["x"]=0.3,["title"]="Proof of Profit",["from"]="Cubic Draconia",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:27:3",["count"]=1,["quest"]=95934,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:27",["text"]="The Cinderscale hollow",["sourceRouteConditions"]=true,["detail"]="The whelps nest all over the hollow; the warriors guard its back, by the Cubic Draconia. The warriors are level 41-42: pull them one at a time. Scaldaron, a rare elite drake, can be up here too: leave him be unless you have a group."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:28",["text"]="Gelinda Coppergleam",["goals"]={{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:28:1",["t"]="turnin",["npc"]=262399,["npcName"]="Gelinda Coppergleam",["x"]=0.302,["title"]="Clear 'em Out",["quest"]=95792,["y"]=0.6920000000000001},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:28:2",["t"]="turnin",["npc"]=262399,["npcName"]="Gelinda Coppergleam",["x"]=0.302,["title"]="Proof of Profit",["quest"]=95934,["y"]=0.6920000000000001}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=2548,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:29:1",["t"]="kill",["npc"]=256383,["y"]=0.767,["x"]=0.42090000000000005,["title"]="A Message in Blood",["lvl"]=36,["target"]="Meadowsbrook Farmhand",["count"]=12,["quest"]=93786,["sourceRouteConditions"]=true},{["map"]=2548,["itemName"]="Feed Satchel",["oi"]=1,["fromId"]=616740,["t"]="collect",["title"]="Food for the Taking",["fromKind"]="object",["y"]=0.7979999999999999,["x"]=0.446,["count"]=6,["from"]="Feed Satchel",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:29:2",["item"]=262640,["quest"]=93787,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:step:29",["text"]="Meadowsbrook",["sourceRouteConditions"]=true,["detail"]="East to Meadowsbrook, the Alliance farm by the river: the farmhands work the fields and the feed satchels lie by the barns. Southern Watch, the Alliance outpost on the road, has guards: pass south of it.\nCareful: Ghostmaw, an elite (level 42), hunts along the river by the farm: keep an eye on the riverbank."},{["goals"]={{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:30:1",["t"]="turnin",["npc"]=263190,["npcName"]="Tan'jani",["x"]=0.5813,["title"]="Fetch 'n' Fletch",["quest"]=95951,["y"]=0.4532},{["map"]=2548,["note"]="Stick 'Em",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:30:2",["t"]="accept",["npc"]=263190,["y"]=0.4532,["x"]=0.5813,["title"]="Stick 'Em",["npcName"]="Tan'jani",["pre"]={95951},["qlvl"]=39,["quest"]=95955,["minLevel"]=36},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:30:3",["t"]="turnin",["npc"]=256418,["npcName"]="Krom'rosh",["x"]=0.5937,["title"]="A Message in Blood",["quest"]=93786,["y"]=0.456},{["map"]=2548,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:30:4",["t"]="turnin",["npc"]=256418,["npcName"]="Krom'rosh",["x"]=0.5937,["title"]="Food for the Taking",["quest"]=93787,["y"]=0.456},{["map"]=2548,["note"]="A Gift From Our Enemies",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:30:5",["t"]="accept",["npc"]=256418,["y"]=0.456,["x"]=0.5937,["title"]="A Gift From Our Enemies",["npcName"]="Krom'rosh",["pre"]={93787},["qlvl"]=36,["quest"]=94480,["minLevel"]=36},{["map"]=2548,["preAll"]={93786,93787},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:30:6",["t"]="accept",["npc"]=256418,["npcName"]="Krom'rosh",["x"]=0.5937,["title"]="Show Them How It's Done",["note"]="Show Them How It's Done",["y"]=0.456,["qlvl"]=39,["quest"]=94483,["minLevel"]=36},{["map"]=2548,["note"]="Gorg, by the cook fire",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:30:7",["t"]="turnin",["npc"]=256655,["npcName"]="Gorg",["x"]=0.5865,["title"]="A Gift From Our Enemies",["quest"]=94480,["y"]=0.4457},{["map"]=2548,["note"]="A Serving of Strength",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/01b-riverglades:goal:30:8",["t"]="accept",["npc"]=256655,["y"]=0.445