d"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:goal:62:3",["t"]="kill",["npc"]=5236,["y"]=0.6328,["x"]=0.6,["title"]="The Ogres of Feralas",["lvl"]=45,["target"]="Gordunni Shaman",["count"]=10,["quest"]=2980,["sourceRouteConditions"]=true},{["map"]=1444,["itemName"]="Gordunni Orb",["oi"]=1,["count"]=1,["fromId"]=5239,["t"]="collect",["quest"]=2979,["lvl"]=46,["y"]=0.6724,["x"]=0.6027,["item"]=9371,["from"]="Gordunni Mage-Lord",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:goal:62:4",["title"]="Dark Ceremony",["fromKind"]="npc",["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:step:62",["text"]="Ruins of Isildien: kill these as you meet them",["sourceRouteConditions"]=true,["detail"]="Ride west from the hive to the ogre ruins below Feral Scar Vale. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb.\nCareful: the Mage-Lords (45-46) and the Shamans cast from range and the ruins are packed: pull one at a time from the edge."},{["goals"]={{["itemName"]="Thick Yeti Hide",["sourceRouteConditions"]=true,["item"]=8973,["quest"]=2822,["map"]=1444,["oi"]=1,["fromId"]=5292,["t"]="collect",["fromAlsoId"]=5293,["title"]="The Mark of Quality",["y"]=0.5881000000000001,["x"]=0.5588000000000001,["count"]=10,["lvl"]=44,["from"]="Feral Scar Yeti",["fromAlso"]="Hulking Feral Scar",["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:goal:63:1"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:step:63",["text"]="Feral Scar Vale yetis",["sourceRouteConditions"]=true,["detail"]="North-west of the ruins, the yetis den in Feral Scar Vale; every yeti there can drop a thick hide."},{["goals"]={{["map"]=1444,["itemName"]="OOX-22/FE Distress Beacon",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:goal:64:1",["t"]="collect",["y"]=0.5376,["x"]=0.5529,["item"]=8705,["lvl"]=49,["fromNpcsAt"]="1;9;9;11;13;15;2;2,12;2;9;3;4;14;5;6,10;9;6,10,9;6,9;6,10;3,4;3,4;3,4;3,4;3,4;6,10,9;6;4;7,8;4,6;7,8;3,4;3,4;8;4;4",["spread"]=true,["optional"]=true},{["optional"]=true,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/02-feralas:33:2",["t"]="accept",["title"]="Find OOX-22/FE!",["itemName"]="OOX-22/FE Distress Beacon",["qlvl"]=45,["minLevel"]=40,["quest"]=2766,["item"]=8705},{["map"]=1444,["optional"]=true,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/02-feralas:34:1",["t"]="turnin",["npc"]=7807,["npcName"]="Homing Robot OOX-22/FE",["x"]=0.5335,["title"]="Find OOX-22/FE!",["quest"]=2766,["y"]=0.557},{["map"]=1444,["optional"]=true,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:goal:64:4",["t"]="accept",["npc"]=7807,["y"]=0.557,["npcName"]="Homing Robot OOX-22/FE",["x"]=0.5335,["escort"]=true,["title"]="Rescue OOX-22/FE!",["pre"]={2766},["qlvl"]=45,["quest"]=2767,["minLevel"]=40},{["optional"]=true,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:goal:64:5",["t"]="complete",["objs"]={{["count"]=1,["text"]="Escort OOX-22/FE to the dock along the Forgotten Coast"}},["title"]="Rescue OOX-22/FE!",["carriedTo"]="forever/horde/40-50/06-azshara",["quest"]=2767,["escort"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:step:64",["text"]="Homing Robot OOX-22/FE",["sourceRouteConditions"]=true,["detail"]="Only with the distress beacon: any beast, gnoll or ogre in Feralas can drop it, about one kill in a hundred; use it to start the quest. The robot sits in a small cave on the north side of Feral Scar Vale, just north-west of the ruins. Escort it to the dock on the Forgotten Coast; yetis and gorillas ambush you on the way. Its reward waits in Booty Bay for a later visit.\nCareful: Three ambushes spawn during the escort, and the robot warns you before each one. The first is 3 yetis, just after the robot leaves the cave and climbs toward the road. The second is 3 gorillas, on the path that runs along the cliff. The third is about 4 gnolls, one of them a caster, where the route turns off toward the dock."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:step:65",["text"]="Camp Mojache",["goals"]={{["map"]=1444,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/02-feralas:31:1",["t"]="turnin",["npc"]=7875,["npcName"]="Hadoken Swiftstrider",["x"]=0.7491,["title"]="Zukk'ash Infestation",["quest"]=7730,["y"]=0.42460000000000003},{["map"]=1444,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/02-feralas:31:2",["t"]="turnin",["npc"]=7875,["npcName"]="Hadoken Swiftstrider",["x"]=0.7491,["title"]="Stinglasher",["quest"]=7731,["y"]=0.42460000000000003},{["map"]=1444,["note"]="Jangdor Swiftstrider, inside",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:goal:65:3",["t"]="turnin",["npc"]=7854,["npcName"]="Jangdor Swiftstrider",["x"]=0.7443000000000001,["title"]="The Mark of Quality",["quest"]=2822,["y"]=0.4291},{["map"]=1444,["note"]="the Rage Scar yetis, on the next visit to Feralas",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:goal:65:4",["t"]="accept",["npc"]=7854,["y"]=0.4291,["x"]=0.7443000000000001,["title"]="Improved Quality",["npcName"]="Jangdor Swiftstrider",["pre"]={2822},["qlvl"]=48,["quest"]=7734,["minLevel"]=40},{["map"]=1444,["preAll"]={7730,7731},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:goal:65:5",["t"]="accept",["npc"]=7875,["y"]=0.42460000000000003,["x"]=0.7491,["title"]="Zukk'ash Report",["note"]="Hadoken Swiftstrider: for Zilzibin Drumlore in Orgrimmar",["npcName"]="Hadoken Swiftstrider",["qlvl"]=48,["quest"]=7732,["minLevel"]=39},{["map"]=1444,["note"]="Rok Orhan walks around Camp Mojache: look inside the circle on the map",["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/02-feralas:29:7",["t"]="turnin",["npc"]=7777,["npcName"]="Rok Orhan",["x"]=0.758,["title"]="The Ogres of Feralas",["quest"]=2980,["y"]=0.43579999999999997},{["map"]=1444,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/02-feralas:29:6",["t"]="turnin",["npc"]=7777,["npcName"]="Rok Orhan",["x"]=0.758,["title"]="Dark Ceremony",["quest"]=2979,["y"]=0.43579999999999997},{["map"]=1444,["note"]="for Orgrimmar, after Shen'dralas",["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/02-feralas:29:8",["t"]="accept",["npc"]=7777,["y"]=0.43579999999999997,["x"]=0.758,["title"]="The Gordunni Orb",["npcName"]="Rok Orhan",["pre"]={2979},["qlvl"]=47,["quest"]=3002,["minLevel"]=38},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/02-feralas:goal:65:9",["text"]="Shen'dralas is next, a ride north from Camp Mojache into Desolace: keep your Orgrimmar hand-ins (Neeru, Zilzibin, Belgrom Rockmaul, Uthel'nay) for the flight there after it.",["sourceRouteConditions"]=true,["t"]="note"}},["sourceRouteConditions"]=true}}},{["revision"]="b753c783be39ccf9c91a94b1bfcb67ce01932d52",["source"]="Polestar GPL-3.0; simulation-derived Forever route",["zone"]=1444,["id"]="polestar:forever/horde/40-50/03-feralas",["next"]="polestar:forever/horde/40-50/04-tanaris",["max"]=48,["min"]=46,["availability"]="source-listed",["name"]="Feralas, Dustwallow Marsh & Swamp of Sorrows (46-48)",["faction"]="Horde",["category"]="Leveling",["zoneName"]="Feralas",["refreshRevision"]="forever-20261117-b753c783",["steps"]={{["goals"]={{["map"]=1454,["note"]="Neeru Fireblade, Cleft of Shadow",["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/03-feralas:13:3",["t"]="turnin",["npc"]=3216,["npcName"]="Neeru Fireblade",["x"]=0.4947,["title"]="A Strange Request",["quest"]=3121,["y"]