ceRouteConditions"]=true,["id"]="forever/horde/40-50/04-tanaris:2:5",["t"]="accept",["npc"]=7564,["npcName"]="Marin Noggenfogger",["x"]=0.5181,["title"]="The Thirsty Goblin",["y"]=0.2866,["qlvl"]=49,["quest"]=2605,["minLevel"]=44}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:step:3",["text"]="Gadgetzan",["sourceRouteConditions"]=true,["detail"]="The flight lands beside Tran'rek. Take the town's quests before riding west to Sandsorrow Watch."},{["goals"]={{["map"]=1446,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:goal:4:1",["t"]="accept",["npc"]=7724,["soloWhen"]={{["neg"]=true,["k"]="onquest",["q"]={992}},{["neg"]=true,["k"]="turnedin",["q"]=992}},["npcName"]="Senior Surveyor Fizzledowser",["x"]=0.5021,["title"]="Gadgetzan Water Survey",["y"]=0.2748,["qlvl"]=46,["quest"]=992,["minLevel"]=38}},["detail"]="You missed this on the route's earlier visit here: it comes first now. It is quick and opens the quests after it.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:step:4",["text"]="Senior Surveyor Fizzledowser",["sourceRouteConditions"]=true,["soloWhen"]={{["neg"]=true,["k"]="onquest",["q"]={992}},{["neg"]=true,["k"]="turnedin",["q"]=992}}},{["goals"]={{["map"]=1446,["sourceRouteConditions"]=true,["group"]={["map"]=209,["kind"]="dungeon",["name"]="Zul'Farrak"},["t"]="accept",["npc"]=7407,["soloWhen"]={{["map"]=209,["k"]="dungeon",["name"]="Zul'Farrak"}},["npcName"]="Chief Engineer Bilgewhizzle",["x"]=0.5246,["title"]="Divino-matic Rod",["y"]=0.2851,["minLevel"]=40,["qlvl"]=47,["quest"]=2768,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:goal:5:1"},{["map"]=1446,["crumbs"]={2864},["y"]=0.2676,["group"]={["map"]=209,["kind"]="dungeon",["name"]="Zul'Farrak"},["t"]="accept",["npc"]=7876,["soloWhen"]={{["map"]=209,["k"]="dungeon",["name"]="Zul'Farrak"}},["npcName"]="Tran'rek",["x"]=0.5157,["title"]="Scarab Shells",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:goal:5:2",["qlvl"]=45,["minLevel"]=40,["quest"]=2865,["sourceRouteConditions"]=true},{["map"]=1446,["sourceRouteConditions"]=true,["group"]={["map"]=209,["kind"]="dungeon",["name"]="Zul'Farrak"},["t"]="accept",["npc"]=7804,["soloWhen"]={{["map"]=209,["k"]="dungeon",["name"]="Zul'Farrak"}},["npcName"]="Trenton Lighthammer",["x"]=0.5141,["title"]="Troll Temper",["y"]=0.2875,["minLevel"]=40,["qlvl"]=45,["quest"]=3042,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:goal:5:3"}},["detail"]="For your Zul'Farrak run, after Sandsorrow Watch: Chief Engineer Bilgewhizzle, by the water tower, wants his Divino-matic Rod back; Tran'rek his scarab shells and Trenton Lighthammer Troll Temper, if you have not taken those yet.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:step:5",["text"]="Gadgetzan",["sourceRouteConditions"]=true,["soloWhen"]={{["map"]=209,["k"]="dungeon",["name"]="Zul'Farrak"}}},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:step:6",["text"]="Tanaris",["goals"]={{["map"]=1446,["x"]=0.39,["sourceRouteConditions"]=true,["y"]=0.29,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:goal:6:1",["t"]="goto",["text"]="Sandsorrow Watch",["area"]=979}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1446,["itemName"]="Untapped Dowsing Widget",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:goal:7:1",["t"]="use",["y"]=0.292,["x"]=0.39,["title"]="Gadgetzan Water Survey",["item"]=8584,["quest"]=992,["sourceRouteConditions"]=true},{["map"]=1446,["itemName"]="Tapped Dowsing Widget",["oi"]=1,["fromId"]=144052,["t"]="collect",["title"]="Gadgetzan Water Survey",["fromKind"]="object",["y"]=0.292,["x"]=0.39,["count"]=1,["from"]="Sandsorrow Watch Water Hole",["id"]="forever/horde/40-50/04-tanaris:3:1",["ite