p"]=1427,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/04-tanaris:21:4",["t"]="turnin",["y"]=0.6217,["x"]=0.6559,["title"]="Caught!",["objName"]="Wooden Outhouse",["quest"]=4449,["object"]=173265}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:step:30",["text"]="The Grimesilt Dig Site",["sourceRouteConditions"]=true,["detail"]="From Powderfuse Port, ride into the Searing Gorge by its eastern pass, then west to the dig site. The Wooden Outhouse stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 Silk Cloth (the Auction House sells it)."},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:step:31",["text"]="Searing Gorge",["goals"]={{["map"]=1427,["x"]=0.377,["sourceRouteConditions"]=true,["y"]=0.265,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/04-tanaris:goal:31:1",["t"]="goto",["text"]="Thorium Point",["area"]=1446}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/04-tanaris:22:1",["t"]="getfp",["npc"]=3305,["npcName"]="Grisha",["x"]=0.34840000000000004,["location"]="Thorium Point",["y"]=0.30870000000000003,["node"]=75,["area"]=1446},{["map"]=1427,["note"]="The Wanted/Missing/Lost & Found board",["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/04-tanaris:22:2",["t"]="accept",["y"]=0.2647,["x"]=0.3765,["title"]="STOLEN: Smithing Tuyere and Lookout's Spyglass",["objName"]="Wanted/Missing/Lost & Found",["qlvl"]=48,["minLevel"]=45,["quest"]=7728,["object"]=179827},{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/04-tanaris:22:3",["t"]="accept",["y"]=0.2647,["x"]=0.3765,["title"]="JOB OPPORTUNITY: Culling the Competition",["objName"]="Wanted/Missing/Lost & Found",["qlvl"]=48,["minLevel"]=45,["quest"]=7729,["object"]=179827},{["map"]=1427,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/04-tanaris:22:4",["t"]="accept",["npc"