le"]="A Boar's Vitality",["count"]=1,["spread"]=true,["item"]=8394,["quest"]=2583,["sourceRouteConditions"]=true},{["map"]=1419,["itemName"]="Blasted Boar Lung",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/05-the-hinterlands:goal:37:11",["t"]="collect",["title"]="A Boar's Vitality",["y"]=0.27390000000000003,["x"]=0.5227,["count"]=3,["lvl"]=53,["spread"]=true,["item"]=8392,["quest"]=2583,["sourceRouteConditions"]=true},{["map"]=1419,["itemName"]="Blasted Boar Lung",["oi"]=3,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/05-the-hinterlands:goal:37:12",["t"]="collect",["title"]="The Decisive Striker",["y"]=0.27390000000000003,["x"]=0.5227,["count"]=1,["lvl"]=53,["spread"]=true,["item"]=8392,["quest"]=2585,["sourceRouteConditions"]=true},{["map"]=1419,["itemName"]="Blasted Boar Lung",["oi"]=2,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/05-the-hinterlands:goal:37:13",["t"]="collect",["title"]="Snickerfang Jowls",["y"]=0.27390000000000003,["x"]=0.5227,["count"]=2,["lvl"]=53,["spread"]=true,["item"]=8392,["quest"]=2581,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/40-50/05-the-hinterlands:step:37",["text"]="Serpent's Coil: kill these as you meet them",["sourceRouteConditions"]=true,["detail"]="The five quests share the same parts: gather them all in one sweep. West of the road the Black Slayer vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills.\nEast of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south.\nCareful: Scorpok Stingers (50-51) use Venom Sting; Clack the Reaver adds Knockdown. Pull the Stingers one at a time."},{["goals"]={{["map"]=1419,["sourceRouteConditions"]=true,["id"]="forever/horde/40-50/05-the-hinterlands:5:4",["t"]="turnin",["npc"]=7506,["npcName"]="Bloodmage Lynnore",["x"]=0.5064,["title"]="