le"]="Augustus' Receipt Book",["quest"]=6164,["y"]=0.2637},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:goal:24:2",["text"]="Keep the termites: Mickey Levine at the Bulwark takes them on the next guide's ride into the Western Plaguelands.",["sourceRouteConditions"]=true,["t"]="note"}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1423,["x"]=0.495,["sourceRouteConditions"]=true,["y"]=0.434,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:goal:25:1",["t"]="goto",["text"]="Noxious Plaguebat",["soloWhen"]={{["op"]="<",["k"]="level",["n"]=56}}},{["map"]=1423,["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:goal:25:2",["t"]="kill",["npc"]=8601,["soloWhen"]={{["op"]="<",["k"]="level",["n"]=56}},["y"]=0.434,["x"]=0.495,["title"]="Un-Life's Little Annoyances",["lvl"]=56,["target"]="Noxious Plaguebat",["count"]=20,["quest"]=6042,["sourceRouteConditions"]=true},{["map"]=1423,["note"]="grind on Noxious Plaguebat",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:goal:25:3",["t"]="level",["soloWhen"]={{["op"]="<",["k"]="level",["n"]=56}},["npcName"]="Noxious Plaguebat",["x"]=0.4954,["lvl"]=56,["y"]=0.4336,["level"]=56,["spread"]=true,["grind"]=8601}},["detail"]="Top up here to level 56 before the Frenzied Plaguehounds of Northdale (57-58): the Noxious Plaguebats (54-56) over the fields on the way east are at your level, and Nathanos Blightcaller wants twenty of them. Or, with a group, run the Blackrock Spire dungeon (Lower) instead.",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:step:25",["text"]="Level 56",["sourceRouteConditions"]=true,["soloWhen"]={{["op"]="<",["k"]="level",["n"]=56}}},{["goals"]={{["map"]=1423,["oi"]=3,["count"]=5,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/