"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:step:54",["text"]="Fly to Marshal's Refuge",["goals"]={{["map"]=1446,["x"]=0.516,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:goal:54:1",["text"]="Gadgetzan flight master",["t"]="goto",["y"]=0.255},{["sourceRouteConditions"]=true,["location"]="Marshal's Refuge",["id"]="forever/horde/50-60/05-eastern-plaguelands:31:1",["t"]="fly",["node"]=79,["area"]=541}},["sourceRouteConditions"]=true},{["goals"]={{["map"]=1449,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:goal:55:1",["t"]="accept",["npc"]=9997,["npcName"]="Spraggle Frock",["x"]=0.4362,["title"]="Lost!",["y"]=0.085,["qlvl"]=55,["quest"]=4492,["minLevel"]=50},{["map"]=1449,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:goal:55:2",["t"]="turnin",["npc"]=8737,["npcName"]="Linken",["x"]=0.44659999999999994,["title"]="Linken's Sword",["quest"]=3914,["y"]=0.081},{["map"]=1449,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:goal:55:3",["t"]="accept",["npc"]=8737,["y"]=0.081,["x"]=0.44659999999999994,["title"]="A Gnome's Assistance",["npcName"]="Linken",["pre"]={3914},["qlvl"]=52,["quest"]=3941,["minLevel"]=47},{["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:goal:55:4",["text"]="A Gnome's Assistance goes to J.D. Collie in the cave here, on the next guide's return to Marshal's Refuge: keep it.",["sourceRouteConditions"]=true,["t"]="note"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/05-eastern-plaguelands:step:55",["text"]="Marshal's Refuge",["sourceRouteConditions"]=true,["detail"]="The flight lands at Marshal's Refuge: Spraggle Frock stands beside the f