r",["quest"]=8285,["y"]=0.6976},{["map"]=1451,["sourceRouteConditions"]=true,["id"]="forever/horde/50-60/06-silithus:9:2",["t"]="accept",["npc"]=15194,["y"]=0.6976,["x"]=0.6718999999999999,["title"]="The Twilight Lexicon",["npcName"]="Hermit Ortell",["pre"]={8285},["qlvl"]=60,["quest"]=8279,["minLevel"]=54},{["itemName"]="Rock Stalker Fang",["sourceRouteConditions"]=true,["item"]=20377,["quest"]=8278,["map"]=1451,["oi"]=3,["fromId"]=11739,["t"]="collect",["spread"]=true,["title"]="Noggle's Last Hope",["y"]=0.7426999999999999,["x"]=0.6653,["count"]=3,["from"]="Rock Stalker",["lvl"]=59,["note"]="Rock Stalker Fang from Rock Stalker, 130 yd south-west",["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/06-silithus:goal:9:3"}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/06-silithus:step:9",["text"]="Hermit Ortell",["sourceRouteConditions"]=true,["detail"]="Ride south-east to Ortell's Hideout under the Un'Goro cliffs."},{["goals"]={{["map"]=1451,["note"]="Dredge Crusher walks around Southwind Village: look inside the circle on the map",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/06-silithus:goal:10:1",["t"]="kill",["npc"]=11741,["count"]=20,["y"]=0.6308,["x"]=0.636,["title"]="Stepping Up Security",["lvl"]=58,["target"]="Dredge Crusher",["quest"]=8281,["spread"]=true,["sourceRouteConditions"]=true},{["itemName"]="Stonelash Flayer Stinger",["sourceRouteConditions"]=true,["item"]=20375,["quest"]=8278,["map"]=1451,["oi"]=1,["fromId"]=11737,["t"]="collect",["spread"]=true,["y"]=0.6663,["x"]=0.6417,["title"]="Noggle's Last Hope",["from"]="Stonelash Flayer",["count"]=3,["lvl"]=58,["fromKind"]="npc",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/50-60/06-silithus:goal:10:2"},{["itemName"]="Rock Stalker Fang",["sourceRouteConditions"]=true,["item"]=20377,["quest"]=8278,["map"]=1451,["oi"]=3,["fromId"]=11739,["t"]="collect",["spread"]=true,["y"]=0.7426999999999999