"]=1411,["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/orc/01-durotar:goal:44:2",["t"]="turnin",["npc"]=3304,["npcName"]="Master Vornal",["x"]=0.5594,["title"]="Lost in the Shadows",["quest"]=99123,["y"]=0.7439}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/orc/01-durotar:step:44",["text"]="Sen'jin Village",["sourceRouteConditions"]=true,["detail"]="Back east to Sen'jin on the way to the Echo Isles."},{["goals"]={{["map"]=1411,["itemName"]="Bloodtalon Matriarch Eggs",["oi"]=1,["fromId"]=268530,["t"]="collect",["title"]="Bloodtalon Matriarch",["fromKind"]="npc",["y"]=0.7178,["x"]=0.6881,["count"]=1,["from"]="Bloodtalon Matriarch",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/orc/01-durotar:goal:45:1",["item"]=277128,["quest"]=97223,["sourceRouteConditions"]=true},{["map"]=1411,["itemName"]="Durotar Tiger Fur",["oi"]=1,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/orc/01-durotar:goal:45:2",["t"]="collect",["title"]="Practical Prey",["y"]=0.7242000000000001,["x"]=0.6901999999999999,["count"]=4,["lvl"]=8,["spread"]=true,["item"]=4892,["quest"]=817,["sourceRouteConditions"]=true}},["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/orc/01-durotar:step:45",["text"]="Echo Isles: kill these as you meet them",["sourceRouteConditions"]=true,["detail"]="Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."},{["goals"]={{["map"]=1411,["x"]=0.655,["sourceRouteConditions"]=true,["text"]="Durotar Tiger",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/orc/01-durotar:goal:46:1",["t"]="goto",["y"]=0.83,["soloWhen"]={{["op"]="<",["k"]="level",["n"]=9}}},{["map"]=1411,["note"]="grind on Durotar Tiger",["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar: