ly"]={["classes"]={"SHAMAN"}},["detail"]="Seer Ravenfeather stands in Camp Narache. Call of Earth needs level 4, which you reach with the turn-ins here."},{["goals"]={{["map"]=1412,["itemName"]="Ritual Salve",["oi"]=1,["count"]=2,["fromId"]=2953,["t"]="collect",["quest"]=1519,["lvl"]=4,["y"]=0.7829999999999999,["x"]=0.5661,["item"]=6634,["from"]="Bristleback Shaman",["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/tauren/01-mulgore:goal:13:1",["title"]="Call of Earth",["fromKind"]="npc",["sourceRouteConditions"]=true}},["sourceRouteConditions"]=true,["id"]="refresh:forever-20261117-b753c783:polestar:forever/horde/tauren/01-mulgore:step:13",["text"]="Ritual Salve",["only"]={["classes"]={"SHAMAN"}},["detail"]="Back east to Brambleblade Ravine: the Bristleback Shamans stand among the quilboar there."},{["goals"]={{["map"]=1412,["sourceRouteConditions"]=true,["id"]="forever/horde/tauren/01-mulgore:14:1",["t"]="turnin",["npc"]=5888,["npcName"]="Seer Ravenfeather",["x"]=0.4435,["title"]="Call of Earth",["quest"]=1519,["y"]=0.7676999999999999},{["map"]=1412,["sourceRouteConditions"]=true,["id"]="forever/horde/tauren/01-mulgore:14:2",["t"]="accept",["npc"]=5888,["y"]=0.7676999999999999,["x"]=0.4435,["title"]="Call of Earth",["npcName"]="Seer Ravenfeather",["pre"]={1516,1519},["qlvl"]=4,["quest"]=1520,["minLevel"]=4},{["map"]=1412,["sourceRouteConditions"]=true,["id"]="forever/horde/tauren/01-mulgore:14:3",["t"]="turnin",["npc"]=5891,["npcName"]="Minor Manifestation of Earth",["x"]=0.5199,["title"]="Call of Earth",["quest"]=1520,["y"]=0.804},{["map"]=1412,["sourceRouteConditions"]=true,["id"]="forever/horde/tauren/01-mulgore:14:4",["t"]="accept",["npc"]=5891,["y"]=0.804,["x"]=0.5199,["title"]="Call of Earth",["npcName"]="Minor Manifestation of Earth",["pre"]={1520},["qlvl"]=4,["quest"]=1521,["minLevel"]=4},{["map"]=1412,["note"]="Seer Ravenfeather: Stoneskin Totem and your Earth Totem",["sourceRouteConditions"]=true,["id"]="forever/horde/tauren/01-mulgore:14: